const e="list-test-01",t="Listening Practice Test 1",i="standard";const n=JSON.parse(`[{"sectionNumber":1,"title":"Community Watersports Center Membership Enquiry","contextDescription":"A phone conversation between a new resident, Mark Henderson, and the receptionist at the West Bay Watersports Center.","audioScript":[{"speaker":"Receptionist","text":"Good morning! West Bay Watersports Center. How can I help you today?"},{"speaker":"Mark","text":"Hello there! I recently moved to the coast and I'm interested in joining the community sailing and paddleboard club. Could you give me some information about your membership packages?"},{"speaker":"Receptionist","text":"Certainly, sir! We offer three main tiers: Single Day Pass, Monthly Explorer, and our most popular one, the Annual Gold Pass."},{"speaker":"Mark","text":"Great. What does the Annual Gold Pass include?"},{"speaker":"Receptionist","text":"With the Annual Gold Pass, you get unlimited kayak and paddleboard rentals, plus access to our weekend sailing regattas. The regular price is four hundred and eighty pounds, but if you sign up before the fifteenth of May, it's discounted to four hundred and twenty pounds."},{"speaker":"Mark","text":"Four hundred and twenty pounds sounds very reasonable. What time do you open on Saturday mornings?"},{"speaker":"Receptionist","text":"On Saturdays and Sundays, our equipment lockers open at seven thirty in the morning, and water sessions continue until sunset, which is usually eight fifteen in the evening."},{"speaker":"Mark","text":"Wonderful. And where exactly is the center located? I know it's near the marina."},{"speaker":"Receptionist","text":"Yes, our main clubhouse is situated at forty-two Ocean Esplanade, right next to the lighthouse beacon."},{"speaker":"Mark","text":"Forty-two Ocean Esplanade. Got it. Do I need to bring my own life jacket, or is safety gear provided?"},{"speaker":"Receptionist","text":"All safety gear is provided free of charge, including certified buoyancy vests and emergency whistles. However, members must provide their own wetsuit."},{"speaker":"Mark","text":"That's fine, I already have one. And what about car parking?"},{"speaker":"Receptionist","text":"We have a secure parking compound behind the boathouse. For annual members, parking is completely free; you just need to display your blue permit on the dashboard."},{"speaker":"Mark","text":"Excellent. Could you take down my email address to send me the application form?"},{"speaker":"Receptionist","text":"Of course! What's your surname and email?"},{"speaker":"Mark","text":"My surname is Henderson, that's H-E-N-D-E-R-S-O-N, and my email is mark dot henderson ninety-two at mailhub dot com."},{"speaker":"Receptionist","text":"Thank you, Mr. Henderson. I've sent the welcome packet over to you right now."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l1-q1","questionNumber":1,"prompt":"Discounted Annual Gold Pass fee if paid before May 15: £____","correctAnswer":["420","four hundred and twenty","420 pounds"],"explanation":"Receptionist mentions: 'if you sign up before the fifteenth of May, it's discounted to four hundred and twenty pounds.'","evidence":"if you sign up before the fifteenth of May, it's discounted to four hundred and twenty pounds."},{"id":"l1-q2","questionNumber":2,"prompt":"Weekend equipment lockers open at ____ AM.","correctAnswer":["7:30","7.30","seven thirty"],"explanation":"Receptionist states: 'On Saturdays and Sundays, our equipment lockers open at seven thirty in the morning'.","evidence":"our equipment lockers open at seven thirty in the morning"},{"id":"l1-q3","questionNumber":3,"prompt":"Clubhouse address: 42 ____ Esplanade.","correctAnswer":"Ocean","explanation":"Receptionist says: 'forty-two Ocean Esplanade'.","evidence":"our main clubhouse is situated at forty-two Ocean Esplanade"},{"id":"l1-q4","questionNumber":4,"prompt":"The center is positioned immediately adjacent to the ____.","correctAnswer":["lighthouse beacon","lighthouse"],"explanation":"Receptionist says: 'right next to the lighthouse beacon.'","evidence":"right next to the lighthouse beacon."},{"id":"l1-q5","questionNumber":5,"prompt":"Safety equipment supplied free includes buoyancy vests and emergency ____.","correctAnswer":"whistles","explanation":"Receptionist specifies: 'including certified buoyancy vests and emergency whistles.'","evidence":"including certified buoyancy vests and emergency whistles."},{"id":"l1-q6","questionNumber":6,"prompt":"Item of apparel that members must supply for themselves: ____.","correctAnswer":"wetsuit","explanation":"Receptionist explains: 'However, members must provide their own wetsuit.'","evidence":"However, members must provide their own wetsuit."},{"id":"l1-q7","questionNumber":7,"prompt":"Parking location: behind the ____.","correctAnswer":"boathouse","explanation":"Receptionist states: 'secure parking compound behind the boathouse.'","evidence":"We have a secure parking compound behind the boathouse."},{"id":"l1-q8","questionNumber":8,"prompt":"Color of the dashboard parking permit: ____.","correctAnswer":"blue","explanation":"Receptionist says: 'display your blue permit on the dashboard.'","evidence":"you just need to display your blue permit on the dashboard."},{"id":"l1-q9","questionNumber":9,"prompt":"Caller's family surname: ____.","correctAnswer":"Henderson","explanation":"Caller spells out H-E-N-D-E-R-S-O-N.","evidence":"My surname is Henderson, that's H-E-N-D-E-R-S-O-N"},{"id":"l1-q10","questionNumber":10,"prompt":"Number included in the email address username: ____.","correctAnswer":["92","ninety-two"],"explanation":"Caller gives: 'mark dot henderson ninety-two'.","evidence":"my email is mark dot henderson ninety-two at mailhub dot com."}]}]},{"sectionNumber":2,"title":"Coastal Heritage Pier and Maritime Museum Tour","contextDescription":"A volunteer guide orienting visitors to the layout and facilities of the newly refurbished Victorian Heritage Pier.","audioScript":[{"speaker":"Tour Guide","text":"Good morning, ladies and gentlemen, and a warm welcome to the St. Jude Heritage Pier! Originally constructed in 1888 during the Victorian steamship boom, this historic pier has recently undergone a twelve-million-pound restoration."},{"speaker":"Tour Guide","text":"Before you set off to explore, please look at the map of the pier head displayed on the brochure in your hands. We are currently standing at the Main Entrance Turnstiles at the very foot of the pier."},{"speaker":"Tour Guide","text":"If you follow the central timber boardwalk straight ahead towards the ocean, the very first structure you will encounter on your left is the Maritime Ticket Office, labeled Location A."},{"speaker":"Tour Guide","text":"Just past the ticket office on your left, you'll see a large octagonal dome with stained glass windows. That is our famous Victorian Tea Pavilion, indicated by Location B, where traditional afternoon tea is served daily."},{"speaker":"Tour Guide","text":"Directly opposite the tea pavilion on the right-hand side of the boardwalk, marked as Location C, is the Children's Discovery Aquarium, featuring touch pools with starfish and hermit crabs."},{"speaker":"Tour Guide","text":"Continuing further down the pier towards the seaward end, the boardwalk widens into a circular observation plaza. On the eastern perimeter of this plaza, at Location D, stands the historic Lifeboat Rescue Station, which houses the restored 1910 wooden rescue vessel."},{"speaker":"Tour Guide","text":"Finally, at the absolute tip of the pier jutting out into deep water, designated as Location E, you will find the Open-Air Angling Platform, which offers panoramic views of the coastal cliffs."},{"speaker":"Tour Guide","text":"Now, a couple of quick notices regarding visitor safety. Because the pier decking is made of authentic English oak planks, high-heeled shoes and wheeled skateboards are strictly prohibited. The pier gates close automatically at nine in the evening, so please ensure you make your way back to the shore by eight forty-five."}],"questionGroups":[{"groupInstruction":"Label the map below. Choose the correct letter, A–E, and write the answers in boxes 11–15 on your answer sheet.","questionType":"diagram_label_completion","diagramSvg":"<svg viewBox='0 0 500 320' xmlns='http://www.w3.org/2000/svg' class='w-full max-w-lg mx-auto bg-slate-50 dark:bg-slate-900 rounded-xl p-2 border border-slate-200 dark:border-slate-700'><rect width='500' height='320' fill='#f0f9ff' rx='10'/><path d='M 50 160 L 450 160' stroke='#0d9488' stroke-width='36' stroke-linecap='round'/><text x='30' y='140' font-size='12' font-weight='bold' fill='#0f766e'>Entrance Turnstiles</text><rect x='100' y='70' width='60' height='45' rx='6' fill='#0284c7' stroke='#0369a1' stroke-width='2'/><text x='125' y='98' font-size='16' font-weight='bold' fill='white'>A</text><rect x='200' y='60' width='70' height='55' rx='6' fill='#0284c7' stroke='#0369a1' stroke-width='2'/><text x='230' y='94' font-size='16' font-weight='bold' fill='white'>B</text><rect x='200' y='200' width='70' height='55' rx='6' fill='#0284c7' stroke='#0369a1' stroke-width='2'/><text x='230' y='234' font-size='16' font-weight='bold' fill='white'>C</text><circle cx='380' cy='100' r='28' fill='#0284c7' stroke='#0369a1' stroke-width='2'/><text x='374' y='106' font-size='16' font-weight='bold' fill='white'>D</text><polygon points='440,160 490,120 490,200' fill='#0284c7' stroke='#0369a1' stroke-width='2'/><text x='465' y='166' font-size='16' font-weight='bold' fill='white'>E</text><text x='210' y='290' font-size='12' font-weight='bold' fill='#64748b'>Central Boardwalk</text></svg>","questions":[{"id":"l1-q11","questionNumber":11,"prompt":"Maritime Ticket Office","options":["A","B","C","D","E"],"correctAnswer":"A","explanation":"Guide states: 'the very first structure you will encounter on your left is the Maritime Ticket Office, labeled Location A.'","evidence":"the very first structure you will encounter on your left is the Maritime Ticket Office, labeled Location A."},{"id":"l1-q12","questionNumber":12,"prompt":"Victorian Tea Pavilion","options":["A","B","C","D","E"],"correctAnswer":"B","explanation":"Guide notes: 'Just past the ticket office on your left... Victorian Tea Pavilion, indicated by Location B'.","evidence":"Victorian Tea Pavilion, indicated by Location B, where traditional afternoon tea is served daily."},{"id":"l1-q13","questionNumber":13,"prompt":"Children's Discovery Aquarium","options":["A","B","C","D","E"],"correctAnswer":"C","explanation":"Guide points out: 'Directly opposite the tea pavilion on the right-hand side of the boardwalk, marked as Location C, is the Children's Discovery Aquarium'.","evidence":"marked as Location C, is the Children's Discovery Aquarium, featuring touch pools with starfish"},{"id":"l1-q14","questionNumber":14,"prompt":"Lifeboat Rescue Station","options":["A","B","C","D","E"],"correctAnswer":"D","explanation":"Guide states: 'On the eastern perimeter of this plaza, at Location D, stands the historic Lifeboat Rescue Station'.","evidence":"at Location D, stands the historic Lifeboat Rescue Station, which houses the restored 1910 wooden rescue vessel."},{"id":"l1-q15","questionNumber":15,"prompt":"Open-Air Angling Platform","options":["A","B","C","D","E"],"correctAnswer":"E","explanation":"Guide specifies: 'at the absolute tip of the pier jutting out into deep water, designated as Location E, you will find the Open-Air Angling Platform'.","evidence":"designated as Location E, you will find the Open-Air Angling Platform"}]},{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 16–20 on your answer sheet.","questionType":"multiple_choice_single","questions":[{"id":"l1-q16","questionNumber":16,"prompt":"In what year was the St. Jude Heritage Pier originally constructed?","options":["1888","1910","1928"],"correctAnswer":"A","explanation":"Guide says: 'Originally constructed in 1888 during the Victorian steamship boom'.","evidence":"Originally constructed in 1888 during the Victorian steamship boom"},{"id":"l1-q17","questionNumber":17,"prompt":"How much funding was invested in the recent restoration project?","options":["Two million pounds","Twelve million pounds","Ten million pounds"],"correctAnswer":"B","explanation":"Guide states: 'undergone a twelve-million-pound restoration.'","evidence":"undergone a twelve-million-pound restoration."},{"id":"l1-q18","questionNumber":18,"prompt":"Which item of footwear is explicitly banned on the pier?","options":["Running sneakers","Open-toed sandals","High-heeled shoes"],"correctAnswer":"C","explanation":"Guide states: 'high-heeled shoes and wheeled skateboards are strictly prohibited.'","evidence":"high-heeled shoes and wheeled skateboards are strictly prohibited."},{"id":"l1-q19","questionNumber":19,"prompt":"What wood was used for the restored pier decking planks?","options":["English oak","Scandinavian pine","Teak"],"correctAnswer":"A","explanation":"Guide mentions: 'Because the pier decking is made of authentic English oak planks'.","evidence":"Because the pier decking is made of authentic English oak planks"},{"id":"l1-q20","questionNumber":20,"prompt":"By what time should visitors start returning to shore before gates lock?","options":["8:15 PM","8:45 PM","9:00 PM"],"correctAnswer":"B","explanation":"Guide states: 'The pier gates close automatically at nine in the evening, so please ensure you make your way back to the shore by eight forty-five.'","evidence":"please ensure you make your way back to the shore by eight forty-five."}]}]},{"sectionNumber":3,"title":"Academic Seminar on Marine Microplastics Research","contextDescription":"Two environmental science students, Chloe and Sam, discussing their upcoming seminar on microplastics with Professor Davies.","audioScript":[{"speaker":"Professor","text":"Good afternoon, Chloe, Sam. Let's review the final draft of your presentation on microplastic trophic transfer."},{"speaker":"Chloe","text":"Thanks, Professor Davies. We've structured the talk into four sections: primary sources, fragmentation mechanisms, biological ingestion, and mitigation."},{"speaker":"Sam","text":"For the primary sources, I was planning to focus mainly on industrial cosmetic microbeads, but recent literature suggests synthetic textile microfibers actually account for over thirty-five percent of ocean microplastics."},{"speaker":"Professor","text":"That's a very prudent update, Sam. Every laundry wash cycle can release up to seven hundred thousand microfibers into municipal wastewater streams."},{"speaker":"Chloe","text":"And in the biological section, I looked at zooplankton. When copepods ingest non-nutritive plastic spheres, their caloric intake drops significantly, leading to decreased reproductive egg viability."},{"speaker":"Professor","text":"Excellent evidence. But what about trophic magnification? Do the toxins travel up to apex predators like seals and seabirds?"},{"speaker":"Sam","text":"Yes, we found studies examining polychlorinated biphenyls—PCBs. Because plastic particles are hydrophobic, they absorb persistent organic pollutants from surrounding seawater like sponges. When small fish consume thousands of particles, the toxic burden biomagnifies up the food chain."},{"speaker":"Professor","text":"Very thorough. Now, regarding your slide design: your current data graph on slide eight is far too crowded. You should eliminate the background gridlines and use contrasting colors for the benthic vs pelagic sample groups."},{"speaker":"Chloe","text":"Understood. I will simplify the axis labels and highlight the benthic species in amber."},{"speaker":"Professor","text":"Good. Remember that each team has strictly twenty minutes to present, followed by five minutes for faculty Q&A."}],"questionGroups":[{"groupInstruction":"Choose TWO letters, A–E. Write your answers in boxes 21 and 22 on your answer sheet.\\nWhich TWO primary findings regarding microplastics are mentioned by the students?","questionType":"multiple_choice_multi","questions":[{"id":"l1-q21","questionNumber":21,"prompt":"Key findings discussed in the seminar (Choose TWO letters)","options":["A. Synthetic clothing fibers produce more marine pollution than cosmetic beads.","B. Microplastics completely dissolve in ocean water within six months.","C. Copepod zooplankton suffer reduced reproductive fertility when ingesting plastic.","D. Freshwater rivers contain zero microplastic particles.","E. Microplastics repel all chemical pollutants in seawater."],"correctAnswer":["A","C"],"explanation":"Sam mentions synthetic microfibers account for >35% of pollution (A), and Chloe notes copepods suffer decreased reproductive egg viability (C).","evidence":"synthetic textile microfibers actually account for over thirty-five percent... caloric intake drops significantly, leading to decreased reproductive egg viability."}]},{"groupInstruction":"Who suggested the following actions? Choose the correct letter, A, B, or C, for questions 23–25.\\nA: Professor Davies\\nB: Chloe\\nC: Sam","questionType":"matching","questions":[{"id":"l1-q23","questionNumber":23,"prompt":"Include data regarding the release of microfibers during household laundry washes.","options":["A. Professor Davies","B. Chloe","C. Sam"],"correctAnswer":"A","explanation":"Professor Davies points out: 'Every laundry wash cycle can release up to seven hundred thousand microfibers'.","evidence":"Every laundry wash cycle can release up to seven hundred thousand microfibers into municipal wastewater streams."},{"id":"l1-q24","questionNumber":24,"prompt":"Highlight the chemical absorption of persistent pollutants like PCBs.","options":["A. Professor Davies","B. Chloe","C. Sam"],"correctAnswer":"C","explanation":"Sam states: 'we found studies examining polychlorinated biphenyls—PCBs. Because plastic particles are hydrophobic...'","evidence":"Yes, we found studies examining polychlorinated biphenyls—PCBs. Because plastic particles are hydrophobic, they absorb persistent organic pollutants"},{"id":"l1-q25","questionNumber":25,"prompt":"Remove distracting background gridlines from presentation slide graphs.","options":["A. Professor Davies","B. Chloe","C. Sam"],"correctAnswer":"A","explanation":"Professor Davies advises: 'You should eliminate the background gridlines and use contrasting colors'.","evidence":"You should eliminate the background gridlines and use contrasting colors for the benthic vs pelagic sample groups."}]},{"groupInstruction":"Complete the summary below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 26–30.","questionType":"summary_completion","questions":[{"id":"l1-q26","questionNumber":26,"prompt":"Microplastics absorb toxins because their surface chemical characteristic is ____.","correctAnswer":"hydrophobic","explanation":"Sam explains: 'Because plastic particles are hydrophobic, they absorb persistent organic pollutants'.","evidence":"Because plastic particles are hydrophobic, they absorb persistent organic pollutants from surrounding seawater like sponges."},{"id":"l1-q27","questionNumber":27,"prompt":"The biological buildup of contaminants across food web tiers is known as ____.","correctAnswer":["biomagnification","trophic magnification"],"explanation":"Sam mentions: 'biomagnifies up the food chain'.","evidence":"the toxic burden biomagnifies up the food chain."},{"id":"l1-q28","questionNumber":28,"prompt":"Chloe intends to color-code the benthic organism samples using ____.","correctAnswer":"amber","explanation":"Chloe says: 'I will simplify the axis labels and highlight the benthic species in amber.'","evidence":"I will simplify the axis labels and highlight the benthic species in amber."},{"id":"l1-q29","questionNumber":29,"prompt":"Maximum presentation speaking duration permitted: ____ minutes.","correctAnswer":["20","twenty"],"explanation":"Professor says: 'each team has strictly twenty minutes to present'.","evidence":"each team has strictly twenty minutes to present"},{"id":"l1-q30","questionNumber":30,"prompt":"Duration set aside for faculty questions following the talk: ____ minutes.","correctAnswer":["5","five"],"explanation":"Professor states: 'followed by five minutes for faculty Q&A.'","evidence":"followed by five minutes for faculty Q&A."}]}]},{"sectionNumber":4,"title":"University Lecture: Aerodynamic Architecture and Urban Wind Tunnels","contextDescription":"A lecture delivered by an architectural engineering professor on managing pedestrian wind microclimates around high-rise towers.","audioScript":[{"speaker":"Lecturer","text":"Welcome back to Architectural Aerodynamics. Today we turn our attention to the urban microclimate—specifically, how the geometry of high-rise structures impacts pedestrian ground-level wind speeds."},{"speaker":"Lecturer","text":"When a solitary skyscraper is erected in an open cityscape, it acts as a colossal sail. Approaching atmospheric winds, which travel significantly faster at higher altitudes due to lack of ground friction, strike the upper facade of the building. This collision creates a high-pressure stagnation zone on the windward face."},{"speaker":"Lecturer","text":"Because air naturally flows from high to low pressure, this intercepted air is driven forcefully downward along the building facade. This aerodynamic downward diversion is known as the downwash vortex. When the downwash reaches the ground plane, it rolls outwards across pedestrian footpaths at accelerating velocities, frequently exceeding twenty-five meters per second."},{"speaker":"Lecturer","text":"In addition, when tall towers are positioned close together with narrow gaps between them, they induce the Venturi effect—often called the wind tunnel effect. Compressed into constricted urban alleys, wind streamlines accelerate dramatically, ripping awnings and toppling outdoor cafe furniture."},{"speaker":"Lecturer","text":"Fortunately, architectural engineers have developed several structural countermeasures. The first design mitigation involves aerodynamic corner chamfering: carving curved or beveled edges onto building corners, which softens sharp vortex separation. Research demonstrates that chamfered corners can diminish ground wind gusts by up to thirty-two percent."},{"speaker":"Lecturer","text":"A second prominent intervention is the incorporation of through-building openings, known in engineering as porous wind slits. Rather than forcing the entire air mass downwards, these horizontal voids allow wind to flow harmlessly through upper stories. A striking example is the Shanghai World Financial Center, whose aperture near the pinnacle significantly alleviates structural vortex shedding."},{"speaker":"Lecturer","text":"Finally, at the street level, architects deploy large horizontal podiums and landscaped canopies. A broad podium extending five to eight meters from the tower perimeter acts as a physical shield, intercepting descending downwash winds before they can strike pedestrians on the sidewalk."}],"questionGroups":[{"groupInstruction":"Complete the lecture notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40 on your answer sheet.","questionType":"sentence_completion","questions":[{"id":"l1-q31","questionNumber":31,"prompt":"Winds at higher altitudes travel faster because of an absence of ____.","correctAnswer":["ground friction","friction"],"explanation":"Lecturer notes: 'due to lack of ground friction'.","evidence":"due to lack of ground friction, strike the upper facade of the building."},{"id":"l1-q32","questionNumber":32,"prompt":"Wind colliding with a building facade generates a high-pressure ____ zone.","correctAnswer":"stagnation","explanation":"Lecturer says: 'creates a high-pressure stagnation zone on the windward face.'","evidence":"creates a high-pressure stagnation zone on the windward face."},{"id":"l1-q33","questionNumber":33,"prompt":"The downward movement of high-level air to the street is termed the ____.","correctAnswer":"downwash vortex","explanation":"Lecturer states: 'downward diversion is known as the downwash vortex.'","evidence":"This aerodynamic downward diversion is known as the downwash vortex."},{"id":"l1-q34","questionNumber":34,"prompt":"Ground-level street wind speeds can exceed ____ meters per second.","correctAnswer":["25","twenty-five"],"explanation":"Lecturer says: 'frequently exceeding twenty-five meters per second.'","evidence":"frequently exceeding twenty-five meters per second."},{"id":"l1-q35","questionNumber":35,"prompt":"Narrow passages between adjacent towers cause wind to speed up via the ____ effect.","correctAnswer":"Venturi","explanation":"Lecturer states: 'induce the Venturi effect—often called the wind tunnel effect.'","evidence":"they induce the Venturi effect—often called the wind tunnel effect."},{"id":"l1-q36","questionNumber":36,"prompt":"Cutting curved or angled edges on building corners is termed ____.","correctAnswer":["chamfering","corner chamfering"],"explanation":"Lecturer refers to: 'aerodynamic corner chamfering: carving curved or beveled edges'.","evidence":"involves aerodynamic corner chamfering: carving curved or beveled edges onto building corners"},{"id":"l1-q37","questionNumber":37,"prompt":"Corner modifications can decrease ground gust speeds by as much as ____ percent.","correctAnswer":["32","thirty-two"],"explanation":"Lecturer cites: 'can diminish ground wind gusts by up to thirty-two percent.'","evidence":"can diminish ground wind gusts by up to thirty-two percent."},{"id":"l1-q38","questionNumber":38,"prompt":"Horizontal voids designed through buildings are called ____.","correctAnswer":"wind slits","explanation":"Lecturer refers to: 'through-building openings, known in engineering as porous wind slits.'","evidence":"through-building openings, known in engineering as porous wind slits."},{"id":"l1-q39","questionNumber":39,"prompt":"The landmark building cited in China featuring an upper wind opening is the ____ Financial Center.","correctAnswer":["Shanghai World","Shanghai"],"explanation":"Lecturer refers to: 'Shanghai World Financial Center, whose aperture near the pinnacle'.","evidence":"A striking example is the Shanghai World Financial Center"},{"id":"l1-q40","questionNumber":40,"prompt":"Pedestrians can be shielded from descending air by street-level horizontal structures called ____.","correctAnswer":"podiums","explanation":"Lecturer says: 'deploy large horizontal podiums and landscaped canopies.'","evidence":"A broad podium extending five to eight meters from the tower perimeter acts as a physical shield"}]}]}]`),r={source:"Zarii Open Audio Education Lab",license:"CC BY-SA 4.0",notes:"Original multi-speaker listening audio scripts designed for IELTS listening assessment."},ue={id:e,title:t,difficulty:i,timeLimitMinutes:40,sections:n,attribution:r},o="list-test-02",a="Listening Practice Test 2",s="standard",l=40,c=JSON.parse(`[{"sectionNumber":1,"title":"Community Bicycle Cooperative Repair & Rental","contextDescription":"A customer, Sarah Jenkins, booking a bicycle tune-up and weekend hire at the GreenSpoke Bike Co-op.","audioScript":[{"speaker":"Mechanic","text":"Welcome to GreenSpoke Cooperative! How's your bicycle running today?"},{"speaker":"Sarah","text":"Hello! I commute daily on my hybrid commuter bike, but recently the rear gear shifting has been slipping, especially on hills. Also, the rear brake feels quite spongy."},{"speaker":"Mechanic","text":"Alright, let me inspect it. Ah yes, your derailleur cable has stretched, and the rear brake pads are worn down to the metal indicators. We can replace both cables and install new ceramic compound pads."},{"speaker":"Sarah","text":"That sounds great. What's the total estimate for parts and labor?"},{"speaker":"Mechanic","text":"The full safety overhaul comes to forty-five pounds for parts plus twenty pounds labor, so sixty-five pounds total."},{"speaker":"Sarah","text":"Perfect. When will it be ready for collection?"},{"speaker":"Mechanic","text":"We can have it ready tomorrow by four thirty in the afternoon. Let me take down your contact details. What is your full name?"},{"speaker":"Sarah","text":"It's Sarah Jenkins, that's J-E-N-K-I-N-S, and my phone number is zero seven seven zero zero, nine zero zero four five two."},{"speaker":"Mechanic","text":"Got it. Now, you mentioned on the phone that you also wanted to rent a touring e-bike for your sister visiting this weekend?"},{"speaker":"Sarah","text":"Yes, exactly! From Saturday morning to Sunday evening."},{"speaker":"Mechanic","text":"No problem. Our e-bike rental includes a high-capacity lithium battery with a range of eighty kilometers, an approved safety helmet, and a heavy-duty steel U-lock. Just ensure that the battery is recharged only using the supplied fifty-watt adapter."},{"speaker":"Sarah","text":"Understood. And what time must the rental bike be returned on Sunday?"},{"speaker":"Mechanic","text":"Our shop closes at six in the evening on Sundays, but you can drop the bike into our automated electronic storage shed anytime until eight thirty PM using the PIN code seven four one zero."},{"speaker":"Sarah","text":"Seven four one zero. That's super convenient. Thank you so much!"}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l2-q1","questionNumber":1,"prompt":"Customer's bicycle style: hybrid ____ bike.","correctAnswer":"commuter","explanation":"Sarah states: 'commute daily on my hybrid commuter bike'.","evidence":"I commute daily on my hybrid commuter bike"},{"id":"l2-q2","questionNumber":2,"prompt":"Parts needing renewal: gear cables and ceramic compound ____.","correctAnswer":["brake pads","pads"],"explanation":"Mechanic states: 'replace both cables and install new ceramic compound pads.'","evidence":"replace both cables and install new ceramic compound pads."},{"id":"l2-q3","questionNumber":3,"prompt":"Total quoted price including parts and labor: £____","correctAnswer":["65","sixty-five","65 pounds"],"explanation":"Mechanic explains: 'so sixty-five pounds total.'","evidence":"forty-five pounds for parts plus twenty pounds labor, so sixty-five pounds total."},{"id":"l2-q4","questionNumber":4,"prompt":"Collection pickup time tomorrow: ____ PM.","correctAnswer":["4:30","4.30","four thirty"],"explanation":"Mechanic states: 'ready tomorrow by four thirty in the afternoon.'","evidence":"ready tomorrow by four thirty in the afternoon."},{"id":"l2-q5","questionNumber":5,"prompt":"Customer's surname: ____.","correctAnswer":"Jenkins","explanation":"Sarah spells J-E-N-K-I-N-S.","evidence":"It's Sarah Jenkins, that's J-E-N-K-I-N-S"},{"id":"l2-q6","questionNumber":6,"prompt":"Rental e-bike maximum distance battery range: ____ kilometers.","correctAnswer":["80","eighty"],"explanation":"Mechanic mentions: 'with a range of eighty kilometers'.","evidence":"with a range of eighty kilometers, an approved safety helmet"},{"id":"l2-q7","questionNumber":7,"prompt":"Type of bicycle lock supplied: steel ____.","correctAnswer":["U-lock","u lock"],"explanation":"Mechanic specifies: 'and a heavy-duty steel U-lock.'","evidence":"and a heavy-duty steel U-lock."},{"id":"l2-q8","questionNumber":8,"prompt":"Charger rating to be used exclusively: ____ watts.","correctAnswer":["50","fifty"],"explanation":"Mechanic emphasizes: 'using the supplied fifty-watt adapter.'","evidence":"using the supplied fifty-watt adapter."},{"id":"l2-q9","questionNumber":9,"prompt":"Latest evening time for electronic storage shed return on Sunday: ____ PM.","correctAnswer":["8:30","8.30","eight thirty"],"explanation":"Mechanic says: 'automated electronic storage shed anytime until eight thirty PM'.","evidence":"drop the bike into our automated electronic storage shed anytime until eight thirty PM"},{"id":"l2-q10","questionNumber":10,"prompt":"Four-digit shed entry PIN code: ____.","correctAnswer":"7410","explanation":"Mechanic states: 'PIN code seven four one zero.'","evidence":"PIN code seven four one zero."}]}]},{"sectionNumber":2,"title":"Kingfisher Marshes Wetland Sanctuary Orientation","contextDescription":"A guided orientation by park warden Douglas Evans describing trails and observation hides at the wetland nature reserve.","audioScript":[{"speaker":"Warden","text":"Good morning and welcome to the Kingfisher Marshes Wetland Sanctuary. Spread across four hundred hectares of tidal salt marsh and reed beds, this protected reserve hosts over two hundred migratory waterfowl species."},{"speaker":"Warden","text":"Please take a look at the orientation map in front of you. We are gathered here at the Visitor Center and Car Park at the bottom of the map."},{"speaker":"Warden","text":"Directly leading north from the center is our elevated wooden boardwalk. As you proceed along the main boardwalk, take the first right fork leading into the willow trees. Nestled at the end of this short spur, marked as Location A, is the Dragonfly Observation Platform, where water lilies bloom throughout summer."},{"speaker":"Warden","text":"Returning to the main boardwalk and continuing north over the tidal sluice bridge, you will see a large wooden hide on your left overlooking the tidal lagoon. This is Location B, our Heron Watching Hide, fitted with specialized tinted glass windows."},{"speaker":"Warden","text":"Further north, where the trail crosses into the deep reed bed zone, you'll encounter a three-story timber tower marked as Location C. That is the Otter Lookout Tower, offering prime vantage points at dawn and dusk."},{"speaker":"Warden","text":"If you follow the eastern branch of the boardwalk loop around the freshwater lagoon, marked at Location D on the eastern shoreline, you'll find the Pond Dipping Shelter, where educational groups study aquatic macroinvertebrates."},{"speaker":"Warden","text":"Finally, at the northernmost boundary of the reserve adjacent to the tidal sea wall, marked as Location E, sits the Coastal Wader Blind, designed for viewing rare curlews and godwits."},{"speaker":"Warden","text":"A brief reminder: because noise carries easily across open water, mobile phones must be silenced. Please remain on marked timber paths to avoid disturbing ground-nesting lapwings."}],"questionGroups":[{"groupInstruction":"Label the map below. Choose the correct letter, A–E, and write the answers in boxes 11–15 on your answer sheet.","questionType":"diagram_label_completion","diagramSvg":"<svg viewBox='0 0 500 320' xmlns='http://www.w3.org/2000/svg' class='w-full max-w-lg mx-auto bg-slate-50 dark:bg-slate-900 rounded-xl p-2 border border-slate-200 dark:border-slate-700'><rect width='500' height='320' fill='#f0fdf4' rx='10'/><path d='M 250 300 L 250 80' stroke='#14b8a6' stroke-width='16' stroke-linecap='round'/><path d='M 250 240 L 370 200' stroke='#14b8a6' stroke-width='12' stroke-linecap='round'/><path d='M 250 150 L 120 150' stroke='#14b8a6' stroke-width='12' stroke-linecap='round'/><path d='M 250 110 L 380 110' stroke='#14b8a6' stroke-width='12' stroke-linecap='round'/><circle cx='250' cy='300' r='14' fill='#0f766e'/><text x='210' y='318' font-size='11' font-weight='bold' fill='#0f766e'>Visitor Center</text><rect x='370' y='180' width='55' height='40' rx='6' fill='#0d9488'/><text x='392' y='206' font-size='16' font-weight='bold' fill='white'>A</text><rect x='70' y='130' width='55' height='40' rx='6' fill='#0d9488'/><text x='92' y='156' font-size='16' font-weight='bold' fill='white'>B</text><circle cx='250' cy='70' r='24' fill='#0d9488'/><text x='244' y='76' font-size='16' font-weight='bold' fill='white'>C</text><rect x='380' y='90' width='55' height='40' rx='6' fill='#0d9488'/><text x='402' y='116' font-size='16' font-weight='bold' fill='white'>D</text><polygon points='220,20 280,20 250,5' fill='#0d9488'/><text x='244' y='35' font-size='16' font-weight='bold' fill='white'>E</text></svg>","questions":[{"id":"l2-q11","questionNumber":11,"prompt":"Dragonfly Observation Platform","options":["A","B","C","D","E"],"correctAnswer":"A","explanation":"Warden states: 'first right fork leading into the willow trees... marked as Location A, is the Dragonfly Observation Platform'.","evidence":"marked as Location A, is the Dragonfly Observation Platform, where water lilies bloom"},{"id":"l2-q12","questionNumber":12,"prompt":"Heron Watching Hide","options":["A","B","C","D","E"],"correctAnswer":"B","explanation":"Warden points out: 'large wooden hide on your left overlooking the tidal lagoon. This is Location B, our Heron Watching Hide'.","evidence":"This is Location B, our Heron Watching Hide, fitted with specialized tinted glass windows."},{"id":"l2-q13","questionNumber":13,"prompt":"Otter Lookout Tower","options":["A","B","C","D","E"],"correctAnswer":"C","explanation":"Warden states: 'three-story timber tower marked as Location C. That is the Otter Lookout Tower'.","evidence":"three-story timber tower marked as Location C. That is the Otter Lookout Tower"},{"id":"l2-q14","questionNumber":14,"prompt":"Pond Dipping Shelter","options":["A","B","C","D","E"],"correctAnswer":"D","explanation":"Warden notes: 'marked at Location D on the eastern shoreline, you'll find the Pond Dipping Shelter'.","evidence":"marked at Location D on the eastern shoreline, you'll find the Pond Dipping Shelter"},{"id":"l2-q15","questionNumber":15,"prompt":"Coastal Wader Blind","options":["A","B","C","D","E"],"correctAnswer":"E","explanation":"Warden specifies: 'at the northernmost boundary of the reserve adjacent to the tidal sea wall, marked as Location E, sits the Coastal Wader Blind'.","evidence":"marked as Location E, sits the Coastal Wader Blind, designed for viewing rare curlews"}]},{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 16–20 on your answer sheet.","questionType":"multiple_choice_single","questions":[{"id":"l2-q16","questionNumber":16,"prompt":"How large is the Kingfisher Marshes Wetland Sanctuary?","options":["150 hectares","650 hectares","400 hectares"],"correctAnswer":"C","explanation":"Warden says: 'Spread across four hundred hectares of tidal salt marsh'.","evidence":"Spread across four hundred hectares of tidal salt marsh"},{"id":"l2-q17","questionNumber":17,"prompt":"Approximately how many migratory waterfowl species visit the reserve?","options":["Over 200","Over 50","Over 100"],"correctAnswer":"A","explanation":"Warden mentions: 'hosts over two hundred migratory waterfowl species.'","evidence":"hosts over two hundred migratory waterfowl species."},{"id":"l2-q18","questionNumber":18,"prompt":"What special architectural feature does the Heron Watching Hide have?","options":["Solar heated floors","Tinted glass viewing windows","Soundproof acoustic walls"],"correctAnswer":"B","explanation":"Warden specifies: 'fitted with specialized tinted glass windows.'","evidence":"fitted with specialized tinted glass windows."},{"id":"l2-q19","questionNumber":19,"prompt":"What aquatic organisms are studied at the Pond Dipping Shelter?","options":["Freshwater salmon","Deep sea sponges","Aquatic macroinvertebrates"],"correctAnswer":"C","explanation":"Warden states: 'educational groups study aquatic macroinvertebrates.'","evidence":"educational groups study aquatic macroinvertebrates."},{"id":"l2-q20","questionNumber":20,"prompt":"Why are visitors requested to stay strictly on the timber walkways?","options":["To prevent damaging ground-nesting bird nests","To avoid snakes in the grass","To prevent damaging expensive irrigation pipes"],"correctAnswer":"A","explanation":"Warden advises: 'Please remain on marked timber paths to avoid disturbing ground-nesting lapwings.'","evidence":"Please remain on marked timber paths to avoid disturbing ground-nesting lapwings."}]}]},{"sectionNumber":3,"title":"Academic Consultation on Enhanced Geothermal Energy Systems","contextDescription":"Two master's engineering students, Liam and Maya, discussing their research dissertation on deep geothermal wells with Professor Vance.","audioScript":[{"speaker":"Professor","text":"Come in, Liam, Maya. Let's examine your preliminary technical feasibility model for Enhanced Geothermal Systems (EGS)."},{"speaker":"Liam","text":"Thank you, Professor Vance. Our simulation compares traditional hydrothermal power with supercritical EGS wells drilled into hot dry crystalline granite at five kilometers depth."},{"speaker":"Maya","text":"We discovered that while conventional hydrothermal systems require naturally occurring underground water and permeable fault lines, EGS injects high-pressure fluid to create artificial micro-fractures in impermeable rock."},{"speaker":"Professor","text":"Crucial distinction. What heat exchange fluid did you select for the subsurface thermodynamic cycle?"},{"speaker":"Liam","text":"Initially, we modeled pressurized water, but our updated simulation utilizes supercritical carbon dioxide instead. Because supercritical CO2 has lower viscosity and higher thermal expansion than water, it requires twenty-five percent less pumping power."},{"speaker":"Maya","text":"Plus, a portion of the circulating carbon dioxide becomes permanently sequestered in calcium silicate minerals deep within the subsurface basalt formations."},{"speaker":"Professor","text":"That's a compelling dual-benefit: zero-carbon baseload electricity alongside permanent carbon sequestration. However, did you evaluate induced seismicity?"},{"speaker":"Liam","text":"Yes, induced micro-earthquakes are the foremost societal concern. In our risk mitigation chapter, we propose deploying continuous fiber-optic acoustic sensors along borehole casings to monitor hydraulic pressure spikes in real time."},{"speaker":"Professor","text":"Good. Remember to submit your completed methodology chapter by the thirtieth of June."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–25 on your answer sheet.","questionType":"multiple_choice_single","questions":[{"id":"l2-q21","questionNumber":21,"prompt":"To what depth are the simulated geothermal wells drilled?","options":["Two kilometers","Five kilometers","Ten kilometers"],"correctAnswer":"B","explanation":"Liam specifies: 'drilled into hot dry crystalline granite at five kilometers depth.'","evidence":"drilled into hot dry crystalline granite at five kilometers depth."},{"id":"l2-q22","questionNumber":22,"prompt":"How does Enhanced Geothermal Systems (EGS) create permeability in dense rock?","options":["By detonating underground explosives","By melting rock with lasers","By injecting high-pressure fluid to produce micro-fractures"],"correctAnswer":"C","explanation":"Maya notes: 'EGS injects high-pressure fluid to create artificial micro-fractures in impermeable rock.'","evidence":"EGS injects high-pressure fluid to create artificial micro-fractures in impermeable rock."},{"id":"l2-q23","questionNumber":23,"prompt":"What advantage does supercritical carbon dioxide have over water as a working fluid?","options":["It requires 25% less pumping power due to lower viscosity.","It is entirely free of financial cost.","It prevents any corrosion in steel pipes."],"correctAnswer":"A","explanation":"Liam states: 'lower viscosity and higher thermal expansion than water, it requires twenty-five percent less pumping power.'","evidence":"requires twenty-five percent less pumping power."},{"id":"l2-q24","questionNumber":24,"prompt":"What secondary environmental benefit does using CO2 provide?","options":["Purifying local groundwater reservoirs","Permanent mineral sequestration of carbon underground","Generating agricultural fertilizer"],"correctAnswer":"B","explanation":"Maya notes: 'becomes permanently sequestered in calcium silicate minerals deep within the subsurface basalt formations.'","evidence":"becomes permanently sequestered in calcium silicate minerals deep within the subsurface basalt formations."},{"id":"l2-q25","questionNumber":25,"prompt":"What technology is proposed to monitor induced micro-seismicity?","options":["Drone thermal surveillance","Satellite radar imaging","Fiber-optic acoustic sensors along boreholes"],"correctAnswer":"C","explanation":"Liam mentions: 'deploying continuous fiber-optic acoustic sensors along borehole casings'.","evidence":"deploying continuous fiber-optic acoustic sensors along borehole casings"}]},{"groupInstruction":"Complete the sentences below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 26–30 on your answer sheet.","questionType":"sentence_completion","questions":[{"id":"l2-q26","questionNumber":26,"prompt":"The geological rock type targeted for deep drilling is crystalline ____.","correctAnswer":"granite","explanation":"Liam says: 'drilled into hot dry crystalline granite'.","evidence":"drilled into hot dry crystalline granite at five kilometers depth."},{"id":"l2-q27","questionNumber":27,"prompt":"CO2 reacts and traps carbon inside calcium ____ minerals.","correctAnswer":"silicate","explanation":"Maya mentions: 'calcium silicate minerals deep within the subsurface'.","evidence":"calcium silicate minerals deep within the subsurface basalt formations."},{"id":"l2-q28","questionNumber":28,"prompt":"The primary public and societal concern regarding EGS is induced ____.","correctAnswer":["seismicity","micro-earthquakes"],"explanation":"Professor asks about: 'induced seismicity', and Liam refers to 'induced micro-earthquakes'.","evidence":"induced micro-earthquakes are the foremost societal concern."},{"id":"l2-q29","questionNumber":29,"prompt":"Sensors monitor unexpected subsurface spikes in hydraulic ____.","correctAnswer":"pressure","explanation":"Liam states: 'monitor hydraulic pressure spikes in real time.'","evidence":"monitor hydraulic pressure spikes in real time."},{"id":"l2-q30","questionNumber":30,"prompt":"Formal deadline for the methodology chapter submission: the thirtieth of ____.","correctAnswer":"June","explanation":"Professor reminds: 'submit your completed methodology chapter by the thirtieth of June.'","evidence":"submit your completed methodology chapter by the thirtieth of June."}]}]},{"sectionNumber":4,"title":"University Lecture: Acoustic Ecology and Ancient Whistled Languages","contextDescription":"A lecture delivered by an anthropologist on the origins, phonetic structure, and survival of whistled languages in mountainous environments.","audioScript":[{"speaker":"Lecturer","text":"Good afternoon, students. Today we examine an extraordinary manifestation of human bioacoustics: whistled languages, known scientifically as silbo or whistled speech."},{"speaker":"Lecturer","text":"Whistled speech is not an artificial code like Morse; rather, it is a phonetically complete acoustic translation of spoken language. Over seventy populations globally, from the island of La Gomera in the Canaries to the rugged Pyrenees and the Anatolian mountains of Turkey, have developed whistled versions of their native tongues."},{"speaker":"Lecturer","text":"The primary driver of whistled speech is topography. In deeply incised mountainous valleys and dense subtropical forest canopies, normal spoken vowel formats scatter and absorb within two hundred meters. A human whistle, however, generates a concentrated sinusoidal sound wave between one and four kilohertz, which cuts through ambient background noise and carries across distances exceeding five kilometers."},{"speaker":"Lecturer","text":"Phonetically, whistled speech mimics the pitch frequency contours and formant transitions of spoken dialects. For tonal languages like Mazatec in Mexico, whistling replicates pitch contours directly. For non-tonal languages like Spanish or Turkish, whistled frequencies mimic vowel formants, while sudden silences or abrupt frequency glides simulate consonant occlusions."},{"speaker":"Lecturer","text":"Neuroimaging studies conducted at the University of Zurich reveal a captivating phenomenon: when native whistlers listen to whistled sentences, their brains activate both the left temporal lobe, which handles linguistic grammar, and the right hemisphere, which normally processes musical melodies. In contrast, monolingual non-whistling listeners process the sounds purely as meaningless music in the right hemisphere."},{"speaker":"Lecturer","text":"Regrettably, modern telecommunications and mobile phones have triggered a steep decline in traditional whistled communication over recent decades. Today, cultural preservation initiatives in schools have revived Silbo Gomero, ensuring that younger generations sustain this remarkable acoustic heritage."}],"questionGroups":[{"groupInstruction":"Complete the lecture notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40 on your answer sheet.","questionType":"sentence_completion","questions":[{"id":"l2-q31","questionNumber":31,"prompt":"Over ____ communities worldwide have developed forms of whistled speech.","correctAnswer":["70","seventy"],"explanation":"Lecturer states: 'Over seventy populations globally'.","evidence":"Over seventy populations globally, from the island of La Gomera"},{"id":"l2-q32","questionNumber":32,"prompt":"The primary geographical factor driving the creation of whistled languages is ____.","correctAnswer":"topography","explanation":"Lecturer says: 'The primary driver of whistled speech is topography.'","evidence":"The primary driver of whistled speech is topography."},{"id":"l2-q33","questionNumber":33,"prompt":"Ordinary human spoken vowels degrade and dissipate within ____ meters in valleys.","correctAnswer":["200","two hundred"],"explanation":"Lecturer notes: 'scatter and absorb within two hundred meters.'","evidence":"normal spoken vowel formats scatter and absorb within two hundred meters."},{"id":"l2-q34","questionNumber":34,"prompt":"Whistled sound waves can travel over distances greater than ____ kilometers.","correctAnswer":["5","five"],"explanation":"Lecturer states: 'carries across distances exceeding five kilometers.'","evidence":"carries across distances exceeding five kilometers."},{"id":"l2-q35","questionNumber":35,"prompt":"Whistles generate a pure acoustic wave described geometrically as a ____ wave.","correctAnswer":"sinusoidal","explanation":"Lecturer says: 'generates a concentrated sinusoidal sound wave'.","evidence":"generates a concentrated sinusoidal sound wave between one and four kilohertz"},{"id":"l2-q36","questionNumber":36,"prompt":"In tonal languages, whistling directly imitates the spoken ____ contours.","correctAnswer":"pitch","explanation":"Lecturer notes: 'replicates pitch contours directly.'","evidence":"whistling replicates pitch contours directly."},{"id":"l2-q37","questionNumber":37,"prompt":"In non-tonal dialects, brief pauses in the sound represent consonant ____.","correctAnswer":["occlusions","stops"],"explanation":"Lecturer explains: 'sudden silences or abrupt frequency glides simulate consonant occlusions.'","evidence":"sudden silences or abrupt frequency glides simulate consonant occlusions."},{"id":"l2-q38","questionNumber":38,"prompt":"Neuroscientists at the University of ____ studied the brain scans of native whistlers.","correctAnswer":"Zurich","explanation":"Lecturer cites: 'Neuroimaging studies conducted at the University of Zurich'.","evidence":"Neuroimaging studies conducted at the University of Zurich reveal a captivating phenomenon"},{"id":"l2-q39","questionNumber":39,"prompt":"In whistlers' brains, language grammar is processed simultaneously in the left ____ lobe.","correctAnswer":"temporal","explanation":"Lecturer states: 'left temporal lobe, which handles linguistic grammar'.","evidence":"both the left temporal lobe, which handles linguistic grammar, and the right hemisphere"},{"id":"l2-q40","questionNumber":40,"prompt":"The whistled language taught in Canary Island schools today is called Silbo ____.","correctAnswer":"Gomero","explanation":"Lecturer concludes: 'initiatives in schools have revived Silbo Gomero'.","evidence":"cultural preservation initiatives in schools have revived Silbo Gomero"}]}]}]`),d={source:"Zarii Open Audio Linguistics Lab",license:"CC BY-SA 4.0",notes:"Original multi-speaker listening audio scripts designed for IELTS listening assessment."},he={id:o,title:a,difficulty:s,timeLimitMinutes:l,sections:c,attribution:d},p="list-test-03",u="Listening Practice Test 3",h="standard",m=40,g=JSON.parse(`[{"sectionNumber":1,"title":"Campervan Rental and Insurance Booking","contextDescription":"A customer, Marcus Henderson, inquiring about hiring a campervan for a touring vacation across the South Island of New Zealand.","audioScript":[{"speaker":"Agent","text":"Kia Ora and good morning! Southern Cross Campervan Rentals, Liam speaking. How can I help you today?"},{"speaker":"Marcus","text":"Hello there! My wife and I are planning a two-week driving holiday across the South Island next month, and we'd like to reserve a motorhome."},{"speaker":"Agent","text":"Excellent choice. What dates are you looking at arriving and departing?"},{"speaker":"Marcus","text":"We touch down in Christchurch on the twelfth of November, and we fly out from Queenstown on the twenty-sixth of November."},{"speaker":"Agent","text":"Splendid. So that's a fourteen-day one-way hire. For two adults, our most popular model is the Alpine Cruiser. It features a pressurized hot-water shower, a compact gas kitchenette with a two-burner stove, a mini-fridge, and an elevated double bed."},{"speaker":"Marcus","text":"That sounds ideal. Does the Alpine Cruiser require a specialized commercial driving license?"},{"speaker":"Agent","text":"No, a standard full domestic automobile driver's license in English is completely valid."},{"speaker":"Marcus","text":"Terrific. And what is the base rental tariff per day?"},{"speaker":"Agent","text":"During November, the seasonal rate is one hundred and eighty-five dollars per day. That includes unlimited kilometers and twenty-four-hour roadside assistance."},{"speaker":"Marcus","text":"What about insurance coverage? Are we liable for accidental windscreen chips or gravel damage?"},{"speaker":"Agent","text":"The standard complimentary tier carries a excess liability of two thousand dollars. However, we strongly recommend our Platinum Peace-of-Mind waiver for thirty-five dollars extra per day, which reduces your excess to zero and protects against windscreen chips, tyre punctures, and undercarriage gravel damage."},{"speaker":"Marcus","text":"We definitely want the Platinum waiver; mountain roads can be quite gravelly. Can we also hire GPS navigation and two folding camping chairs?"},{"speaker":"Agent","text":"Yes, portable satellite GPS is ten dollars total for the entire trip, and camping chairs are five dollars each."},{"speaker":"Marcus","text":"Wonderful. Let me give you my reservation details."},{"speaker":"Agent","text":"Certainly. Could I have your full name and contact number?"},{"speaker":"Marcus","text":"Yes, it's Marcus Henderson, that's H-E-N-D-E-R-S-O-N, and my mobile number is zero two one, five five five, seven eight three zero."},{"speaker":"Agent","text":"Thank you, Marcus. And your email address for the voucher confirmation?"},{"speaker":"Marcus","text":"It's m dot henderson at horizon dot nz."},{"speaker":"Agent","text":"Got it. When you arrive at Christchurch Airport, take the complimentary shuttle bus from Exit Door Four directly to our depot on Memorial Avenue. Our depot closes at six PM, so please arrive before five thirty to complete the digital vehicle orientation."},{"speaker":"Marcus","text":"Noted. Five thirty PM at Memorial Avenue. Thank you very much, Liam!"}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l3-q1","questionNumber":1,"prompt":"Rental start date: 12th of ____.","correctAnswer":"November","explanation":"Marcus states: 'We touch down in Christchurch on the twelfth of November'.","evidence":"We touch down in Christchurch on the twelfth of November"},{"id":"l3-q2","questionNumber":2,"prompt":"Vehicle model chosen: the ____ Cruiser.","correctAnswer":"Alpine","explanation":"Liam mentions: 'our most popular model is the Alpine Cruiser.'","evidence":"For two adults, our most popular model is the Alpine Cruiser."},{"id":"l3-q3","questionNumber":3,"prompt":"Kitchenette includes a two-burner stove and a mini-____.","correctAnswer":"fridge","explanation":"Liam notes: 'a two-burner stove, a mini-fridge, and an elevated double bed.'","evidence":"a compact gas kitchenette with a two-burner stove, a mini-fridge"},{"id":"l3-q4","questionNumber":4,"prompt":"Daily base hire rate in November: $____ per day.","correctAnswer":["185","one hundred and eighty-five","185 dollars"],"explanation":"Liam states: 'the seasonal rate is one hundred and eighty-five dollars per day.'","evidence":"During November, the seasonal rate is one hundred and eighty-five dollars per day."},{"id":"l3-q5","questionNumber":5,"prompt":"Name of insurance package: the ____ Peace-of-Mind waiver.","correctAnswer":"Platinum","explanation":"Liam introduces: 'our Platinum Peace-of-Mind waiver'.","evidence":"However, we strongly recommend our Platinum Peace-of-Mind waiver for thirty-five dollars extra per day"},{"id":"l3-q6","questionNumber":6,"prompt":"Optional equipment hired: GPS navigation and two folding camping ____.","correctAnswer":"chairs","explanation":"Marcus asks: 'hire GPS navigation and two folding camping chairs?'","evidence":"Can we also hire GPS navigation and two folding camping chairs?"},{"id":"l3-q7","questionNumber":7,"prompt":"Customer's surname: ____.","correctAnswer":"Henderson","explanation":"Marcus spells: 'H-E-N-D-E-R-S-O-N'.","evidence":"Yes, it's Marcus Henderson, that's H-E-N-D-E-R-S-O-N"},{"id":"l3-q8","questionNumber":8,"prompt":"Customer's contact phone number: 021 555 ____.","correctAnswer":"7830","explanation":"Marcus gives phone number: 'zero two one, five five five, seven eight three zero.'","evidence":"my mobile number is zero two one, five five five, seven eight three zero."},{"id":"l3-q9","questionNumber":9,"prompt":"Airport shuttle departs from Exit Door ____.","correctAnswer":["Four","4","door 4"],"explanation":"Liam says: 'take the complimentary shuttle bus from Exit Door Four'.","evidence":"take the complimentary shuttle bus from Exit Door Four directly to our depot"},{"id":"l3-q10","questionNumber":10,"prompt":"Depot address: ____ Avenue.","correctAnswer":"Memorial","explanation":"Liam gives the location: 'depot on Memorial Avenue.'","evidence":"directly to our depot on Memorial Avenue."}]}]},{"sectionNumber":2,"title":"Audio Guide to the Riverside Botanic Glasshouses","contextDescription":"The senior botanist, Dr. David Campbell, providing a welcoming audio introduction for visitors exploring the botanical conservatory gardens.","audioScript":[{"speaker":"Guide","text":"A warm welcome to the Riverside Botanic Glasshouses, constructed in 1888 during the Victorian golden age of botany. Our historic cast-iron and glass structure houses over four thousand species of flora from every continent on Earth."},{"speaker":"Guide","text":"Before you embark on your self-guided walk, let me orient you with our layout. You are currently standing in the Central Palm Atrium, beneath our soaring thirty-meter curved glass dome. In the center of the atrium floor stands our ornamental koi pond, which was originally installed to maintain atmospheric humidity for our nineteenth-century cycad collection."},{"speaker":"Guide","text":"Directly north of the central atrium, you will find the Tropical Rainforest biome. Here, the temperature is maintained at a constant twenty-eight degrees Celsius, and high-pressure mist nozzles recreate the daily monsoon precipitation of the Amazon river basin. Look up to spot our magnificent climbing strangler figs and epiphytic orchids."},{"speaker":"Guide","text":"If you head east through the glass vestibule, you enter the Arid Succulent Pavilion. This zone replicates the harsh desert climates of southern Africa and the American Southwest. Notice the remarkable columnar saguaro cacti, which can store up to two metric tons of water inside their pleated stems during rare desert flash floods."},{"speaker":"Guide","text":"Moving south toward the riverside wing brings you to the Alpine Terraces. Unlike the tropical house, the Alpine pavilion utilizes chilled geothermal pipes running through the soil beds to recreate the sub-zero night conditions essential for fragile Himalayan edelweiss and high-altitude mosses."},{"speaker":"Guide","text":"Finally, nestled in the western courtyard is our newly opened Insectarium and Pollinator Garden. Here, visitors can witness thousands of free-flying tropical butterflies feeding on flowering nectar corridors. Please note that photography using tripod equipment is prohibited on weekend afternoons due to narrow pathways, but handheld camera devices and smartphones are warmly encouraged. Light refreshments and botanical herbal teas are served at the Orangery Tearoom, located adjacent to the gift shop near the exit."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–15.","questionType":"multiple_choice","questions":[{"id":"l3-q11","questionNumber":11,"prompt":"When were the Riverside Botanic Glasshouses initially constructed?","options":["1888","1848","1928"],"correctAnswer":"A","explanation":"The guide states the glasshouses were 'constructed in 1888 during the Victorian golden age of botany.'","evidence":"constructed in 1888 during the Victorian golden age of botany."},{"id":"l3-q12","questionNumber":12,"prompt":"Why was the koi pond in the Central Palm Atrium originally introduced?","options":["To supply drinking water for local songbirds","To maintain necessary atmospheric humidity for plants","To conduct fish breeding experiments"],"correctAnswer":"B","explanation":"The guide explains it was installed 'to maintain atmospheric humidity for our nineteenth-century cycad collection.'","evidence":"which was originally installed to maintain atmospheric humidity for our nineteenth-century cycad collection."},{"id":"l3-q13","questionNumber":13,"prompt":"What special climate control system is used in the Alpine Terraces?","options":["Industrial air blowers","Artificial snow generators","Chilled geothermal pipes inside soil beds"],"correctAnswer":"C","explanation":"The guide notes the Alpine pavilion 'utilizes chilled geothermal pipes running through the soil beds'.","evidence":"utilizes chilled geothermal pipes running through the soil beds to recreate the sub-zero night conditions"},{"id":"l3-q14","questionNumber":14,"prompt":"What restriction applies to visitors in the Insectarium?","options":["Tripod photography prohibited on weekend afternoons","No children under six permitted","Food and bottled water strictly forbidden"],"correctAnswer":"A","explanation":"The guide notes: 'photography using tripod equipment is prohibited on weekend afternoons due to narrow pathways'.","evidence":"Please note that photography using tripod equipment is prohibited on weekend afternoons due to narrow pathways"},{"id":"l3-q15","questionNumber":15,"prompt":"Where can visitors find refreshments and herbal tea?","options":["Beside the Central Palm koi pond","At the Orangery Tearoom near the gift shop","In the Alpine pavilion observation terrace"],"correctAnswer":"B","explanation":"The guide specifies: 'at the Orangery Tearoom, located adjacent to the gift shop near the exit.'","evidence":"at the Orangery Tearoom, located adjacent to the gift shop near the exit."}]},{"groupInstruction":"Match the glasshouse areas (16–20) with their directional location from the Central Palm Atrium (A–E). Write the correct letter in boxes 16–20.\\nA: Directly North\\nB: East wing\\nC: South wing\\nD: West courtyard\\nE: Atrium center","questionType":"matching","questions":[{"id":"l3-q16","questionNumber":16,"prompt":"Ornamental Koi Pond","correctAnswer":"E","explanation":"The guide explains: 'In the center of the atrium floor stands our ornamental koi pond'.","evidence":"In the center of the atrium floor stands our ornamental koi pond"},{"id":"l3-q17","questionNumber":17,"prompt":"Tropical Rainforest Biome","correctAnswer":"A","explanation":"The guide states: 'Directly north of the central atrium, you will find the Tropical Rainforest biome.'","evidence":"Directly north of the central atrium, you will find the Tropical Rainforest biome."},{"id":"l3-q18","questionNumber":18,"prompt":"Arid Succulent Pavilion","correctAnswer":"B","explanation":"The guide notes: 'If you head east through the glass vestibule, you enter the Arid Succulent Pavilion.'","evidence":"If you head east through the glass vestibule, you enter the Arid Succulent Pavilion."},{"id":"l3-q19","questionNumber":19,"prompt":"Alpine Terraces","correctAnswer":"C","explanation":"The guide states: 'Moving south toward the riverside wing brings you to the Alpine Terraces.'","evidence":"Moving south toward the riverside wing brings you to the Alpine Terraces."},{"id":"l3-q20","questionNumber":20,"prompt":"Insectarium & Pollinator Garden","correctAnswer":"D","explanation":"The guide concludes: 'nestled in the western courtyard is our newly opened Insectarium and Pollinator Garden.'","evidence":"Finally, nestled in the western courtyard is our newly opened Insectarium and Pollinator Garden."}]}]},{"sectionNumber":3,"title":"University Micro-Hydro Turbine Engineering Project","contextDescription":"Two engineering undergraduates, Chloe and Liam, discussing their renewable energy project design with their academic supervisor, Professor Evans.","audioScript":[{"speaker":"Prof Evans","text":"Good afternoon, Chloe, Liam. How is the design for your remote village micro-hydro generating system progressing?"},{"speaker":"Chloe","text":"Quite well, Professor. We've finalized our site selection for the mountainous rural community in northern Vietnam. The stream has a vertical head drop of forty-five meters and a minimum flow rate of twenty liters per second during the dry season."},{"speaker":"Liam","text":"Based on those parameters, we had to choose between a Pelton wheel impulse turbine and a crossflow reaction turbine. We ran computational fluid simulations and concluded that a Pelton wheel is significantly superior for high-head, low-volume flow conditions."},{"speaker":"Prof Evans","text":"I agree with that thermodynamic assessment. What about sediment and silt management? Mountain streams during the rainy season carry substantial abrasive sand that can rapidly erode turbine runner buckets."},{"speaker":"Chloe","text":"We designed a two-chamber settling tank upstream. The first chamber decants coarse gravel, while the second chamber decelerates water velocity to allow fine silt particles over zero point two millimeters to settle before entering the penstock pipe."},{"speaker":"Prof Evans","text":"Very sensible. And what material have you specified for the penstock pipe carrying the pressurized water down the mountain?"},{"speaker":"Liam","text":"We initially considered welded mild steel, but the transport logistics up steep footpaths are impossible for heavy trucks. So we opted for high-density polyethylene, or HDPE. It's lightweight, flexible, completely immune to chemical corrosion, and comes in coiled rolls that can be carried on pack mules."},{"speaker":"Chloe","text":"For the runner buckets, we are testing 3D-printed glass-fiber reinforced nylon against recycled cast aluminum. The nylon prototypes are twenty percent lighter and cheaper to manufacture locally using open-source desktop 3D printers."},{"speaker":"Prof Evans","text":"Excellent community-centered innovation. For your final submission, remember to include an electronic load controller schematic. In isolated off-grid grids, when villagers switch off lights, the excess electrical generation must be dumped into secondary resistive heaters, such as a community water tank, to prevent generator runaway."},{"speaker":"Liam","text":"Yes, we have integrated a pulse-width modulated ballast circuit into our final CAD model. We'll present the functional prototype at the faculty symposium next Thursday!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–25.","questionType":"multiple_choice","questions":[{"id":"l3-q21","questionNumber":21,"prompt":"What is the vertical head drop of the selected stream site in Vietnam?","options":["25 meters","60 meters","45 meters"],"correctAnswer":"C","explanation":"Chloe states: 'The stream has a vertical head drop of forty-five meters'.","evidence":"The stream has a vertical head drop of forty-five meters and a minimum flow rate of twenty liters per second"},{"id":"l3-q22","questionNumber":22,"prompt":"Why did the students select a Pelton wheel turbine?","options":["It performs best in high-head, low-flow conditions","It is the only turbine permitted by government environmental rules","It requires no upstream water filtration"],"correctAnswer":"A","explanation":"Liam explains: 'a Pelton wheel is significantly superior for high-head, low-volume flow conditions.'","evidence":"concluded that a Pelton wheel is significantly superior for high-head, low-volume flow conditions."},{"id":"l3-q23","questionNumber":23,"prompt":"How does their design manage stream sediment?","options":["By using chemical flocculants","Using a two-chamber upstream settling tank","By cleaning turbine buckets manually every morning"],"correctAnswer":"B","explanation":"Chloe explains: 'We designed a two-chamber settling tank upstream.'","evidence":"We designed a two-chamber settling tank upstream. The first chamber decants coarse gravel, while the second chamber decelerates water velocity"},{"id":"l3-q24","questionNumber":24,"prompt":"Why did the students choose HDPE over steel for the penstock pipe?","options":["It can withstand higher steam pressure","It is transparent so blockages can be seen","It is lightweight and transportable on pack mules"],"correctAnswer":"C","explanation":"Liam notes: 'opted for high-density polyethylene, or HDPE. It's lightweight, flexible... and comes in coiled rolls that can be carried on pack mules.'","evidence":"opted for high-density polyethylene, or HDPE. It's lightweight, flexible, completely immune to chemical corrosion, and comes in coiled rolls that can be carried on pack mules."},{"id":"l3-q25","questionNumber":25,"prompt":"What purpose does the electronic load controller serve?","options":["It diverts surplus power into water heaters to prevent generator overspeed","It shuts down the generator whenever electricity tariffs rise","It monitors river water temperature"],"correctAnswer":"A","explanation":"Professor Evans notes: 'the excess electrical generation must be dumped into secondary resistive heaters, such as a community water tank, to prevent generator runaway.'","evidence":"the excess electrical generation must be dumped into secondary resistive heaters, such as a community water tank, to prevent generator runaway."}]},{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS for each answer. Write your answers in boxes 26–30.","questionType":"sentence_completion","questions":[{"id":"l3-q26","questionNumber":26,"prompt":"The stream has a minimum dry-season flow rate of twenty ____ per second.","correctAnswer":"liters","explanation":"Chloe mentions 'twenty liters per second during the dry season.'","evidence":"minimum flow rate of twenty liters per second during the dry season."},{"id":"l3-q27","questionNumber":27,"prompt":"The settling tank removes abrasive sand to prevent the erosion of turbine ____.","correctAnswer":"runner buckets","explanation":"Professor Evans notes abrasive sand can 'rapidly erode turbine runner buckets.'","evidence":"abrasive sand that can rapidly erode turbine runner buckets."},{"id":"l3-q28","questionNumber":28,"prompt":"The second tank chamber removes fine silt larger than ____ millimeters.","correctAnswer":["0.2","zero point two"],"explanation":"Chloe notes particles over 'zero point two millimeters to settle'.","evidence":"allow fine silt particles over zero point two millimeters to settle"},{"id":"l3-q29","questionNumber":29,"prompt":"Runner buckets are tested using glass-fiber reinforced ____.","correctAnswer":"nylon","explanation":"Chloe states: 'testing 3D-printed glass-fiber reinforced nylon'.","evidence":"testing 3D-printed glass-fiber reinforced nylon against recycled cast aluminum."},{"id":"l3-q30","questionNumber":30,"prompt":"The functional prototype will be unveiled at the faculty ____ next Thursday.","correctAnswer":"symposium","explanation":"Liam concludes: 'present the functional prototype at the faculty symposium next Thursday!'","evidence":"present the functional prototype at the faculty symposium next Thursday!"}]}]},{"sectionNumber":4,"title":"Academic Lecture on Marine Bioluminescence and Oceanic Optics","contextDescription":"Professor Rachel Vance delivering an oceanography lecture on biochemical light production in deep-sea marine organisms.","audioScript":[{"speaker":"Prof Vance","text":"Good morning, students. Today we explore one of the most astonishing biological phenomena on our planet: marine bioluminescence. While light production is relatively rare among terrestrial creatures—confined largely to fireflies and certain fungal mycelia—in the open ocean, it is the prevailing optical norm. Marine biologists estimate that over seventy-five percent of all pelagic organisms inhabiting the ocean column between two hundred and one thousand meters depth possess the capacity to generate biochemical light."},{"speaker":"Prof Vance","text":"At a molecular level, biological light emission is an enzymatic oxidation reaction. The reaction requires two primary components: a light-emitting substrate molecule called luciferin, and an enzyme catalyst known as luciferase. In the presence of dissolved oxygen and cellular energy in the form of ATP, luciferase oxidizes luciferin to form an electronically excited intermediate, oxyluciferin. When this molecule relaxes back to its ground state, it releases a quantum packet of light—a photon. Because virtually zero energy is lost as thermal radiation, bioluminescence is often described by physicists as cold light, achieving ninety-five percent photonic efficiency compared to less than ten percent in incandescent light bulbs."},{"speaker":"Prof Vance","text":"Why is bioluminescence overwhelmingly blue-green in oceanic environments? The answer lies in ocean water optics. Pure water acts as a selective spectral filter: red, orange, and yellow wavelengths of sunlight are rapidly absorbed within the top fifty meters of the sea surface. Blue-green light, with a wavelength between 470 and 490 nanometers, experiences the least optical attenuation and penetrates deepest through seawater. Consequently, marine organisms have evolved photoreceptor pigments tuned precisely to detect this spectral bandwidth."},{"speaker":"Prof Vance","text":"Ecologically, deep-sea fauna harness bioluminescence for three primary survival functions: predation, defense, and communication. In terms of predation, deep-sea anglerfish sport a modified dorsal fin spine tipped with a bioluminescent photophore bulb—termed the esca—filled with symbiotic luminous bacteria. Suspended in total darkness above gaping jaws, the glowing lure attracts inquisitive crustaceans and smaller fish directly into striking range."},{"speaker":"Prof Vance","text":"For defense, many midwater squid and hatchetfish practice counter-illumination camouflage. When swimming in the twilight mesopelagic zone, an animal viewed from below casts a dark silhouette against the faint downwelling sunlight from the surface, making it an easy target for ascending predators. To counteract this vulnerability, hatchetfish possess ventral photophores on their bellies that emit faint blue light matching the precise intensity and color spectrum of the overhead downwelling light, effectively rendering their silhouette completely invisible from beneath."},{"speaker":"Prof Vance","text":"Beyond marine ecology, the discovery of bioluminescent chemical systems has catalyzed breakthroughs in biomedical research. In the 1960s, marine biochemist Osamu Shimomura isolated green fluorescent protein, or GFP, from the crystal jellyfish Aequorea victoria. Today, cellular biologists routinely fuse the genetic code for GFP to human cancer proteins and viral pathogens. When illuminated under blue ultraviolet light, the tagged proteins glow with radiant green fluorescence, allowing researchers to track live tumor metastasis, gene expression, and viral transmission in real time under high-powered microscopes."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l3-q31","questionNumber":31,"prompt":"Over ____ percent of creatures between 200 and 1,000 meters produce light.","correctAnswer":["75","seventy-five"],"explanation":"Prof Vance states: 'over seventy-five percent of all pelagic organisms inhabiting the ocean column'.","evidence":"estimate that over seventy-five percent of all pelagic organisms inhabiting the ocean column"},{"id":"l3-q32","questionNumber":32,"prompt":"The biological substrate molecule oxidized during light production is called ____.","correctAnswer":"luciferin","explanation":"Prof Vance identifies 'a light-emitting substrate molecule called luciferin'.","evidence":"a light-emitting substrate molecule called luciferin, and an enzyme catalyst known as luciferase."},{"id":"l3-q33","questionNumber":33,"prompt":"Bioluminescence is termed cold light because it achieves ____ percent photonic efficiency.","correctAnswer":["95","ninety-five"],"explanation":"Prof Vance highlights: 'achieving ninety-five percent photonic efficiency'.","evidence":"bioluminescence is often described by physicists as cold light, achieving ninety-five percent photonic efficiency"},{"id":"l3-q34","questionNumber":34,"prompt":"Blue-green light travels furthest in seawater because it experiences the lowest optical ____.","correctAnswer":"attenuation","explanation":"Prof Vance notes blue-green light 'experiences the least optical attenuation and penetrates deepest'.","evidence":"experiences the least optical attenuation and penetrates deepest through seawater."},{"id":"l3-q35","questionNumber":35,"prompt":"The glowing bulb on an anglerfish's dorsal spine is scientifically termed the ____.","correctAnswer":"esca","explanation":"Prof Vance refers to 'a bioluminescent photophore bulb—termed the esca'.","evidence":"a bioluminescent photophore bulb—termed the esca—filled with symbiotic luminous bacteria."},{"id":"l3-q36","questionNumber":36,"prompt":"The anglerfish lure is illuminated by symbiotic luminous ____.","correctAnswer":"bacteria","explanation":"Prof Vance mentions the esca is 'filled with symbiotic luminous bacteria.'","evidence":"filled with symbiotic luminous bacteria. Suspended in total darkness"},{"id":"l3-q37","questionNumber":37,"prompt":"Hatchetfish avoid predators below by practicing ____ camouflage.","correctAnswer":"counter-illumination","explanation":"Prof Vance describes hatchetfish practicing 'counter-illumination camouflage.'","evidence":"For defense, many midwater squid and hatchetfish practice counter-illumination camouflage."},{"id":"l3-q38","questionNumber":38,"prompt":"Light-emitting organs situated on the fish's belly are called ventral ____.","correctAnswer":"photophores","explanation":"Prof Vance notes: 'hatchetfish possess ventral photophores on their bellies'.","evidence":"hatchetfish possess ventral photophores on their bellies that emit faint blue light"},{"id":"l3-q39","questionNumber":39,"prompt":"Green fluorescent protein (GFP) was originally isolated from the crystal ____.","correctAnswer":"jellyfish","explanation":"Prof Vance notes GFP was isolated 'from the crystal jellyfish Aequorea victoria.'","evidence":"isolated green fluorescent protein, or GFP, from the crystal jellyfish Aequorea victoria."},{"id":"l3-q40","questionNumber":40,"prompt":"GFP allows modern cancer researchers to track live tumor ____ under microscopes.","correctAnswer":"metastasis","explanation":"Prof Vance concludes: 'allowing researchers to track live tumor metastasis, gene expression'.","evidence":"allowing researchers to track live tumor metastasis, gene expression, and viral transmission in real time"}]}]}]`),me={id:p,title:u,difficulty:h,timeLimitMinutes:m,sections:g},y="list-test-04",f="Listening Practice Test 4",w="standard",b=40,v=JSON.parse(`[{"sectionNumber":1,"title":"Community Cycling Club Membership Registration","contextDescription":"A prospective cyclist, David Brooks, calling the secretary of the Avon Valley Cycling Club, Fiona Clark, to register for membership and weekend club rides.","audioScript":[{"speaker":"Fiona","text":"Good morning! Avon Valley Cycling Club, Fiona speaking. How can I assist you?"},{"speaker":"David","text":"Hello Fiona! I moved to the valley last month and I'm keen to join your cycling group for weekend road rides."},{"speaker":"Fiona","text":"Fantastic! We have riders of all abilities. Are you looking at social leisure rides or our faster training pacelines?"},{"speaker":"David","text":"I'd like to start with the Intermediate Social group. I ride a lightweight aluminum road bike and usually average twenty-four kilometers per hour over fifty kilometers."},{"speaker":"Fiona","text":"That fits our Saturday 'B group' perfectly. Those rides depart every Saturday morning promptly at seven forty-five AM from outside the Millfield Community Centre."},{"speaker":"David","text":"Seven forty-five, got it. What equipment is mandatory?"},{"speaker":"Fiona","text":"First, an EN 1078 approved rigid safety helmet is strictly mandatory—no exceptions. Second, your bike must be equipped with a high-visibility flashing rear red light and front white light, even during daylight rides. You must also carry two spare inner tubes, a hand mini-pump, and a multi-tool."},{"speaker":"David","text":"I have all of those in my saddlebag. What is the annual membership fee?"},{"speaker":"Fiona","text":"The annual adult membership is thirty-eight pounds, which includes third-party liability insurance coverage through British Cycling and a ten percent discount at Pedals Bike Shop in town."},{"speaker":"David","text":"That's exceptional value. Can I register right now?"},{"speaker":"Fiona","text":"Certainly! Let me take down your particulars. What is your full legal name?"},{"speaker":"David","text":"It's David Brooks, that's B-R-O-O-K-S."},{"speaker":"Fiona","text":"And your residential street address, David?"},{"speaker":"David","text":"It's twenty-four Orchard Lane, Avonbury."},{"speaker":"Fiona","text":"Postcode?"},{"speaker":"David","text":"BA15 2PQ."},{"speaker":"Fiona","text":"And an emergency contact name and phone number?"},{"speaker":"David","text":"My sister, Claire Brooks, on zero seven eight nine one, four four three two one zero."},{"speaker":"Fiona","text":"Splendid. I'll email you the membership welcome pack. You can collect your club jersey at our social coffee meet this Thursday evening at eight o'clock at the Riverside Cafe."},{"speaker":"David","text":"Riverside Cafe this Thursday at eight. See you then, Fiona!"}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l4-q1","questionNumber":1,"prompt":"Selected cycling group: Intermediate ____ group.","correctAnswer":"Social","explanation":"David says: 'I'd like to start with the Intermediate Social group.'","evidence":"I'd like to start with the Intermediate Social group."},{"id":"l4-q2","questionNumber":2,"prompt":"Saturday rides departure time: ____ AM.","correctAnswer":["7:45","7.45","seven forty-five"],"explanation":"Fiona explains rides depart 'promptly at seven forty-five AM'.","evidence":"Those rides depart every Saturday morning promptly at seven forty-five AM"},{"id":"l4-q3","questionNumber":3,"prompt":"Ride departure location: outside the Millfield ____ Centre.","correctAnswer":"Community","explanation":"Fiona notes departure from 'outside the Millfield Community Centre.'","evidence":"from outside the Millfield Community Centre."},{"id":"l4-q4","questionNumber":4,"prompt":"Mandatory safety item: approved rigid safety ____.","correctAnswer":"helmet","explanation":"Fiona notes 'an EN 1078 approved rigid safety helmet is strictly mandatory'.","evidence":"First, an EN 1078 approved rigid safety helmet is strictly mandatory"},{"id":"l4-q5","questionNumber":5,"prompt":"Emergency repair kit: two spare inner ____ and a mini-pump.","correctAnswer":"tubes","explanation":"Fiona specifies 'two spare inner tubes, a hand mini-pump, and a multi-tool.'","evidence":"You must also carry two spare inner tubes, a hand mini-pump, and a multi-tool."},{"id":"l4-q6","questionNumber":6,"prompt":"Annual membership fee: £____.","correctAnswer":["38","thirty-eight","38 pounds"],"explanation":"Fiona states: 'annual adult membership is thirty-eight pounds'.","evidence":"The annual adult membership is thirty-eight pounds"},{"id":"l4-q7","questionNumber":7,"prompt":"Applicant's surname: ____.","correctAnswer":"Brooks","explanation":"David spells B-R-O-O-K-S.","evidence":"It's David Brooks, that's B-R-O-O-K-S."},{"id":"l4-q8","questionNumber":8,"prompt":"Street address: 24 ____ Lane.","correctAnswer":"Orchard","explanation":"David gives his address as 'twenty-four Orchard Lane, Avonbury.'","evidence":"It's twenty-four Orchard Lane, Avonbury."},{"id":"l4-q9","questionNumber":9,"prompt":"Emergency contact relation: ____.","correctAnswer":"sister","explanation":"David states: 'My sister, Claire Brooks'.","evidence":"My sister, Claire Brooks, on zero seven eight nine one"},{"id":"l4-q10","questionNumber":10,"prompt":"Social coffee meet venue: ____ Cafe.","correctAnswer":"Riverside","explanation":"Fiona mentions 'social coffee meet this Thursday evening at eight o'clock at the Riverside Cafe.'","evidence":"at eight o'clock at the Riverside Cafe."}]}]},{"sectionNumber":2,"title":"Audio Guide to the Heritage Industrial Watermill Museum","contextDescription":"The resident curator, Arthur Pendelton, introducing visitors to the historic water-powered grain mill and industrial iron forge.","audioScript":[{"speaker":"Curator","text":"Welcome to the Blackwood Heritage Watermill, situated on the swift currents of the River Calder. This site has sustained industrial milling activity since the eleventh century, when the Domesday Book recorded a timber watermill here grinding rye and barley for the local feudal estate."},{"speaker":"Curator","text":"The current three-story stone mill before you was constructed in 1782 by master millwright Thomas Hesketh. It was designed to harness the energy of falling water through our magnificent six-meter breastshot iron waterwheel. If you look at the riverbank to your left, you can see the millrace canal, which diverted river water along a controlled timber flume to turn the giant wheel at twelve revolutions per minute."},{"speaker":"Curator","text":"Inside the ground floor, known as the Wheelpit Chamber, the rotating waterwheel turns a primary cast-iron pit gear weighing four metric tons. This immense gear engages a vertical timber drive shaft known as the upright shaft, which transfers mechanical torque upwards to the first-floor Stone Floor."},{"speaker":"Curator","text":"On the Stone Floor, visitors can inspect three pairs of historic millstones. Two pairs are crafted from French buhrstone—a freshwater quartz renowned for its exceptional hardness—used exclusively for grinding pure white wheat flour. The third pair is cut from local gritstone, used for milling coarser animal feed. Notice the hopper funnels above, which vibrated rhythmically to feed grain evenly into the center eye of the rotating runner stone."},{"speaker":"Curator","text":"Moving to the second floor, or the Grain Loft, you can view the mechanical sack hoist. This ingenious pulley system was powered by the waterwheel itself, allowing a single miller to lift fifty-kilogram sacks of harvested grain from horse-drawn wagons on the ground straight into the attic storage bins."},{"speaker":"Curator","text":"Before you explore, please observe our safety rules: due to historic exposed timber beams, hard hats must be worn in the lower basement, and smoking or open flames are strictly forbidden across the complex because airborne flour dust is combustible. Traditional stone-ground wholemeal flour packaged in cotton sacks is available for purchase in the Mill Bakehouse adjacent to the waterwheel."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–15.","questionType":"multiple_choice","questions":[{"id":"l4-q11","questionNumber":11,"prompt":"When was the present stone mill structure built by Thomas Hesketh?","options":["1682","1782","1882"],"correctAnswer":"B","explanation":"The curator states the mill 'was constructed in 1782 by master millwright Thomas Hesketh.'","evidence":"The current three-story stone mill before you was constructed in 1782 by master millwright Thomas Hesketh."},{"id":"l4-q12","questionNumber":12,"prompt":"At what speed did the breastshot waterwheel rotate during milling?","options":["25 revolutions per minute","50 revolutions per minute","12 revolutions per minute"],"correctAnswer":"C","explanation":"The curator notes it turned 'at twelve revolutions per minute.'","evidence":"to turn the giant wheel at twelve revolutions per minute."},{"id":"l4-q13","questionNumber":13,"prompt":"What were the French buhrstone millstones used to grind?","options":["Pure white wheat flour","Coarse animal fodder","Metal filings for paint pigment"],"correctAnswer":"A","explanation":"The curator states French buhrstone was 'used exclusively for grinding pure white wheat flour.'","evidence":"used exclusively for grinding pure white wheat flour."},{"id":"l4-q14","questionNumber":14,"prompt":"What powered the attic sack hoist in the Grain Loft?","options":["A steam donkey engine","The waterwheel itself via pulleys","Manual hand cranks only"],"correctAnswer":"B","explanation":"The curator explains: 'This ingenious pulley system was powered by the waterwheel itself'.","evidence":"This ingenious pulley system was powered by the waterwheel itself"},{"id":"l4-q15","questionNumber":15,"prompt":"Why are open flames strictly prohibited across the mill complex?","options":["Dry wooden floorboards are coated in beeswax","Historical fabrics are stored in the attic","Airborne flour dust is explosive and combustible"],"correctAnswer":"C","explanation":"The curator warns: 'smoking or open flames are strictly forbidden across the complex because airborne flour dust is combustible.'","evidence":"smoking or open flames are strictly forbidden across the complex because airborne flour dust is combustible."}]},{"groupInstruction":"Match the following mill features (16–20) with the floor or area where they are located (A–E). Write the correct letter in boxes 16–20.\\nA: Riverbank exterior\\nB: Ground floor (Wheelpit Chamber)\\nC: First floor (Stone Floor)\\nD: Second floor (Grain Loft)\\nE: Adjacent outbuilding","questionType":"matching","questions":[{"id":"l4-q16","questionNumber":16,"prompt":"Millrace canal and timber flume","correctAnswer":"A","explanation":"The curator points to 'the riverbank to your left, you can see the millrace canal'.","evidence":"If you look at the riverbank to your left, you can see the millrace canal"},{"id":"l4-q17","questionNumber":17,"prompt":"Primary cast-iron pit gear","correctAnswer":"B","explanation":"The curator describes the pit gear 'Inside the ground floor, known as the Wheelpit Chamber'.","evidence":"Inside the ground floor, known as the Wheelpit Chamber, the rotating waterwheel turns a primary cast-iron pit gear"},{"id":"l4-q18","questionNumber":18,"prompt":"Vibrating hopper funnels and runner stones","correctAnswer":"C","explanation":"The curator describes them on the 'first-floor Stone Floor.'","evidence":"transfers mechanical torque upwards to the first-floor Stone Floor. On the Stone Floor, visitors can inspect three pairs of historic millstones."},{"id":"l4-q19","questionNumber":19,"prompt":"Mechanical sack hoist pulley system","correctAnswer":"D","explanation":"The curator describes the hoist on the 'second floor, or the Grain Loft'.","evidence":"Moving to the second floor, or the Grain Loft, you can view the mechanical sack hoist."},{"id":"l4-q20","questionNumber":20,"prompt":"Mill Bakehouse selling stone-ground flour","correctAnswer":"E","explanation":"The curator mentions purchase in the 'Mill Bakehouse adjacent to the waterwheel.'","evidence":"available for purchase in the Mill Bakehouse adjacent to the waterwheel."}]}]},{"sectionNumber":3,"title":"Psychology Tutorial: Memory Retention and Spaced Repetition","contextDescription":"Two cognitive psychology students, Maya and Alex, discussing memory consolidation experiments with their course tutor, Dr. Patel.","audioScript":[{"speaker":"Dr Patel","text":"Good morning, Maya, Alex. How are the preparations for your seminar presentation on experimental memory paradigms coming along?"},{"speaker":"Maya","text":"Very well, Dr. Patel. We're structuring our analysis around Hermann Ebbinghaus's pioneering nineteenth-century experiments on the forgetting curve."},{"speaker":"Alex","text":"Right. Ebbinghaus tested his own recall of nonsense three-letter syllables and discovered that forgetting does not occur linearly. Instead, memory decay is exponential: roughly fifty percent of newly learned material is forgotten within the first twenty minutes, and up to seventy percent disappears within twenty-four hours without active reinforcement."},{"speaker":"Dr Patel","text":"Precisely. And what modern cognitive mechanism counters this exponential decay?"},{"speaker":"Maya","text":"Spaced repetition and active retrieval practice. When a student attempts active recall—testing themselves rather than passively re-reading highlighting notes—the brain must expend cognitive effort to retrieve information from long-term storage. This retrieval effort signals to the brain that the memory trace is biologically critical, prompting synaptic strengthening."},{"speaker":"Alex","text":"We also analyzed Sebastian Leitner's box system from the 1970s. Leitner organized paper flashcards into five physical compartments. Cards answered correctly move to higher boxes that are reviewed at progressively wider intervals—say, every three days, then every week, then every month. Conversely, any lapsed card that is forgotten is immediately banished back to Box One for daily review."},{"speaker":"Dr Patel","text":"An elegant algorithm. How are you integrating modern algorithmic adaptations like the SuperMemo-2 (SM-2) model?"},{"speaker":"Maya","text":"We coded a JavaScript demonstration that computes dynamic intervals using an ease factor. Each card starts with an ease factor of two point five. When a user rates a card as 'easy', the ease factor rises, expanding the next review interval. If they rate it 'again', repetitions reset to zero and the ease factor drops, ensuring difficult vocabulary receives frequent exposure."},{"speaker":"Dr Patel","text":"Superb. Be sure to highlight the 'spacing effect' in your slides: four thirty-minute study sessions distributed across four days produce far higher retention than a single two-hour cramming session, even though total study time is identical."},{"speaker":"Alex","text":"Yes, we have created comparative bar charts illustrating that exact finding for our tutorial handout."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–25.","questionType":"multiple_choice","questions":[{"id":"l4-q21","questionNumber":21,"prompt":"What did Ebbinghaus discover about the rate of human forgetting?","options":["It decays exponentially, with the steepest drop within 24 hours","It happens at a steady, linear pace over a month","It only occurs when people are asleep"],"correctAnswer":"A","explanation":"Alex states forgetting is 'exponential: roughly fifty percent... within the first twenty minutes, and up to seventy percent disappears within twenty-four hours'.","evidence":"Instead, memory decay is exponential: roughly fifty percent of newly learned material is forgotten within the first twenty minutes, and up to seventy percent disappears within twenty-four hours"},{"id":"l4-q22","questionNumber":22,"prompt":"Why is active retrieval practice more effective than passive re-reading?","options":["It requires less study time","Cognitive retrieval effort triggers synaptic strengthening","It completely eliminates the need for future review"],"correctAnswer":"B","explanation":"Maya explains 'retrieval effort signals to the brain that the memory trace is biologically critical, prompting synaptic strengthening.'","evidence":"This retrieval effort signals to the brain that the memory trace is biologically critical, prompting synaptic strengthening."},{"id":"l4-q23","questionNumber":23,"prompt":"In the Leitner flashcard box system, what happens to a forgotten card?","options":["It is thrown away","It stays in the same box for one more day","It is sent immediately back to Box One"],"correctAnswer":"C","explanation":"Alex states: 'any lapsed card that is forgotten is immediately banished back to Box One for daily review.'","evidence":"Conversely, any lapsed card that is forgotten is immediately banished back to Box One for daily review."},{"id":"l4-q24","questionNumber":24,"prompt":"What is the standard starting ease factor in the SM-2 algorithm?","options":["2.5","1.3","4.0"],"correctAnswer":"A","explanation":"Maya states: 'Each card starts with an ease factor of two point five.'","evidence":"Each card starts with an ease factor of two point five."},{"id":"l4-q25","questionNumber":25,"prompt":"What is the practical takeaway of the 'spacing effect'?","options":["Cramming before an exam creates stronger neural connections","Distributing study sessions over several days produces superior retention","Studying in a quiet room is the only factor in exam success"],"correctAnswer":"B","explanation":"Dr Patel explains 'four thirty-minute study sessions distributed across four days produce far higher retention than a single two-hour cramming session'.","evidence":"four thirty-minute study sessions distributed across four days produce far higher retention than a single two-hour cramming session"}]},{"groupInstruction":"Complete the sentences below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 26–30.","questionType":"sentence_completion","questions":[{"id":"l4-q26","questionNumber":26,"prompt":"Ebbinghaus tested memory retention using nonsense ____ syllables.","correctAnswer":"three-letter","explanation":"Alex refers to 'nonsense three-letter syllables'.","evidence":"Ebbinghaus tested his own recall of nonsense three-letter syllables"},{"id":"l4-q27","questionNumber":27,"prompt":"Approximately ____ percent of newly memorized info is lost within twenty minutes without review.","correctAnswer":["50","fifty"],"explanation":"Alex notes: 'roughly fifty percent of newly learned material is forgotten within the first twenty minutes'.","evidence":"roughly fifty percent of newly learned material is forgotten within the first twenty minutes"},{"id":"l4-q28","questionNumber":28,"prompt":"Sebastian Leitner's box system utilized ____ physical flashcard compartments.","correctAnswer":["5","five"],"explanation":"Alex states: 'organized paper flashcards into five physical compartments.'","evidence":"Leitner organized paper flashcards into five physical compartments."},{"id":"l4-q29","questionNumber":29,"prompt":"When a user rates a flashcard as 'again', the repetition count resets to ____.","correctAnswer":["0","zero"],"explanation":"Maya says: 'repetitions reset to zero and the ease factor drops'.","evidence":"If they rate it 'again', repetitions reset to zero and the ease factor drops"},{"id":"l4-q30","questionNumber":30,"prompt":"The students prepared comparative ____ charts for their tutorial handout.","correctAnswer":"bar","explanation":"Alex concludes: 'we have created comparative bar charts illustrating that exact finding'.","evidence":"we have created comparative bar charts illustrating that exact finding for our tutorial handout."}]}]},{"sectionNumber":4,"title":"Academic Lecture on Early Metallurgy and the Bronze Age Tin Trade","contextDescription":"Dr. Gregory Thorne giving an archaeology lecture on Bronze Age copper smelting and maritime trade routes for tin.","audioScript":[{"speaker":"Dr Thorne","text":"Good morning, everyone. In today's lecture on prehistoric technology, we examine the material transition that fundamentally redefined human societal complexity: the dawn of the Bronze Age during the third millennium BCE. Before the mastery of bronze, human societies relied on copper, native gold, and stone. While pure copper was a malleable metal that could be cold-hammered or melted into decorative ornaments and rudimentary awls, it possessed significant structural shortcomings: it was soft, blunted rapidly against bone or wood, and lacked the tensile strength required for durable cutting tools or military weapons."},{"speaker":"Dr Thorne","text":"The technological breakthrough occurred with the deliberate discovery of alloying—combining molten copper with a secondary hardening agent. Early metallurgists first experimented with arsenic-rich copper ores, producing arsenical bronze. However, arsenic smelting was lethally toxic to smiths, causing peripheral neuropathy and early mortality. Around 2500 BCE, ancient metalworkers discovered that adding approximately ten to twelve percent metallic tin to copper created true tin-bronze—an alloy of remarkable hardness, lower melting temperature, and superior casting fluidity that expanded into intricate mould crevices."},{"speaker":"Dr Thorne","text":"This metallurgical revolution created an acute geopolitical problem: the scarcity of tin. Copper ores—such as malachite and chalcopyrite—were relatively abundant across Cyprus, Anatolia, and the Levant. In fact, the word 'copper' derives from the Latin cuprum, meaning 'metal of Cyprus'. Tin, however, was exceptionally rare in the ancient Near East, found almost exclusively in the mineral form of cassiterite. Consequently, to sustain bronze production, Near Eastern kingdoms were forced to organize vast, transcontinental trade networks spanning thousands of kilometers to obtain tin from distant alluvial gravels in modern-day Afghanistan, Uzbekistan, and Cornwall in southwestern Britain."},{"speaker":"Dr Thorne","text":"To transport copper and tin safely across the treacherous Mediterranean, merchants smelted metals into standardized, portable ingots. Archaeological shipwrecks, such as the famous Uluburun wreck excavated off the southern coast of Turkey dating to 1300 BCE, revealed hundreds of copper ingots cast in the distinctive 'oxhide' shape—rectangular slabs with four protruding corner handles designed specifically to allow two dock laborers to carry a thirty-kilogram ingot across narrow ship gangplanks."},{"speaker":"Dr Thorne","text":"The interdependence of this international tin and copper exchange created the world's first globalized economy. When mysterious maritime raiders, known as the Sea Peoples, disrupted Eastern Mediterranean trade corridors around 1200 BCE, the tin supply chain abruptly fractured. Unable to secure tin to manufacture bronze, regional empires collapsed within decades, precipitating the Late Bronze Age Collapse and forcing metalworkers to turn to an abundant, difficult, but universally accessible alternative: iron."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l4-q31","questionNumber":31,"prompt":"The Bronze Age began to redefine human society during the ____ millennium BCE.","correctAnswer":["third","3rd"],"explanation":"Dr Thorne states the Bronze Age began 'during the third millennium BCE.'","evidence":"the dawn of the Bronze Age during the third millennium BCE."},{"id":"l4-q32","questionNumber":32,"prompt":"Early metallurgists first alloyed copper with toxic ____ ores.","correctAnswer":"arsenic","explanation":"Dr Thorne notes smiths 'first experimented with arsenic-rich copper ores'.","evidence":"Early metallurgists first experimented with arsenic-rich copper ores, producing arsenical bronze."},{"id":"l4-q33","questionNumber":33,"prompt":"True tin-bronze requires adding roughly ____ to twelve percent tin to molten copper.","correctAnswer":["10","ten"],"explanation":"Dr Thorne states: 'adding approximately ten to twelve percent metallic tin'.","evidence":"adding approximately ten to twelve percent metallic tin to copper created true tin-bronze"},{"id":"l4-q34","questionNumber":34,"prompt":"The English word 'copper' comes from the Latin name for the island of ____.","correctAnswer":"Cyprus","explanation":"Dr Thorne explains cuprum means 'metal of Cyprus'.","evidence":"the word 'copper' derives from the Latin cuprum, meaning 'metal of Cyprus'."},{"id":"l4-q35","questionNumber":35,"prompt":"Tin in nature is found almost exclusively in the mineral form of ____.","correctAnswer":"cassiterite","explanation":"Dr Thorne names 'the mineral form of cassiterite.'","evidence":"found almost exclusively in the mineral form of cassiterite."},{"id":"l4-q36","questionNumber":36,"prompt":"Tin was sourced from distant locations including Afghanistan, Uzbekistan, and ____ in Britain.","correctAnswer":"Cornwall","explanation":"Dr Thorne specifies 'Cornwall in southwestern Britain.'","evidence":"and Cornwall in southwestern Britain."},{"id":"l4-q37","questionNumber":37,"prompt":"The famous Bronze Age shipwreck excavated off Turkey is known as the ____ wreck.","correctAnswer":"Uluburun","explanation":"Dr Thorne names 'the famous Uluburun wreck excavated off the southern coast of Turkey'.","evidence":"such as the famous Uluburun wreck excavated off the southern coast of Turkey"},{"id":"l4-q38","questionNumber":38,"prompt":"Standardized copper slabs were cast in the distinctive ____ shape with four handles.","correctAnswer":"oxhide","explanation":"Dr Thorne describes ingots cast 'in the distinctive 'oxhide' shape'.","evidence":"cast in the distinctive 'oxhide' shape—rectangular slabs with four protruding corner handles"},{"id":"l4-q39","questionNumber":39,"prompt":"Trade corridors around 1200 BCE were disrupted by raiders known as the ____.","correctAnswer":"Sea Peoples","explanation":"Dr Thorne cites raiders 'known as the Sea Peoples'.","evidence":"mysterious maritime raiders, known as the Sea Peoples, disrupted Eastern Mediterranean trade corridors"},{"id":"l4-q40","questionNumber":40,"prompt":"The collapse of the tin trade forced metalworkers to transition to using ____.","correctAnswer":"iron","explanation":"Dr Thorne concludes: 'forcing metalworkers to turn to an abundant, difficult, but universally accessible alternative: iron.'","evidence":"forcing metalworkers to turn to an abundant, difficult, but universally accessible alternative: iron."}]}]}]`),ge={id:y,title:f,difficulty:w,timeLimitMinutes:b,sections:v},x="list-test-05",_="Listening Practice Test 5",k="standard",q=40,A=JSON.parse(`[{"sectionNumber":1,"title":"International Academic Conference Venue & Catering Booking","contextDescription":"Conference coordinator Elena Martinez booking facilities for the Annual Renewable Energy Symposium with James Thornton at the University Conference Centre.","audioScript":[{"speaker":"James","text":"Good morning! University Conference Centre, James Thornton speaking. How can I help with your event?"},{"speaker":"Elena","text":"Hello James! I'm Elena Martinez from the School of Environmental Science. I'm calling to book facilities for our Annual Renewable Energy Symposium this autumn."},{"speaker":"James","text":"Splendid! What dates are you looking to hold the symposium?"},{"speaker":"Elena","text":"We need the venue for two days: Thursday the eighteenth and Friday the nineteenth of October."},{"speaker":"James","text":"Let me check our calendar... Yes, the East Wing is completely open. Approximately how many registered delegates are you anticipating?"},{"speaker":"Elena","text":"We expect around two hundred and fifty attendees each day."},{"speaker":"James","text":"In that case, the Kelvin Auditorium would be ideal. It seats three hundred, features tiered acoustic seating, dual laser projectors, and four wireless lapel microphones."},{"speaker":"Elena","text":"That sounds perfect for the morning keynote lectures. We'll also require three smaller breakout rooms for afternoon panel discussions. Can we use seminar rooms four, five, and six?"},{"speaker":"James","text":"Yes, those seminar rooms each seat forty people and have interactive whiteboards."},{"speaker":"Elena","text":"Great. Now regarding catering: we'd like morning coffee and pastries served at ten fifteen, a hot buffet lunch at twelve thirty, and afternoon tea with biscuits at three forty-five."},{"speaker":"Elena","text":"We have some dietary requirements: out of the two hundred and fifty delegates, thirty are vegetarian, fifteen are vegan, and eight require gluten-free meals."},{"speaker":"James","text":"No problem at all; our executive chef prepares clearly labelled individual dietary platters. What about evening events?"},{"speaker":"Elena","text":"We'd like to host a drinks reception on Thursday evening from six to seven thirty in the Glass Conservatory overlooking the campus gardens."},{"speaker":"James","text":"The Glass Conservatory is magnificent at sunset. I'll prepare a formal quote. What is your department billing code?"},{"speaker":"Elena","text":"It's ENV, hyphen, eight four zero two."},{"speaker":"James","text":"ENV-8402. And what contact phone number should I put on the invoice?"},{"speaker":"Elena","text":"You can reach my direct desk extension at zero one six one, four nine six, zero three seven five."},{"speaker":"James","text":"Thank you, Elena. I'll email the contract and catering breakdown by five PM today."}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l5-q1","questionNumber":1,"prompt":"Conference event name: Annual ____ Energy Symposium.","correctAnswer":"Renewable","explanation":"Elena states: 'Annual Renewable Energy Symposium this autumn.'","evidence":"Annual Renewable Energy Symposium this autumn."},{"id":"l5-q2","questionNumber":2,"prompt":"Event dates: 18th and 19th of ____.","correctAnswer":"October","explanation":"Elena states: 'Thursday the eighteenth and Friday the nineteenth of October.'","evidence":"Thursday the eighteenth and Friday the nineteenth of October."},{"id":"l5-q3","questionNumber":3,"prompt":"Anticipated daily attendance: ____ delegates.","correctAnswer":["250","two hundred and fifty"],"explanation":"Elena expects 'around two hundred and fifty attendees each day.'","evidence":"We expect around two hundred and fifty attendees each day."},{"id":"l5-q4","questionNumber":4,"prompt":"Primary morning lecture hall: the ____ Auditorium.","correctAnswer":"Kelvin","explanation":"James suggests: 'the Kelvin Auditorium would be ideal.'","evidence":"the Kelvin Auditorium would be ideal. It seats three hundred"},{"id":"l5-q5","questionNumber":5,"prompt":"Afternoon panel discussions will use three smaller ____ rooms.","correctAnswer":"breakout","explanation":"Elena says: 'require three smaller breakout rooms for afternoon panel discussions.'","evidence":"We'll also require three smaller breakout rooms for afternoon panel discussions."},{"id":"l5-q6","questionNumber":6,"prompt":"Hot buffet lunch scheduled time: ____ PM.","correctAnswer":["12:30","12.30","twelve thirty"],"explanation":"Elena requests 'a hot buffet lunch at twelve thirty'.","evidence":"a hot buffet lunch at twelve thirty"},{"id":"l5-q7","questionNumber":7,"prompt":"Number of gluten-free meals required: ____.","correctAnswer":["8","eight"],"explanation":"Elena states: 'and eight require gluten-free meals.'","evidence":"and eight require gluten-free meals."},{"id":"l5-q8","questionNumber":8,"prompt":"Thursday evening drinks reception venue: the Glass ____.","correctAnswer":"Conservatory","explanation":"Elena mentions 'in the Glass Conservatory overlooking the campus gardens.'","evidence":"in the Glass Conservatory overlooking the campus gardens."},{"id":"l5-q9","questionNumber":9,"prompt":"Department billing code: ENV-____.","correctAnswer":"8402","explanation":"Elena gives code: 'ENV, hyphen, eight four zero two.'","evidence":"It's ENV, hyphen, eight four zero two."},{"id":"l5-q10","questionNumber":10,"prompt":"Desk phone extension number: 0161 496 ____.","correctAnswer":"0375","explanation":"Elena gives number: 'zero one six one, four nine six, zero three seven five.'","evidence":"zero one six one, four nine six, zero three seven five."}]}]},{"sectionNumber":2,"title":"Wilderness Trail Volunteer Ranger Induction Briefing","contextDescription":"Head Ranger Gordon MacLeod welcoming newly arrived conservation volunteers to the Glencree Wilderness Reserve.","audioScript":[{"speaker":"Gordon","text":"Good morning, everyone, and welcome to Glencree Wilderness Reserve. I'm Head Ranger Gordon MacLeod. Over the next fortnight, you'll be undertaking vital trail restoration and native tree planting across sixty square miles of protected Caledonian pine forest."},{"speaker":"Gordon","text":"Before we hand out your tools, let me familiarize you with the reserve compound and our trail network. We are currently gathered at the Visitor Welcome Lodge. If you look straight ahead through the rear glass doors, you can see the Old Sawmill Barn, where our heavy tools, wheelbarrows, and mattocks are stored in locked bay three."},{"speaker":"Gordon","text":"Our main task this week focuses on the Eagle Crag Trail. To reach Eagle Crag, you take the main gravel track heading northeast past the stone footbridge. The first two miles of the trail traverse lowland peat bog. Last winter's torrential rainfall washed away thirty meters of timber boardwalk; our team will be installing replacement composite recycled-plastic sleepers, which last forty years without rotting in wet peat."},{"speaker":"Gordon","text":"Beyond the bog section, the trail climbs steeply through the Gorge of Birches. Here, severe foot erosion has undercut the cliff path. We will be building stone waterbars—diagonal drainage channels embedded into the trail surface to divert rainwater away into the gully before it can wash away the topsoil."},{"speaker":"Gordon","text":"At the summit ridge stands the Eagle Observation Shelter. From here, volunteers will conduct hourly surveys of breeding golden eagles. Remember to bring warm waterproof clothing; wind speeds on the summit ridge frequently reach forty knots, even in summer."},{"speaker":"Gordon","text":"A crucial safety protocol: Glencree is a tick habitat, particularly in tall bracken fern. At the end of every work shift, you must conduct a thorough tick inspection before showering. Any tick bites must be removed with specialized tweezers and recorded in the medical log in the First Aid Room situated next to the Volunteer Kitchen."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–15.","questionType":"multiple_choice","questions":[{"id":"l5-q11","questionNumber":11,"prompt":"Where are wheelbarrows and heavy trail tools stored in the compound?","options":["Beside the stone footbridge","In the Volunteer Kitchen cellar","In bay three of the Old Sawmill Barn"],"correctAnswer":"C","explanation":"Gordon says: 'the Old Sawmill Barn, where our heavy tools, wheelbarrows, and mattocks are stored in locked bay three.'","evidence":"the Old Sawmill Barn, where our heavy tools, wheelbarrows, and mattocks are stored in locked bay three."},{"id":"l5-q12","questionNumber":12,"prompt":"Why are volunteers installing composite recycled-plastic sleepers on the boardwalk?","options":["They do not rot in wet peat and last 40 years","They are lighter to transport on foot","They blend in better with native pine needles"],"correctAnswer":"A","explanation":"Gordon explains: 'which last forty years without rotting in wet peat.'","evidence":"replacement composite recycled-plastic sleepers, which last forty years without rotting in wet peat."},{"id":"l5-q13","questionNumber":13,"prompt":"What is the purpose of the stone waterbars in the Gorge of Birches?","options":["To create seats for hikers","To divert rainwater into the gully to prevent trail erosion","To mark boundary lines between private estates"],"correctAnswer":"B","explanation":"Gordon states waterbars are: 'diagonal drainage channels embedded into the trail surface to divert rainwater away into the gully before it can wash away the topsoil.'","evidence":"diagonal drainage channels embedded into the trail surface to divert rainwater away into the gully before it can wash away the topsoil."},{"id":"l5-q14","questionNumber":14,"prompt":"What bird species will volunteers monitor from the summit shelter?","options":["Peregrine falcons","Scottish crossbills","Golden eagles"],"correctAnswer":"C","explanation":"Gordon explains: 'volunteers will conduct hourly surveys of breeding golden eagles.'","evidence":"volunteers will conduct hourly surveys of breeding golden eagles."},{"id":"l5-q15","questionNumber":15,"prompt":"Where is the reserve First Aid Room located?","options":["Next to the Volunteer Kitchen","Beside the Old Sawmill Barn","At the summit shelter"],"correctAnswer":"A","explanation":"Gordon notes it is 'in the First Aid Room situated next to the Volunteer Kitchen.'","evidence":"in the First Aid Room situated next to the Volunteer Kitchen."}]},{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 16–20.","questionType":"sentence_completion","questions":[{"id":"l5-q16","questionNumber":16,"prompt":"The reserve encompasses 60 square miles of protected ____ pine forest.","correctAnswer":"Caledonian","explanation":"Gordon refers to 'protected Caledonian pine forest.'","evidence":"across sixty square miles of protected Caledonian pine forest."},{"id":"l5-q17","questionNumber":17,"prompt":"Winter torrential rain destroyed ____ meters of timber boardwalk.","correctAnswer":["30","thirty"],"explanation":"Gordon notes: 'rainfall washed away thirty meters of timber boardwalk'.","evidence":"rainfall washed away thirty meters of timber boardwalk"},{"id":"l5-q18","questionNumber":18,"prompt":"The trail path through the Gorge of Birches has suffered from foot ____.","correctAnswer":"erosion","explanation":"Gordon points out: 'severe foot erosion has undercut the cliff path.'","evidence":"severe foot erosion has undercut the cliff path."},{"id":"l5-q19","questionNumber":19,"prompt":"Wind speeds on the summit ridge can reach ____ knots during summer.","correctAnswer":["40","forty"],"explanation":"Gordon states: 'wind speeds on the summit ridge frequently reach forty knots'.","evidence":"wind speeds on the summit ridge frequently reach forty knots, even in summer."},{"id":"l5-q20","questionNumber":20,"prompt":"Volunteers must check their bodies for ____ after working in bracken.","correctAnswer":"ticks","explanation":"Gordon highlights: 'Glencree is a tick habitat... you must conduct a thorough tick inspection'.","evidence":"Glencree is a tick habitat, particularly in tall bracken fern... conduct a thorough tick inspection"}]}]},{"sectionNumber":3,"title":"Economics Tutorial on Microfinance and Rural Credit Dynamics","contextDescription":"Two economics students, Priya and Daniel, discussing their research paper on microcredit institutions with Professor Al-Mansoor.","audioScript":[{"speaker":"Prof Mansoor","text":"Good afternoon, Priya, Daniel. How is your comparative study on microfinance initiatives in South Asia and East Africa progressing?"},{"speaker":"Priya","text":"Very well, Professor. We've focused our core analysis on the Grameen Bank model, pioneered in Bangladesh by Muhammad Yunus in the late 1970s."},{"speaker":"Daniel","text":"What fascinated us is how the model addressed the fundamental obstacle of rural banking: the lack of physical collateral. Traditional commercial banks refuse to lend to impoverished rural women because they possess no land deeds or property to pledge against default."},{"speaker":"Prof Mansoor","text":"Indeed. And what structural innovation circumvented that absence of physical collateral?"},{"speaker":"Priya","text":"Group lending with joint liability. Five borrowers from the same village form a solidarity circle. The bank issues initial loans to only two members. The remaining three members can only access their credit after the first two borrow and maintain prompt weekly repayments. This leverages social capital and community trust; peer monitoring replaces legal collateral."},{"speaker":"Daniel","text":"And the statistical results are striking: Grameen reported repayment rates exceeding ninety-seven percent, substantially higher than typical commercial corporate debt portfolios."},{"speaker":"Prof Mansoor","text":"Remarkable. However, does your paper also address the critiques of microfinance?"},{"speaker":"Priya","text":"Yes, we dedicated a whole chapter to the commercialization of microcredit. When private equity firms entered the sector in the 2000s, some institutions raised annual interest rates to thirty or even forty percent. Aggressive loan recovery practices led to severe borrower distress and over-indebtedness in certain provinces."},{"speaker":"Daniel","text":"On the other hand, in Kenya, the integration of mobile money platforms like M-Pesa has drastically reduced transaction overheads. Borrowers can repay loans via mobile SMS messages, eliminating the need for loan officers to travel long distances on motorbikes to collect paper cash."},{"speaker":"Prof Mansoor","text":"Excellent balance. For your presentation slides, make sure you compare average loan sizes: early Grameen loans were typically under one hundred US dollars, aimed at working capital for livestock or weaving, whereas modern micro-enterprises often seek five hundred to one thousand dollars for solar irrigation pumps."},{"speaker":"Priya","text":"We have that comparative table ready for the tutorial symposium on Monday!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–25.","questionType":"multiple_choice","questions":[{"id":"l5-q21","questionNumber":21,"prompt":"Why had commercial banks traditionally refused to lend to poor rural women?","options":["Government laws prohibited banking in rural areas","Women lacked physical collateral such as land deeds","Rural interest rates were capped at zero"],"correctAnswer":"B","explanation":"Daniel states commercial banks refused because women 'possess no land deeds or property to pledge against default.'","evidence":"Traditional commercial banks refuse to lend to impoverished rural women because they possess no land deeds or property to pledge against default."},{"id":"l5-q22","questionNumber":22,"prompt":"In the Grameen group lending model, how many members form a solidarity circle?","options":["3","10","5"],"correctAnswer":"C","explanation":"Priya explains: 'Five borrowers from the same village form a solidarity circle.'","evidence":"Five borrowers from the same village form a solidarity circle."},{"id":"l5-q23","questionNumber":23,"prompt":"What repayment rate was achieved under the Grameen model?","options":["Over 97 percent","Over 80 percent","Over 90 percent"],"correctAnswer":"A","explanation":"Daniel notes: 'Grameen reported repayment rates exceeding ninety-seven percent'.","evidence":"Grameen reported repayment rates exceeding ninety-seven percent, substantially higher than typical commercial corporate debt portfolios."},{"id":"l5-q24","questionNumber":24,"prompt":"What problem arose when private equity firms commercialized microcredit?","options":["Mobile phones were banned by governments","Interest rates surged to 30 or 40 percent leading to over-indebtedness","Banks refused to accept any repayments in cash"],"correctAnswer":"B","explanation":"Priya notes 'some institutions raised annual interest rates to thirty or even forty percent... led to severe borrower distress and over-indebtedness'.","evidence":"some institutions raised annual interest rates to thirty or even forty percent. Aggressive loan recovery practices led to severe borrower distress and over-indebtedness"},{"id":"l5-q25","questionNumber":25,"prompt":"How did mobile money platforms in Kenya benefit microfinance?","options":["They eliminated the need for loan contracts","They guaranteed government subsidies for every borrower","They lowered transaction costs by enabling SMS loan repayments"],"correctAnswer":"C","explanation":"Daniel explains M-Pesa reduced overheads as 'Borrowers can repay loans via mobile SMS messages'.","evidence":"Borrowers can repay loans via mobile SMS messages, eliminating the need for loan officers to travel long distances"}]},{"groupInstruction":"Complete the summary below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 26–30.","questionType":"sentence_completion","questions":[{"id":"l5-q26","questionNumber":26,"prompt":"Muhammad Yunus founded the Grameen Bank in Bangladesh in the late ____.","correctAnswer":["1970s","nineteen seventies"],"explanation":"Priya states Yunus pioneered it 'in the late 1970s.'","evidence":"pioneered in Bangladesh by Muhammad Yunus in the late 1970s."},{"id":"l5-q27","questionNumber":27,"prompt":"In place of physical assets, group lending relies on social capital and peer ____.","correctAnswer":"monitoring","explanation":"Priya explains: 'peer monitoring replaces legal collateral.'","evidence":"This leverages social capital and community trust; peer monitoring replaces legal collateral."},{"id":"l5-q28","questionNumber":28,"prompt":"Early microcredit loans were typically under ____ US dollars.","correctAnswer":["100","one hundred"],"explanation":"Prof Mansoor notes: 'early Grameen loans were typically under one hundred US dollars'.","evidence":"early Grameen loans were typically under one hundred US dollars, aimed at working capital"},{"id":"l5-q29","questionNumber":29,"prompt":"Modern loans are frequently used to purchase equipment such as solar irrigation ____.","correctAnswer":"pumps","explanation":"Prof Mansoor mentions funds 'for solar irrigation pumps.'","evidence":"often seek five hundred to one thousand dollars for solar irrigation pumps."},{"id":"l5-q30","questionNumber":30,"prompt":"The students will present their research at the tutorial symposium on ____.","correctAnswer":"Monday","explanation":"Priya says: 'ready for the tutorial symposium on Monday!'","evidence":"We have that comparative table ready for the tutorial symposium on Monday!"}]}]},{"sectionNumber":4,"title":"Academic Lecture on Avian Migration Dynamics & Satellite Telemetry","contextDescription":"Dr. Claire Beaumont giving a biology lecture on migratory bird flight navigation and satellite tracking technology.","audioScript":[{"speaker":"Dr Beaumont","text":"Good morning, students. Today we investigate one of the most astonishing biomechanical feats in the animal kingdom: the global migration of avian species. For thousands of years, the seasonal disappearance of birds was steeped in folklore; in ancient Greece, Aristotle famously theorized that swallows spent the winter hibernating in the muddy beds of lakes. Today, miniature satellite telemetry and quantum biophysics have unraveled the extraordinary reality of avian navigation."},{"speaker":"Dr Beaumont","text":"Consider the bar-tailed godwit (Limosa lapponica). Every autumn, this shorebird undertakes an uninterrupted flight from breeding grounds in Alaska across the open Pacific Ocean to wintering estuaries in New Zealand. Over eleven consecutive days and nights, the godwit flaps its wings without pausing to feed, drink, or rest, covering over eleven thousand kilometers. To survive this ordeal, birds undergo profound physiological remodeling before departure: they consume vast quantities of marine mollusks to double their body weight in fat, while internally shrinking their digestive organs by twenty-five percent to minimize aerodynamic drag and save energy."},{"speaker":"Dr Beaumont","text":"How do migratory birds navigate across featureless oceanic expanses without visual landmarks? Avian navigation is a multi-layered sensory hierarchy. By day, birds calculate heading vectors using a sun compass, compensating for solar movement across the sky via their circadian biological clock. By night, nocturnal migrants navigate using star patterns centered on celestial north. Crucially, birds possess a geomagnetic compass governed by quantum mechanics. Specialized blue-light photoreceptor proteins in their eyes, known as cryptochromes, generate entangled radical pairs of electrons when struck by light. These quantum states are exquisitely sensitive to the inclination angle of the Earth's magnetic field, effectively allowing birds to 'see' magnetic field lines superimposed onto their visual field."},{"speaker":"Dr Beaumont","text":"Tracking these epic migrations was historically limited to metal leg ringing, where less than one percent of banded birds were ever recovered. Over the past decade, however, the ICARUS initiative—International Cooperation for Animal Research Using Space—has transformed migration ecology. Engineers designed ultra-miniaturized transmitters weighing less than five grams, powered by solar micro-panels. These solar tags transmit high-frequency GPS fixes to antennas mounted on the International Space Station, mapping migratory routes in real time with three-meter accuracy."},{"speaker":"Dr Beaumont","text":"Tragically, satellite data reveals that migratory flyways are experiencing severe anthropogenic disruption. Artificial light pollution from coastal megacities disorients nocturnal migrants, causing millions to collide fatally with reflective skyscraper windows. Furthermore, coastal mudflats along the East Asian-Australasian Flyway—vital refueling staging posts where birds replenish fat stores—have been reclaimed for industrial development. Preserving these long-distance travelers requires multinational treaty frameworks that protect interconnected network corridors across sovereign borders."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l5-q31","questionNumber":31,"prompt":"The bar-tailed godwit migrates non-stop from breeding grounds in ____ to New Zealand.","correctAnswer":"Alaska","explanation":"Dr Beaumont mentions flight from 'breeding grounds in Alaska across the open Pacific Ocean'.","evidence":"flight from breeding grounds in Alaska across the open Pacific Ocean to wintering estuaries in New Zealand."},{"id":"l5-q32","questionNumber":32,"prompt":"The godwit's non-stop journey takes eleven days and covers over ____ kilometers.","correctAnswer":["11,000","11000","eleven thousand"],"explanation":"Dr Beaumont states: 'covering over eleven thousand kilometers.'","evidence":"Over eleven consecutive days and nights, the godwit flaps its wings... covering over eleven thousand kilometers."},{"id":"l5-q33","questionNumber":33,"prompt":"Prior to departure, godwits shrink their digestive organs by ____ percent.","correctAnswer":["25","twenty-five"],"explanation":"Dr Beaumont notes: 'shrinking their digestive organs by twenty-five percent'.","evidence":"internally shrinking their digestive organs by twenty-five percent to minimize aerodynamic drag"},{"id":"l5-q34","questionNumber":34,"prompt":"Daytime navigation uses a sun compass compensated by the bird's ____ clock.","correctAnswer":"circadian","explanation":"Dr Beaumont explains: 'compensating for solar movement across the sky via their circadian biological clock.'","evidence":"compensating for solar movement across the sky via their circadian biological clock."},{"id":"l5-q35","questionNumber":35,"prompt":"Proteins in bird eyes responsible for detecting magnetic fields are called ____.","correctAnswer":"cryptochromes","explanation":"Dr Beaumont names: 'Specialized blue-light photoreceptor proteins in their eyes, known as cryptochromes'.","evidence":"photoreceptor proteins in their eyes, known as cryptochromes, generate entangled radical pairs"},{"id":"l5-q36","questionNumber":36,"prompt":"Traditional metal leg ringing had a recovery rate of less than ____ percent.","correctAnswer":["1","one"],"explanation":"Dr Beaumont highlights: 'where less than one percent of banded birds were ever recovered.'","evidence":"where less than one percent of banded birds were ever recovered."},{"id":"l5-q37","questionNumber":37,"prompt":"Modern ICARUS satellite tracking transmitters weigh under ____ grams.","correctAnswer":["5","five"],"explanation":"Dr Beaumont notes transmitters 'weighing less than five grams'.","evidence":"designed ultra-miniaturized transmitters weighing less than five grams, powered by solar micro-panels."},{"id":"l5-q38","questionNumber":38,"prompt":"GPS data from ICARUS tags is relayed to antennas on the International ____.","correctAnswer":"Space Station","explanation":"Dr Beaumont states: 'antennas mounted on the International Space Station'.","evidence":"transmit high-frequency GPS fixes to antennas mounted on the International Space Station"},{"id":"l5-q39","questionNumber":39,"prompt":"Artificial ____ pollution from cities disorients nocturnal migrating birds.","correctAnswer":"light","explanation":"Dr Beaumont explains: 'Artificial light pollution from coastal megacities disorients nocturnal migrants'.","evidence":"Artificial light pollution from coastal megacities disorients nocturnal migrants, causing millions to collide fatally"},{"id":"l5-q40","questionNumber":40,"prompt":"Vital refueling staging posts are located in coastal ____ along flyways.","correctAnswer":"mudflats","explanation":"Dr Beaumont refers to 'coastal mudflats along the East Asian-Australasian Flyway'.","evidence":"coastal mudflats along the East Asian-Australasian Flyway—vital refueling staging posts where birds replenish fat stores"}]}]}]`),ye={id:x,title:_,difficulty:k,timeLimitMinutes:q,sections:A},N="list-test-06",B="Listening Practice Test 6",T="easy",C=40,S=JSON.parse(`[{"sectionNumber":1,"title":"Community Tool Library Registration","contextDescription":"Vikram Mehta (Indian English speaker) enquiring with Receptionist Clare (British RP speaker) about joining the local tool lending cooperative.","audioScript":[{"speaker":"Clare (British)","text":"Good morning! Highfield Community Tool Library. How may I help you today?"},{"speaker":"Vikram (Indian English)","text":"Hello Clare! My name is Vikram Mehta. I recently purchased a fixer-upper house in Highfield, and I heard your cooperative lends domestic renovation and gardening tools to local residents."},{"speaker":"Clare (British)","text":"Yes, absolutely! We operate just like a book library, but with over six hundred tools in our inventory. To sign you up, I just need to record a few basic details."},{"speaker":"Vikram (Indian English)","text":"Wonderful. My full name is Vikram Mehta. That's M-E-H-T-A."},{"speaker":"Clare (British)","text":"Thank you, Vikram. And what is your current residential address?"},{"speaker":"Vikram (Indian English)","text":"It's forty-two Orchard Lane, right here in Highfield, postcode H-F-four, seven-P-R."},{"speaker":"Clare (British)","text":"Got it. And a contact mobile number?"},{"speaker":"Vikram (Indian English)","text":"Yes, it is zero seven seven zero zero, nine zero zero eight one four."},{"speaker":"Clare (British)","text":"Splendid. Now regarding membership tiers, our Standard Membership costs thirty-five pounds per year, which entitles you to borrow up to five hand tools simultaneously. If you plan to borrow heavy power machinery, such as rotary tillers or concrete mixers, you will need our Premium tier, which is fifty-five pounds annually."},{"speaker":"Vikram (Indian English)","text":"The Standard tier for thirty-five pounds will be ideal for now. What is the standard loan period for borrowed items?"},{"speaker":"Clare (British)","text":"Most standard items can be kept for up to seven days. However, high-demand items, like cordless drill kits and pressure washers, have a maximum borrowing limit of three days so that other members can access them."},{"speaker":"Vikram (Indian English)","text":"That makes total sense. Do you require any safety deposit?"},{"speaker":"Clare (British)","text":"We do not charge deposits for standard tools, but we do require all new members to show two forms of identification: one photo ID like your passport or driving license, plus a recent utility bill dated within the last three months to verify your address."},{"speaker":"Vikram (Indian English)","text":"I have my driving license and water bill ready in my car. What are your opening hours on weekends?"},{"speaker":"Clare (British)","text":"On Saturdays we are open from nine in the morning until five in the afternoon. On Sundays we open slightly later, from ten in the morning until two in the afternoon."},{"speaker":"Vikram (Indian English)","text":"And where should I return tools when the depot is closed?"},{"speaker":"Clare (British)","text":"Hand tools can be returned via our secure drop box located beside the side gate, but any motorized equipment must be returned in person during staff hours."},{"speaker":"Vikram (Indian English)","text":"Understood. Thank you very much, Clare. I will step outside to grab my documents!"}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l6-q1","questionNumber":1,"type":"sentence_completion","topic":"community","estimatedBand":5.5,"prompt":"Applicant's surname: ____","correctAnswer":"Mehta","explanation":"Vikram spells his surname: M-E-H-T-A.","evidence":"My full name is Vikram Mehta. That's M-E-H-T-A."},{"id":"l6-q2","questionNumber":2,"type":"sentence_completion","topic":"community","estimatedBand":5.5,"prompt":"Address: 42 Orchard Lane, Postcode: ____","correctAnswer":["HF4 7PR","HF47PR"],"explanation":"Vikram gives postcode: H-F-four, seven-P-R.","evidence":"postcode H-F-four, seven-P-R."},{"id":"l6-q3","questionNumber":3,"type":"sentence_completion","topic":"community","estimatedBand":5.5,"prompt":"Contact mobile number: 07700 ____","correctAnswer":"900814","explanation":"Vikram states: zero seven seven zero zero, nine zero zero eight one four.","evidence":"zero seven seven zero zero, nine zero zero eight one four."},{"id":"l6-q4","questionNumber":4,"type":"sentence_completion","topic":"finance","estimatedBand":6,"prompt":"Annual cost of Standard Membership: £____","correctAnswer":["35","thirty-five"],"explanation":"Clare confirms Standard tier is thirty-five pounds.","evidence":"Standard Membership costs thirty-five pounds per year"},{"id":"l6-q5","questionNumber":5,"type":"sentence_completion","topic":"community","estimatedBand":6,"prompt":"Maximum number of hand tools borrowed at one time: ____","correctAnswer":"five","explanation":"Clare explains: 'borrow up to five hand tools simultaneously.'","evidence":"borrow up to five hand tools simultaneously."},{"id":"l6-q6","questionNumber":6,"type":"sentence_completion","topic":"community","estimatedBand":6,"prompt":"Borrowing limit for high-demand items (e.g. pressure washers): ____ days.","correctAnswer":["3","three"],"explanation":"Clare states high-demand items have a limit of three days.","evidence":"maximum borrowing limit of three days so that other members can access them."},{"id":"l6-q7","questionNumber":7,"type":"sentence_completion","topic":"community","estimatedBand":6.5,"prompt":"Required identification: photo ID and a recent ____ bill.","correctAnswer":"utility","explanation":"Clare specifies: 'plus a recent utility bill dated within the last three months'.","evidence":"plus a recent utility bill dated within the last three months to verify your address."},{"id":"l6-q8","questionNumber":8,"type":"sentence_completion","topic":"community","estimatedBand":6,"prompt":"Sunday closing time: ____ PM.","correctAnswer":["2","two","2:00"],"explanation":"Clare states Sunday hours: ten in the morning until two in the afternoon.","evidence":"On Sundays we open slightly later, from ten in the morning until two in the afternoon."},{"id":"l6-q9","questionNumber":9,"type":"sentence_completion","topic":"community","estimatedBand":6.5,"prompt":"After-hours returns for hand tools: use the ____ box near the side gate.","correctAnswer":"drop","explanation":"Clare states hand tools can be returned via our secure drop box.","evidence":"returned via our secure drop box located beside the side gate"},{"id":"l6-q10","questionNumber":10,"type":"sentence_completion","topic":"community","estimatedBand":6.5,"prompt":"Motorized equipment must be returned to ____ during opening hours.","correctAnswer":"staff","explanation":"Clare notes motorized equipment must be returned in person during staff hours.","evidence":"returned in person during staff hours."}]}]},{"sectionNumber":2,"title":"Guided Tour of Port Philip Wildlife Sanctuary","contextDescription":"Ranger Chloe (Australian English speaker) giving an introductory orientation talk to a group of visitors at the Port Philip Wildlife Sanctuary.","audioScript":[{"speaker":"Ranger Chloe (Australian)","text":"G'day everyone, and welcome to Port Philip Wildlife Sanctuary! My name is Chloe, and I am the head conservation ranger here. Before we head out along the boardwalks into the coastal wetlands, I want to give you a quick briefing on our sanctuary's history, current conservation programs, and safety guidelines."},{"speaker":"Ranger Chloe (Australian)","text":"Port Philip Sanctuary was established in 1984 on an old industrial salt pan. Through three decades of tidal rehabilitation, we have successfully restored ninety hectares of native mangrove forest and saltmarsh. This habitat now serves as an essential feeding ground for over one hundred and twenty species of migratory shorebirds, many flying all the way from Siberia and Alaska along the East Asian-Australasian Flyway."},{"speaker":"Ranger Chloe (Australian)","text":"Our flagship success story is the southern brown bandicoot. In 2012, feral foxes had brought this small marsupial to the brink of localized extinction. Thanks to our predator-proof electric perimeter fence and rigorous feral animal trapping, our founder colony of twenty bandicoots has expanded to an estimated four hundred and fifty individuals today."},{"speaker":"Ranger Chloe (Australian)","text":"Now, let me orient you to our sanctuary map. Right now, we are gathered at the Visitor Welcome Pavilion at the southern entrance. Directly ahead of you to the north, you will see the Central Wetland Lagoon. If you follow the main timber boardwalk heading northwest, you will arrive at the Pelican Viewing Hide at location A. It is best to visit the hide at two PM during the daily pelican feeding talk."},{"speaker":"Ranger Chloe (Australian)","text":"If you instead turn northeast from the Welcome Pavilion, location B on your map marks our Native Wildlife Rehabilitation Clinic. You can look through the observation windows to watch our veterinary nurses treating injured flying foxes and echidnas."},{"speaker":"Ranger Chloe (Australian)","text":"Continuing past the clinic along the outer eastern fence line brings you to location C, the Nocturnal Marsupial Enclosure. This enclosure is specially inverted with red ambient lighting, allowing visitors to view sugar gliders and potoroos active during daylight hours."},{"speaker":"Ranger Chloe (Australian)","text":"Finally, at the far northern tip of the lagoon, marked as location D, is our Bush Tucker Botanical Garden. Here, our indigenous rangers lead daily thirty-minute edible plant workshops at eleven in the morning and three in the afternoon."},{"speaker":"Ranger Chloe (Australian)","text":"Just two final rules before you head out: please stay strictly on the raised timber boardwalks to avoid trampling ground-nesting dotterel eggs, and remember that no external food is permitted beyond the picnic lawns. Have a wonderful day exploring!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l6-q11","questionNumber":11,"type":"multiple_choice_single","topic":"conservation","estimatedBand":6,"prompt":"The Port Philip Wildlife Sanctuary was originally built on","options":["a commercial salt pan.","an abandoned coal mine.","a municipal rubbish dump."],"correctAnswer":"A","explanation":"Ranger Chloe explains the sanctuary was established in 1984 on an old industrial salt pan.","evidence":"Port Philip Sanctuary was established in 1984 on an old industrial salt pan."},{"id":"l6-q12","questionNumber":12,"type":"multiple_choice_single","topic":"wildlife","estimatedBand":6.5,"prompt":"Many migratory birds that visit the wetlands fly from as far away as","options":["southern Africa and Madagascar.","Siberia and Alaska.","Scandinavia and Iceland."],"correctAnswer":"B","explanation":"Ranger Chloe mentions birds 'flying all the way from Siberia and Alaska'.","evidence":"migratory shorebirds, many flying all the way from Siberia and Alaska along the East Asian-Australasian Flyway."},{"id":"l6-q13","questionNumber":13,"type":"multiple_choice_single","topic":"ecology","estimatedBand":6.5,"prompt":"The primary threat to the southern brown bandicoot prior to 2012 was","options":["brushfire damage.","parasitic disease.","introduced feral foxes."],"correctAnswer":"C","explanation":"Ranger Chloe states feral foxes had brought the marsupial to the brink of extinction.","evidence":"In 2012, feral foxes had brought this small marsupial to the brink of localized extinction."},{"id":"l6-q14","questionNumber":14,"type":"multiple_choice_single","topic":"conservation","estimatedBand":6,"prompt":"The current population of bandicoots in the sanctuary is approximately","options":["450.","20.","120."],"correctAnswer":"A","explanation":"Chloe states the colony has expanded to an estimated four hundred and fifty individuals.","evidence":"founder colony of twenty bandicoots has expanded to an estimated four hundred and fifty individuals today."},{"id":"l6-q15","questionNumber":15,"type":"multiple_choice_single","topic":"visitor guidelines","estimatedBand":6,"prompt":"Visitors must remain on boardwalks to avoid damaging","options":["delicate mangrove root systems.","ground-nesting bird eggs.","underground electrical cables."],"correctAnswer":"B","explanation":"Chloe says: 'stay strictly on the raised timber boardwalks to avoid trampling ground-nesting dotterel eggs'.","evidence":"stay strictly on the raised timber boardwalks to avoid trampling ground-nesting dotterel eggs"},{"id":"l6-q16","questionNumber":16,"type":"multiple_choice_single","topic":"visitor guidelines","estimatedBand":5.5,"prompt":"External food is only permitted in the","options":["welcome pavilion cafe.","pelican hide.","picnic lawns."],"correctAnswer":"C","explanation":"Chloe says 'no external food is permitted beyond the picnic lawns.'","evidence":"no external food is permitted beyond the picnic lawns."}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l6-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Pelican Viewing Hide: Location ____","correctAnswer":"A","explanation":"Ranger Chloe describes following the main boardwalk northwest to arrive at the Pelican Viewing Hide at location A.","evidence":"timber boardwalk heading northwest, you will arrive at the Pelican Viewing Hide at location A."},{"id":"l6-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Native Wildlife Rehabilitation Clinic: Location ____","correctAnswer":"B","explanation":"Chloe states: 'turn northeast from the Welcome Pavilion, location B on your map marks our Native Wildlife Rehabilitation Clinic.'","evidence":"turn northeast from the Welcome Pavilion, location B on your map marks our Native Wildlife Rehabilitation Clinic."},{"id":"l6-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":7,"prompt":"Nocturnal Marsupial Enclosure: Location ____","correctAnswer":"C","explanation":"Chloe states: 'Continuing past the clinic along the outer eastern fence line brings you to location C, the Nocturnal Marsupial Enclosure.'","evidence":"Continuing past the clinic along the outer eastern fence line brings you to location C, the Nocturnal Marsupial Enclosure."},{"id":"l6-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Bush Tucker Botanical Garden: Location ____","correctAnswer":"D","explanation":"Chloe states: 'Finally, at the far northern tip of the lagoon, marked as location D, is our Bush Tucker Botanical Garden.'","evidence":"far northern tip of the lagoon, marked as location D, is our Bush Tucker Botanical Garden."}]}]},{"sectionNumber":3,"title":"Undergraduate Seminar on Vertical Farming Feasibility","contextDescription":"Professor Davis (British English), Elena (North American English), and Arjun (Indian English) discussing their environmental engineering research presentation on commercial vertical farming.","audioScript":[{"speaker":"Professor Davis (British)","text":"Good morning Elena, Arjun. I have reviewed your draft slides comparing vertical indoor farming with conventional open-field agriculture. Overall, your agronomic data is robust, but I want to ensure your economic and energy analysis is equally critical."},{"speaker":"Elena (North American)","text":"Thanks, Professor Davis. In our initial slides, we highlight the tremendous resource efficiency. For example, closed-loop aeroponic systems use up to ninety-five percent less water than traditional flood irrigation, because excess nutrient mist is condensed and recycled indefinitely."},{"speaker":"Arjun (Indian English)","text":"Yes, and because growing conditions inside a sealed vertical warehouse are completely isolated from external weather, crops are immune to catastrophic droughts or unseasonal hailstorms. Furthermore, indoor farming eliminates the need for chemical insecticides and synthetic herbicides entirely."},{"speaker":"Professor Davis (British)","text":"Those environmental points are well documented. But what about the capital expenditure and power consumption? That is where several high-profile vertical farming startups have gone bankrupt in recent years."},{"speaker":"Elena (North American)","text":"Right. We found that artificial LED grow lighting and industrial HVAC climate control account for nearly fifty-five percent of ongoing operational costs. Unless a facility is directly powered by dedicated onsite solar or geothermal energy, the carbon footprint of grid electricity can actually exceed that of long-haul refrigerated trucking."},{"speaker":"Arjun (Indian English)","text":"Exactly. That is why our case study concludes that vertical farming is currently only commercially viable for high-value perishable crops like microgreens, baby spinach, culinary herbs, and strawberries. Staple calorie crops like wheat, rice, and potatoes require far too much light energy per calorie to be financially viable."},{"speaker":"Professor Davis (British)","text":"Excellent insight. Now, how are you dividing the presentation roles for Tuesday?"},{"speaker":"Elena (North American)","text":"I will deliver the introduction and explain the biological systems: aeroponics versus nutrient film technique hydroponics."},{"speaker":"Arjun (Indian English)","text":"And I will present the financial model, comparing commercial warehouse rental costs in downtown Tokyo and Singapore with rural logistics hubs."},{"speaker":"Professor Davis (British)","text":"Very well. Make sure you leave at least ten minutes at the end for questions from your classmates."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l6-q21","questionNumber":21,"type":"multiple_choice_single","topic":"agriculture","estimatedBand":7,"prompt":"Closed-loop aeroponics uses ninety-five percent less water because","options":["nutrient mist is captured, condensed, and reused.","plants absorb moisture directly from rainfall.","plants are genetically engineered to require zero water."],"correctAnswer":"A","explanation":"Elena states excess nutrient mist is condensed and recycled indefinitely.","evidence":"aeroponic systems use up to ninety-five percent less water than traditional flood irrigation, because excess nutrient mist is condensed and recycled indefinitely."},{"id":"l6-q22","questionNumber":22,"type":"multiple_choice_single","topic":"agriculture","estimatedBand":6.5,"prompt":"One major ecological benefit mentioned by Arjun is that indoor farming","options":["enriches surrounding soil with worms.","requires no chemical insecticides or herbicides.","creates habitats for wild birds."],"correctAnswer":"B","explanation":"Arjun notes indoor farming eliminates the need for chemical insecticides and synthetic herbicides entirely.","evidence":"indoor farming eliminates the need for chemical insecticides and synthetic herbicides entirely."},{"id":"l6-q23","questionNumber":23,"type":"multiple_choice_single","topic":"energy","estimatedBand":7.5,"prompt":"What percentage of ongoing operational costs is typically consumed by lighting and HVAC?","options":["Approximately 30%.","Over 80%.","Nearly 55%."],"correctAnswer":"C","explanation":"Elena states artificial LED grow lighting and HVAC account for nearly fifty-five percent of operational costs.","evidence":"artificial LED grow lighting and industrial HVAC climate control account for nearly fifty-five percent of ongoing operational costs."},{"id":"l6-q24","questionNumber":24,"type":"multiple_choice_single","topic":"economics","estimatedBand":7,"prompt":"Vertical farming can produce a higher carbon footprint than traditional farming if it","options":["relies on standard electrical grid power.","uses heavy diesel tractors.","exports products by air freight."],"correctAnswer":"A","explanation":"Elena explains that unless powered by onsite renewables, grid electricity footprint can exceed refrigerated trucking.","evidence":"Unless a facility is directly powered by dedicated onsite solar or geothermal energy, the carbon footprint of grid electricity can actually exceed that of long-haul refrigerated trucking."},{"id":"l6-q25","questionNumber":25,"type":"multiple_choice_single","topic":"agronomy","estimatedBand":7,"prompt":"Why are staple crops like wheat and potatoes unsuitable for vertical farming?","options":["They cannot grow without natural soil bacteria.","They require too much electrical lighting energy per calorie.","They attract too many rodent pests into warehouses."],"correctAnswer":"B","explanation":"Arjun explains staple calorie crops require far too much light energy per calorie to be financially viable.","evidence":"Staple calorie crops like wheat, rice, and potatoes require far too much light energy per calorie to be financially viable."},{"id":"l6-q26","questionNumber":26,"type":"multiple_choice_single","topic":"education","estimatedBand":6.5,"prompt":"How much time should the students reserve for audience questions?","options":["Five minutes.","Fifteen minutes.","At least ten minutes."],"correctAnswer":"C","explanation":"Professor Davis advises: 'leave at least ten minutes at the end for questions from your classmates.'","evidence":"Make sure you leave at least ten minutes at the end for questions from your classmates."}]},{"groupInstruction":"Which student or speaker is responsible for presenting each topic below? Write the correct letter, A, B, or C, in boxes 27–30.\\nA: Elena\\nB: Arjun\\nC: Professor Davis","questionType":"matching","questions":[{"id":"l6-q27","questionNumber":27,"type":"matching","topic":"presentation","estimatedBand":6.5,"prompt":"Delivering the introductory overview and biological growing systems.","correctAnswer":"A","explanation":"Elena states she will deliver the introduction and explain the biological systems.","evidence":"Elena: I will deliver the introduction and explain the biological systems"},{"id":"l6-q28","questionNumber":28,"type":"matching","topic":"presentation","estimatedBand":7,"prompt":"Comparing urban warehouse rental costs in Tokyo and Singapore.","correctAnswer":"B","explanation":"Arjun states he will present warehouse rental costs in Tokyo and Singapore.","evidence":"Arjun: And I will present the financial model, comparing commercial warehouse rental costs in downtown Tokyo and Singapore"},{"id":"l6-q29","questionNumber":29,"type":"matching","topic":"presentation","estimatedBand":6.5,"prompt":"Explaining nutrient film technique hydroponics.","correctAnswer":"A","explanation":"Elena states she will explain aeroponics versus nutrient film technique hydroponics.","evidence":"Elena: aeroponics versus nutrient film technique hydroponics."},{"id":"l6-q30","questionNumber":30,"type":"matching","topic":"presentation","estimatedBand":7,"prompt":"Analyzing logistics hub transport costs.","correctAnswer":"B","explanation":"Arjun states he will compare urban costs with rural logistics hubs.","evidence":"Arjun: with rural logistics hubs."}]}]},{"sectionNumber":4,"title":"Academic Lecture on Soundscape Ecology and Marine Noise Pollution","contextDescription":"Dr. Alistair Finch (British English speaker) delivering a university biology lecture on anthropogenic ocean noise and acoustic masking in marine mammals.","audioScript":[{"speaker":"Dr. Finch (British)","text":"Good afternoon, students. Today we explore soundscape ecology within marine environments. For terrestrial organisms, vision is the dominant perceptual modality. However, because seawater rapidly absorbs and scatters optical wavelengths, light penetrates only into the upper epipelagic zone. In contrast, acoustic pressure waves travel nearly four point five times faster through seawater than through atmospheric air, attenuating remarkably slowly over thousands of kilometers. Consequently, marine organisms have evolved to rely on sound for navigating, foraging, communicating, and evading predators."},{"speaker":"Dr. Finch (British)","text":"Over the past seventy years, however, the acoustic environment of the global ocean has been radically altered by human industrial activity. The most pervasive chronic contributor is commercial container shipping. Low-frequency propeller cavitation—the rapid collapse of microscopic vapor bubbles generated by churning propeller blades—produces a persistent acoustic drone centered between twenty and two hundred Hertz. Because this frequency band overlaps precisely with the vocalizations of baleen whales, shipping noise creates severe acoustic masking, reducing the effective communication range of blue and fin whales by up to ninety percent."},{"speaker":"Dr. Finch (British)","text":"An even more violent, acute threat comes from marine seismic exploration conducted by offshore hydrocarbon corporations. Survey vessels tow arrays of high-pressure seismic airguns that discharge explosive acoustic blasts into the seabed every ten to twelve seconds for months on end. These acoustic impulses exceed two hundred and fifty decibels at the source. Marine biologists have documented that seismic blasts trigger catastrophic acoustic trauma in odontocetes—such as sperm whales and beaked whales—causing internal auditory hemorrhaging and panic-induced rapid ascents that lead to fatal decompression sickness."},{"speaker":"Dr. Finch (British)","text":"Fortunately, innovative engineering solutions exist. Marine architects are developing silent propeller designs with refined hydrofoil curvature and air-injection bubble curtains that dampen propeller cavitation noise by fifteen decibels. Furthermore, several international maritime authorities have instituted seasonal vessel speed reductions in critical migratory corridors. Decreasing ship speed by just ten percent has been shown to reduce vessel acoustic emissions by approximately fifty percent, providing an immediate, low-cost reprieve for vulnerable marine ecosystems."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l6-q31","questionNumber":31,"type":"sentence_completion","topic":"physics","estimatedBand":7,"prompt":"Sound travels approximately ____ times faster in seawater than in air.","correctAnswer":["4.5","four point five"],"explanation":"Dr. Finch states sound travels nearly four point five times faster through seawater.","evidence":"acoustic pressure waves travel nearly four point five times faster through seawater than through atmospheric air"},{"id":"l6-q32","questionNumber":32,"type":"sentence_completion","topic":"marine biology","estimatedBand":6.5,"prompt":"The most persistent source of chronic ocean noise is commercial ____ shipping.","correctAnswer":"container","explanation":"Dr. Finch identifies commercial container shipping as the most pervasive contributor.","evidence":"The most pervasive chronic contributor is commercial container shipping."},{"id":"l6-q33","questionNumber":33,"type":"sentence_completion","topic":"engineering","estimatedBand":7.5,"prompt":"Propeller noise is primarily generated by a process called ____ cavitation.","correctAnswer":"propeller","explanation":"Dr. Finch refers to low-frequency propeller cavitation.","evidence":"Low-frequency propeller cavitation—the rapid collapse of microscopic vapor bubbles"},{"id":"l6-q34","questionNumber":34,"type":"sentence_completion","topic":"physics","estimatedBand":7,"prompt":"Propeller noise frequencies center between 20 and ____ Hertz.","correctAnswer":["200","two hundred"],"explanation":"Dr. Finch states the drone is centered between twenty and two hundred Hertz.","evidence":"persistent acoustic drone centered between twenty and two hundred Hertz."},{"id":"l6-q35","questionNumber":35,"type":"sentence_completion","topic":"marine biology","estimatedBand":7,"prompt":"Vessel noise causes severe acoustic ____, disrupting whale communication.","correctAnswer":"masking","explanation":"Dr. Finch states shipping noise creates severe acoustic masking.","evidence":"shipping noise creates severe acoustic masking, reducing the effective communication range"},{"id":"l6-q36","questionNumber":36,"type":"sentence_completion","topic":"geology","estimatedBand":7.5,"prompt":"Seismic exploration uses high-pressure airguns fired every 10 to ____ seconds.","correctAnswer":["12","twelve"],"explanation":"Dr. Finch notes airguns discharge blasts every ten to twelve seconds.","evidence":"high-pressure seismic airguns that discharge explosive acoustic blasts into the seabed every ten to twelve seconds"},{"id":"l6-q37","questionNumber":37,"type":"sentence_completion","topic":"physics","estimatedBand":7.5,"prompt":"Seismic airgun sound impulses can exceed ____ decibels at the source.","correctAnswer":["250","two hundred and fifty"],"explanation":"Dr. Finch states impulses exceed two hundred and fifty decibels at the source.","evidence":"These acoustic impulses exceed two hundred and fifty decibels at the source."},{"id":"l6-q38","questionNumber":38,"type":"sentence_completion","topic":"marine biology","estimatedBand":8,"prompt":"Rapid panic ascents in deep-diving whales can trigger fatal decompression ____.","correctAnswer":"sickness","explanation":"Dr. Finch mentions rapid ascents that lead to fatal decompression sickness.","evidence":"rapid ascents that lead to fatal decompression sickness."},{"id":"l6-q39","questionNumber":39,"type":"sentence_completion","topic":"engineering","estimatedBand":7.5,"prompt":"Engineers are dampening cavitation sounds using air-injection ____ curtains.","correctAnswer":"bubble","explanation":"Dr. Finch highlights air-injection bubble curtains.","evidence":"air-injection bubble curtains that dampen propeller cavitation noise by fifteen decibels."},{"id":"l6-q40","questionNumber":40,"type":"sentence_completion","topic":"conservation","estimatedBand":7,"prompt":"A 10 percent reduction in vessel speed cuts acoustic emissions by around ____ percent.","correctAnswer":["50","fifty"],"explanation":"Dr. Finch notes reducing speed by ten percent cuts emissions by approximately fifty percent.","evidence":"Decreasing ship speed by just ten percent has been shown to reduce vessel acoustic emissions by approximately fifty percent"}]}]}]`),fe={id:N,title:B,difficulty:T,timeLimitMinutes:C,sections:S},D="list-test-07",E="Listening Practice Test 7",W="medium",M=40,I=JSON.parse(`[{"sectionNumber":1,"title":"Heritage Railway Weekend Volunteering Enquiry","contextDescription":"Maya Patel (Indian English) speaking with Volunteer Coordinator George (British English) about joining the Severn Valley Steam Railway restoration project.","audioScript":[{"speaker":"George (British)","text":"Good morning! Severn Valley Heritage Railway volunteer office. George speaking."},{"speaker":"Maya (Indian English)","text":"Good morning, George! My name is Maya Patel. I saw your advertisement looking for weekend volunteers to assist with locomotive maintenance and passenger services."},{"speaker":"George (British)","text":"Wonderful, Maya! We are always delighted to welcome new volunteers. Let me capture some preliminary details to register you for our upcoming induction day."},{"speaker":"Maya (Indian English)","text":"Certainly. My first name is Maya, M-A-Y-A, and surname Patel, P-A-T-E-L."},{"speaker":"George (British)","text":"Thank you, Maya. And what is your current address?"},{"speaker":"Maya (Indian English)","text":"I live at seventy-four Victoria Crescent, Bridgnorth, postcode W-V-sixteen, four-B-T."},{"speaker":"George (British)","text":"W-V-sixteen, four-B-T. And an emergency contact telephone number?"},{"speaker":"Maya (Indian English)","text":"Yes, my mobile number is zero seven eight nine zero, six five four three two one."},{"speaker":"George (British)","text":"Excellent. Now, which volunteer role interests you most? We have openings in the station ticket booking office, locomotive engineering workshops, or onboard catering."},{"speaker":"Maya (Indian English)","text":"I have an undergraduate background in mechanical engineering, so I would love to work in the locomotive engineering workshops."},{"speaker":"George (British)","text":"Brilliant! We definitely need help restoring our 1934 LMS Stanier engine. Because the workshops involve active industrial machinery, you will need personal protective equipment. We supply high-visibility vests and safety goggles, but volunteers must provide their own steel-capped safety boots."},{"speaker":"Maya (Indian English)","text":"I already own safety boots from university workshops. What day is the mandatory safety induction held?"},{"speaker":"George (British)","text":"Our next comprehensive safety induction takes place on Saturday, October the twelfth. It starts at nine thirty in the morning and finishes at one in the afternoon."},{"speaker":"Maya (Indian English)","text":"October the twelfth. And where is the induction held?"},{"speaker":"George (British)","text":"In the Carriage Works Training Room, adjacent to Platform Three. If you arrive by car, you can park in the East Yard gravel car park. We will give you a temporary parking permit so you do not have to pay."},{"speaker":"Maya (Indian English)","text":"That is so kind. Thank you George, I look forward to Saturday the twelfth!"}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l7-q1","questionNumber":1,"type":"sentence_completion","topic":"volunteering","estimatedBand":5.5,"prompt":"Applicant full name: Maya ____","correctAnswer":"Patel","explanation":"Maya spells her surname: P-A-T-E-L.","evidence":"surname Patel, P-A-T-E-L."},{"id":"l7-q2","questionNumber":2,"type":"sentence_completion","topic":"volunteering","estimatedBand":5.5,"prompt":"Address: 74 Victoria ____, Bridgnorth.","correctAnswer":"Crescent","explanation":"Maya states: seventy-four Victoria Crescent.","evidence":"seventy-four Victoria Crescent, Bridgnorth"},{"id":"l7-q3","questionNumber":3,"type":"sentence_completion","topic":"volunteering","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["WV16 4BT","WV164BT"],"explanation":"Maya gives postcode: W-V-sixteen, four-B-T.","evidence":"postcode W-V-sixteen, four-B-T."},{"id":"l7-q4","questionNumber":4,"type":"sentence_completion","topic":"volunteering","estimatedBand":5.5,"prompt":"Mobile telephone: 07890 ____","correctAnswer":"654321","explanation":"Maya gives number: zero seven eight nine zero, six five four three two one.","evidence":"zero seven eight nine zero, six five four three two one."},{"id":"l7-q5","questionNumber":5,"type":"sentence_completion","topic":"volunteering","estimatedBand":6.5,"prompt":"Desired volunteer section: locomotive ____ workshops.","correctAnswer":"engineering","explanation":"Maya chooses the locomotive engineering workshops.","evidence":"locomotive engineering workshops."},{"id":"l7-q6","questionNumber":6,"type":"sentence_completion","topic":"safety","estimatedBand":6.5,"prompt":"Volunteers must bring their own steel-capped safety ____.","correctAnswer":"boots","explanation":"George states volunteers must provide their own steel-capped safety boots.","evidence":"volunteers must provide their own steel-capped safety boots."},{"id":"l7-q7","questionNumber":7,"type":"sentence_completion","topic":"dates","estimatedBand":6,"prompt":"Induction date: Saturday, October ____","correctAnswer":["12th","12","twelfth"],"explanation":"George states: Saturday, October the twelfth.","evidence":"Saturday, October the twelfth."},{"id":"l7-q8","questionNumber":8,"type":"sentence_completion","topic":"time","estimatedBand":6,"prompt":"Induction starting time: ____ AM.","correctAnswer":["9:30","9.30","nine thirty"],"explanation":"George states it starts at nine thirty in the morning.","evidence":"starts at nine thirty in the morning"},{"id":"l7-q9","questionNumber":9,"type":"sentence_completion","topic":"location","estimatedBand":6.5,"prompt":"Meeting venue: Carriage Works Training Room, next to Platform ____.","correctAnswer":["Three","3"],"explanation":"George specifies: adjacent to Platform Three.","evidence":"Carriage Works Training Room, adjacent to Platform Three."},{"id":"l7-q10","questionNumber":10,"type":"sentence_completion","topic":"parking","estimatedBand":6.5,"prompt":"Free volunteer parking located in the ____ Yard.","correctAnswer":"East","explanation":"George indicates: park in the East Yard gravel car park.","evidence":"park in the East Yard gravel car park."}]}]},{"sectionNumber":2,"title":"Orientation for New Residents at Mountain View Eco-Village","contextDescription":"Dan (Australian English speaker), the residential manager, orienting newly arrived residents to the community facilities and sustainability protocols.","audioScript":[{"speaker":"Dan (Australian)","text":"Welcome to Mountain View Eco-Village, everyone! My name is Dan, and as the village operations coordinator, I am thrilled to welcome our twelve newest household families. Our community was designed from the ground up to achieve net-zero carbon emissions and foster collaborative neighborliness."},{"speaker":"Dan (Australian)","text":"First, let's talk about water management. Every home here is equipped with an independent five-thousand-liter underground rainwater cistern. This water is filtered and pressurized for laundry appliances and toilet flushing. For garden irrigation, please use the greywater tap marked with purple handles on your exterior wall. Never connect garden hoses to the green drinking water taps during the summer months from December to February."},{"speaker":"Dan (Australian)","text":"Regarding household waste, we operate a five-stream recycling hub located behind the Village Hall. Organic food scraps must be placed inside the aerated worm compost bins. Cardboard and paper go in the blue bins, while glass containers go in the yellow bins. Please note that soft plastic wrappers are not processed in municipal bins; you should deposit them in the designated red collection bin inside the pantry room."},{"speaker":"Dan (Australian)","text":"Our community transport system is another major feature. We have six shared electric cars available for all residents to book via our village mobile app. The fast charging bays are located in Car Park North. The rental rate is just four dollars per hour, which includes full insurance and recharge electricity. Private vehicles must be parked in perimeter car parks, as all internal village pathways are strictly pedestrian and bicycle only."},{"speaker":"Dan (Australian)","text":"Finally, our shared communal dinner takes place every Wednesday evening at six thirty in the Community Kitchen. It is a fantastic tradition where different households take turns cooking using vegetables harvested fresh from our communal organic garden. We hope to see you all this Wednesday!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–15.","questionType":"multiple_choice_single","questions":[{"id":"l7-q11","questionNumber":11,"type":"multiple_choice_single","topic":"sustainability","estimatedBand":6,"prompt":"Underground rainwater tanks in each home supply water for","options":["laundry appliances and toilets.","cooking and drinking.","swimming pools and fountains."],"correctAnswer":"A","explanation":"Dan states cistern water is pressurized for laundry appliances and toilet flushing.","evidence":"pressurized for laundry appliances and toilet flushing."},{"id":"l7-q12","questionNumber":12,"type":"multiple_choice_single","topic":"regulations","estimatedBand":6.5,"prompt":"Connecting garden hoses to drinking water taps is prohibited between","options":["March and May.","December and February.","June and August."],"correctAnswer":"B","explanation":"Dan specifies during summer months from December to February.","evidence":"during the summer months from December to February."},{"id":"l7-q13","questionNumber":13,"type":"multiple_choice_single","topic":"waste","estimatedBand":6.5,"prompt":"Where should residents take soft plastic wrappers?","options":["Yellow recycling bins behind the hall.","The blue paper bins.","The red bin inside the pantry room."],"correctAnswer":"C","explanation":"Dan notes soft plastics go in the designated red collection bin inside the pantry room.","evidence":"deposit them in the designated red collection bin inside the pantry room."},{"id":"l7-q14","questionNumber":14,"type":"multiple_choice_single","topic":"transport","estimatedBand":6,"prompt":"The hourly rental rate for shared electric cars is","options":["$4.","$8.","$12."],"correctAnswer":"A","explanation":"Dan states the rental rate is just four dollars per hour.","evidence":"rental rate is just four dollars per hour, which includes full insurance and recharge electricity."},{"id":"l7-q15","questionNumber":15,"type":"multiple_choice_single","topic":"community","estimatedBand":5.5,"prompt":"The weekly communal dinner is held every","options":["Monday evening.","Wednesday evening.","Friday evening."],"correctAnswer":"B","explanation":"Dan says communal dinner takes place every Wednesday evening.","evidence":"communal dinner takes place every Wednesday evening at six thirty"}]},{"groupInstruction":"Complete the sentences below. Write NO MORE THAN TWO WORDS for each answer. Write your answers in boxes 16–20.","questionType":"sentence_completion","questions":[{"id":"l7-q16","questionNumber":16,"type":"sentence_completion","topic":"water","estimatedBand":6.5,"prompt":"Garden irrigation taps on exterior walls feature ____ handles.","correctAnswer":"purple","explanation":"Dan states: 'marked with purple handles on your exterior wall.'","evidence":"marked with purple handles on your exterior wall."},{"id":"l7-q17","questionNumber":17,"type":"sentence_completion","topic":"recycling","estimatedBand":6,"prompt":"Food scraps must be deposited into aerated ____ compost bins.","correctAnswer":"worm","explanation":"Dan mentions aerated worm compost bins.","evidence":"aerated worm compost bins."},{"id":"l7-q18","questionNumber":18,"type":"sentence_completion","topic":"recycling","estimatedBand":6,"prompt":"Glass bottles and containers are sorted into ____ bins.","correctAnswer":"yellow","explanation":"Dan explains glass containers go in the yellow bins.","evidence":"glass containers go in the yellow bins."},{"id":"l7-q19","questionNumber":19,"type":"sentence_completion","topic":"transport","estimatedBand":6.5,"prompt":"Internal eco-village lanes are restricted strictly to pedestrians and ____.","correctAnswer":"bicycle","explanation":"Dan indicates internal pathways are strictly pedestrian and bicycle only.","evidence":"internal village pathways are strictly pedestrian and bicycle only."},{"id":"l7-q20","questionNumber":20,"type":"sentence_completion","topic":"community","estimatedBand":6,"prompt":"Dinner ingredients are gathered fresh from the village ____ garden.","correctAnswer":"organic","explanation":"Dan notes ingredients come from the communal organic garden.","evidence":"harvested fresh from our communal organic garden."}]}]},{"sectionNumber":3,"title":"Research Proposal Review: Microplastics in Freshwater Estuaries","contextDescription":"Academic supervisor Dr. Karen Vance (North American English) reviewing a postgraduate dissertation methodology with students Oliver (British English) and Meera (Indian English).","audioScript":[{"speaker":"Dr. Vance (North American)","text":"Come in, Oliver, Meera. Let's examine your research proposal investigating microplastic pollution across the Mersey Estuary. Your literature review is quite thorough, but I want to scrutinize your sampling methodology and contamination controls."},{"speaker":"Oliver (British)","text":"Thanks, Dr. Vance. We have designed a stratified sampling protocol across five distinct geographic zones: upstream freshwater, industrial shipping docks, urban stormwater discharge points, agricultural runoff zones, and the outer marine estuary mouth."},{"speaker":"Meera (Indian English)","text":"At each sampling station, we plan to collect twenty-liter surface water samples using a custom stainless steel bucket. We will immediately filter the water through three successive stainless steel mesh sieves: five millimeters, one millimeter, and sixty-three micrometers."},{"speaker":"Dr. Vance (North American)","text":"Using stainless steel is crucial to avoid airborne plastic contamination. But what about procedural blanks? If your field researchers wear synthetic fleece jackets, polyester fibers will contaminate your samples and invalidate your data."},{"speaker":"Oliver (British)","text":"Yes, we took that into consideration! All team members in the field will wear one hundred percent cotton laboratory coats and natural nitrile gloves. Furthermore, we will place open control petri dishes containing damp cellulose filter paper beside the sampling apparatus to quantify background atmospheric fallout."},{"speaker":"Dr. Vance (North American)","text":"Excellent. And how will you identify polymer types once the particles are isolated?"},{"speaker":"Meera (Indian English)","text":"We will utilize micro-FTIR spectroscopy—Fourier-transform infrared spectroscopy. That will allow us to accurately distinguish polyethylene and polypropylene fragments from natural organic cellulose or chitin fibers."},{"speaker":"Dr. Vance (North American)","text":"Very good. Now regarding your budget, have you requested the instrument time on the spectroscopy unit?"},{"speaker":"Oliver (British)","text":"We have booked thirty hours of instrument beam time through the department technician, which will cost approximately six hundred pounds from our research grant."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l7-q21","questionNumber":21,"type":"multiple_choice_single","topic":"methodology","estimatedBand":7,"prompt":"The students' research protocol covers how many distinct sampling zones?","options":["Three zones.","Seven zones.","Five zones."],"correctAnswer":"C","explanation":"Oliver states they have designed a protocol across five distinct geographic zones.","evidence":"stratified sampling protocol across five distinct geographic zones"},{"id":"l7-q22","questionNumber":22,"type":"multiple_choice_single","topic":"sampling","estimatedBand":6.5,"prompt":"What volume of surface water will be collected at each station?","options":["20 liters.","5 liters.","10 liters."],"correctAnswer":"A","explanation":"Meera states: 'collect twenty-liter surface water samples'.","evidence":"collect twenty-liter surface water samples using a custom stainless steel bucket."},{"id":"l7-q23","questionNumber":23,"type":"multiple_choice_single","topic":"laboratory","estimatedBand":7,"prompt":"The finest mesh sieve size used in their filtration is","options":["1 millimeter.","63 micrometers.","5 millimeters."],"correctAnswer":"B","explanation":"Meera lists: five millimeters, one millimeter, and sixty-three micrometers.","evidence":"five millimeters, one millimeter, and sixty-three micrometers."},{"id":"l7-q24","questionNumber":24,"type":"multiple_choice_single","topic":"contamination","estimatedBand":7,"prompt":"Field researchers will prevent synthetic fiber contamination by wearing","options":["polyester raincoats.","disposable nylon jumpsuits.","100% cotton lab coats."],"correctAnswer":"C","explanation":"Oliver explains all team members will wear one hundred percent cotton laboratory coats.","evidence":"All team members in the field will wear one hundred percent cotton laboratory coats"},{"id":"l7-q25","questionNumber":25,"type":"multiple_choice_single","topic":"analysis","estimatedBand":7.5,"prompt":"The primary analytical technique used to verify polymer types will be","options":["Fourier-transform infrared spectroscopy.","gas chromatography mass spectrometry.","simple optical stereomicroscopy."],"correctAnswer":"A","explanation":"Meera specifies micro-FTIR spectroscopy—Fourier-transform infrared spectroscopy.","evidence":"We will utilize micro-FTIR spectroscopy—Fourier-transform infrared spectroscopy."},{"id":"l7-q26","questionNumber":26,"type":"multiple_choice_single","topic":"finance","estimatedBand":6.5,"prompt":"How much grant funding is allocated for spectroscopy instrument time?","options":["£300.","£600.","£1,200."],"correctAnswer":"B","explanation":"Oliver states: 'cost approximately six hundred pounds from our research grant.'","evidence":"cost approximately six hundred pounds from our research grant."}]},{"groupInstruction":"Match each task with the person who proposed or took responsibility for it. Write the correct letter, A, B, or C, in boxes 27–30.\\nA: Dr. Karen Vance\\nB: Oliver\\nC: Meera","questionType":"matching","questions":[{"id":"l7-q27","questionNumber":27,"type":"matching","topic":"research","estimatedBand":7,"prompt":"Formulating the five-zone stratified geographic sampling scheme.","correctAnswer":"B","explanation":"Oliver presents the stratified sampling protocol across five zones.","evidence":"Oliver: We have designed a stratified sampling protocol across five distinct geographic zones"},{"id":"l7-q28","questionNumber":28,"type":"matching","topic":"research","estimatedBand":7,"prompt":"Describing the multi-mesh stainless steel sieve filtration procedure.","correctAnswer":"C","explanation":"Meera explains the twenty-liter collection and three successive mesh sieves.","evidence":"Meera: At each sampling station, we plan to collect twenty-liter surface water samples... filter the water through three successive stainless steel mesh sieves"},{"id":"l7-q29","questionNumber":29,"type":"matching","topic":"research","estimatedBand":7.5,"prompt":"Emphasizing the danger of synthetic clothing contaminating samples.","correctAnswer":"A","explanation":"Dr. Vance warns about synthetic fleece jackets and procedural blanks.","evidence":"Dr. Vance: If your field researchers wear synthetic fleece jackets, polyester fibers will contaminate your samples"},{"id":"l7-q30","questionNumber":30,"type":"matching","topic":"research","estimatedBand":7,"prompt":"Booking thirty hours of beam time with the department technician.","correctAnswer":"B","explanation":"Oliver confirms booking thirty hours of instrument beam time.","evidence":"Oliver: We have booked thirty hours of instrument beam time through the department technician"}]}]},{"sectionNumber":4,"title":"University Lecture: The History and Linguistics of Pidgins and Creoles","contextDescription":"Dr. Ronald Campbell (Scottish / Australian English speaker) delivering an academic linguistics lecture on the formation, grammar, and creolization of contact languages.","audioScript":[{"speaker":"Dr. Campbell (Scottish/Australian)","text":"Good afternoon, everyone. In today's sociolinguistics lecture, we examine language contact phenomena, specifically the genesis and structural evolution of pidgins and creoles. When two or more human linguistic communities come into prolonged contact through trade, maritime exploration, or plantation colonization without sharing a common tongue, an urgent communicative imperative arises."},{"speaker":"Dr. Campbell (Scottish/Australian)","text":"Initially, speakers develop a contact language termed a pidgin. Crucially, a pidgin has no native speakers. It is a simplified vehicular tongue featuring an impoverished grammatical system, minimal inflectional morphology, reduced phonemic inventories, and a lexicon drawn predominantly from the dominant social or economic group—termed the lexifier language. For example, maritime pidgins relied heavily on nautical terminology and simple subject-verb-object declarative syntax."},{"speaker":"Dr. Campbell (Scottish/Australian)","text":"However, a radical transformation occurs when children are born into a multilingual community where a pidgin is the primary household language. Children do not merely inherit the fragmented, rudimentary pidgin of their parents. Instead, through innate cognitive language acquisition mechanisms, the first generation of children systematically regularizes grammar, invents complex tense and aspect markers, introduces subordinate clauses, and expands the vocabulary. This process is called creolization. When a pidgin becomes the acquired native mother tongue of a speech community, it becomes a creole."},{"speaker":"Dr. Campbell (Scottish/Australian)","text":"A famous theoretical explanation for this rapid grammatical flowering was proposed in 1981 by linguist Derek Bickerton: the Language Bioprogram Hypothesis. Bickerton argued that children possess biologically pre-wired universal syntactic templates. When exposed to an impoverished linguistic input like a pidgin, children subconsciously draw upon this innate bioprogram to construct a fully formed natural language with complex tense, mood, and voice categories."},{"speaker":"Dr. Campbell (Scottish/Australian)","text":"A prime real-world exemplar is Tok Pisin, spoken in Papua New Guinea. Originating in the nineteenth century as an English-lexified Pacific plantation jargon, Tok Pisin evolved into a vibrant national creole with over four million speakers, possessing its own television broadcasts, parliamentary debates, and translated literature."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l7-q31","questionNumber":31,"type":"sentence_completion","topic":"linguistics","estimatedBand":7,"prompt":"A pidgin language is unique in having no ____ speakers.","correctAnswer":"native","explanation":"Dr. Campbell states: 'Crucially, a pidgin has no native speakers.'","evidence":"Crucially, a pidgin has no native speakers."},{"id":"l7-q32","questionNumber":32,"type":"sentence_completion","topic":"linguistics","estimatedBand":7.5,"prompt":"The dominant language that supplies vocabulary to a pidgin is called the ____ language.","correctAnswer":"lexifier","explanation":"Dr. Campbell identifies the dominant source as the 'lexifier language'.","evidence":"lexicon drawn predominantly from the dominant social or economic group—termed the lexifier language."},{"id":"l7-q33","questionNumber":33,"type":"sentence_completion","topic":"linguistics","estimatedBand":7,"prompt":"Early trade pidgins relied on simple subject-verb-object ____ word order.","correctAnswer":"declarative","explanation":"Dr. Campbell refers to 'simple subject-verb-object declarative syntax.'","evidence":"simple subject-verb-object declarative syntax."},{"id":"l7-q34","questionNumber":34,"type":"sentence_completion","topic":"linguistics","estimatedBand":7.5,"prompt":"When children acquire a pidgin as their first language, the process is termed ____.","correctAnswer":"creolization","explanation":"Dr. Campbell explains: 'This process is called creolization.'","evidence":"This process is called creolization. When a pidgin becomes the acquired native mother tongue"},{"id":"l7-q35","questionNumber":35,"type":"sentence_completion","topic":"linguistics","estimatedBand":7.5,"prompt":"During creolization, children invent complex markers for tense and ____.","correctAnswer":"aspect","explanation":"Dr. Campbell notes children 'invents complex tense and aspect markers'.","evidence":"invents complex tense and aspect markers, introduces subordinate clauses"},{"id":"l7-q36","questionNumber":36,"type":"sentence_completion","topic":"linguistics","estimatedBand":7,"prompt":"Linguist Derek Bickerton proposed his famous hypothesis in the year ____.","correctAnswer":"1981","explanation":"Dr. Campbell cites: 'proposed in 1981 by linguist Derek Bickerton'.","evidence":"proposed in 1981 by linguist Derek Bickerton: the Language Bioprogram Hypothesis."},{"id":"l7-q37","questionNumber":37,"type":"sentence_completion","topic":"linguistics","estimatedBand":8,"prompt":"Bickerton named his theory the Language ____ Hypothesis.","correctAnswer":"Bioprogram","explanation":"Dr. Campbell names it the Language Bioprogram Hypothesis.","evidence":"Derek Bickerton: the Language Bioprogram Hypothesis."},{"id":"l7-q38","questionNumber":38,"type":"sentence_completion","topic":"linguistics","estimatedBand":8,"prompt":"The theory posits that children possess innate biological ____ templates.","correctAnswer":"syntactic","explanation":"Dr. Campbell explains children have 'biologically pre-wired universal syntactic templates.'","evidence":"biologically pre-wired universal syntactic templates."},{"id":"l7-q39","questionNumber":39,"type":"sentence_completion","topic":"geography","estimatedBand":7,"prompt":"Tok Pisin is widely spoken across the nation of Papua ____.","correctAnswer":"New Guinea","explanation":"Dr. Campbell mentions Tok Pisin spoken in Papua New Guinea.","evidence":"Tok Pisin, spoken in Papua New Guinea."},{"id":"l7-q40","questionNumber":40,"type":"sentence_completion","topic":"sociolinguistics","estimatedBand":7,"prompt":"Tok Pisin currently has over ____ million speakers.","correctAnswer":["4","four"],"explanation":"Dr. Campbell notes over four million speakers.","evidence":"over four million speakers, possessing its own television broadcasts"}]}]}]`),we={id:D,title:E,difficulty:W,timeLimitMinutes:M,sections:I},P="list-test-08",R="Listening Practice Test 8",z="hard",L=40,O=JSON.parse(`[{"sectionNumber":1,"title":"Botanical Garden Seed Exchange Society Membership","contextDescription":"Sunita (Indian English speaker) enquiring with Coordinator David (Australian English speaker) about joining the Royal Botanic Gardens Heirloom Seed Conservation Society.","audioScript":[{"speaker":"David (Australian)","text":"Good morning! Royal Botanic Gardens Heirloom Seed Society. David speaking."},{"speaker":"Sunita (Indian English)","text":"Good morning, David! My name is Sunita Rao. I manage an urban organic allotment, and I am very keen to join your rare seed preservation network."},{"speaker":"David (Australian)","text":"Fantastic, Sunita! We always welcome enthusiastic seed savers. Let me record your contact details and membership preferences."},{"speaker":"Sunita (Indian English)","text":"Certainly. My first name is Sunita, S-U-N-I-T-A, and my surname is Rao, R-A-O."},{"speaker":"David (Australian)","text":"Thank you, Sunita. And your postal address?"},{"speaker":"Sunita (Indian English)","text":"It is eighty-six Elmwood Terrace, Melbourne, postcode three zero five two."},{"speaker":"David (Australian)","text":"Three zero five two. And a daytime contact phone number?"},{"speaker":"Sunita (Indian English)","text":"Yes, it is zero four nine one, five seven zero two eight three."},{"speaker":"David (Australian)","text":"Got it. Now regarding our membership categories, our standard Seed Conservator tier is forty-five dollars annually. That entitles you to receive twelve complimentary packets of heritage seeds each spring, plus our quarterly botanical journal."},{"speaker":"Sunita (Indian English)","text":"Forty-five dollars sounds very reasonable. What specialized seed varieties are you focusing on this season?"},{"speaker":"David (Australian)","text":"This spring, our priority focus is on drought-tolerant heirloom legumes and heritage climbing beans, particularly varieties that flourish without artificial irrigation."},{"speaker":"Sunita (Indian English)","text":"That is exactly what I need for my plot. Do members need to return harvested seeds to the seed bank?"},{"speaker":"David (Australian)","text":"Yes, we operate on a cooperative return pledge: each member agrees to harvest, thoroughly dry, and mail back at least two hundred viable seeds from each crop grown, accompanied by a completed harvest observation log."},{"speaker":"Sunita (Indian English)","text":"I can easily do that. Where do your monthly seed cleaning and packaging workshops meet?"},{"speaker":"David (Australian)","text":"In the Herbarium Education Pavilion, located directly opposite the Rose Garden Pavilion. Workshops run on the third Saturday of each month, starting at ten in the morning."},{"speaker":"Sunita (Indian English)","text":"Wonderful! Thank you so much for your help, David."}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l8-q1","questionNumber":1,"type":"sentence_completion","topic":"society","estimatedBand":5.5,"prompt":"Applicant surname: ____","correctAnswer":"Rao","explanation":"Sunita spells her surname: R-A-O.","evidence":"surname is Rao, R-A-O."},{"id":"l8-q2","questionNumber":2,"type":"sentence_completion","topic":"society","estimatedBand":5.5,"prompt":"Address: 86 ____ Terrace, Melbourne.","correctAnswer":"Elmwood","explanation":"Sunita states: eighty-six Elmwood Terrace.","evidence":"eighty-six Elmwood Terrace, Melbourne"},{"id":"l8-q3","questionNumber":3,"type":"sentence_completion","topic":"society","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["3052","three zero five two"],"explanation":"Sunita gives postcode: three zero five two.","evidence":"postcode three zero five two."},{"id":"l8-q4","questionNumber":4,"type":"sentence_completion","topic":"society","estimatedBand":5.5,"prompt":"Contact mobile number: 0491 ____","correctAnswer":"570283","explanation":"Sunita states: zero four nine one, five seven zero two eight three.","evidence":"zero four nine one, five seven zero two eight three."},{"id":"l8-q5","questionNumber":5,"type":"sentence_completion","topic":"finance","estimatedBand":6,"prompt":"Annual subscription cost: $____","correctAnswer":["45","forty-five"],"explanation":"David confirms standard tier is forty-five dollars annually.","evidence":"Seed Conservator tier is forty-five dollars annually."},{"id":"l8-q6","questionNumber":6,"type":"sentence_completion","topic":"gardening","estimatedBand":6,"prompt":"Number of free seed packets sent each spring: ____","correctAnswer":["12","twelve"],"explanation":"David mentions twelve complimentary packets of heritage seeds.","evidence":"twelve complimentary packets of heritage seeds each spring"},{"id":"l8-q7","questionNumber":7,"type":"sentence_completion","topic":"gardening","estimatedBand":6.5,"prompt":"Seasonal crop priority: heirloom ____ and climbing beans.","correctAnswer":"legumes","explanation":"David specifies drought-tolerant heirloom legumes.","evidence":"drought-tolerant heirloom legumes and heritage climbing beans"},{"id":"l8-q8","questionNumber":8,"type":"sentence_completion","topic":"gardening","estimatedBand":6.5,"prompt":"Members pledge to return at least ____ viable seeds per crop.","correctAnswer":["200","two hundred"],"explanation":"David explains the pledge to mail back at least two hundred viable seeds.","evidence":"mail back at least two hundred viable seeds from each crop grown"},{"id":"l8-q9","questionNumber":9,"type":"sentence_completion","topic":"location","estimatedBand":6.5,"prompt":"Workshop venue: ____ Education Pavilion.","correctAnswer":"Herbarium","explanation":"David states: 'In the Herbarium Education Pavilion'.","evidence":"In the Herbarium Education Pavilion, located directly opposite"},{"id":"l8-q10","questionNumber":10,"type":"sentence_completion","topic":"schedule","estimatedBand":6,"prompt":"Workshops take place on the ____ Saturday of every month.","correctAnswer":"third","explanation":"David notes workshops run on the third Saturday of each month.","evidence":"third Saturday of each month, starting at ten in the morning."}]}]},{"sectionNumber":2,"title":"Visitor Tour of the Deep Marine Research Submersible Facility","contextDescription":"Commander Mark Ross (North American English speaker) addressing visiting engineering students at the Deep Ocean Exploration Research Center.","audioScript":[{"speaker":"Commander Ross (North American)","text":"Welcome, cadets and engineers, to the National Deep Ocean Exploration Facility. I am Commander Mark Ross. Today, you are standing inside our assembly hangar where we maintain and test human-occupied submersibles capable of descending into the Mariana Trench—over eleven thousand meters beneath the ocean surface."},{"speaker":"Commander Ross (North American)","text":"At those abyssal depths, water pressure exceeds one thousand atmospheres, or roughly eight tons per square inch. To withstand that crushing force without imploding, our crew spheres are forged not from steel, which becomes brittle under cyclic stress, but from seamless, solid grade-five titanium, precisely six point five inches thick. Inside, the internal pressure remains at a comfortable sea-level one atmosphere."},{"speaker":"Commander Ross (North American)","text":"Now, take a look at the facility layout map displayed on your tablets. We are currently positioned at the Central Entrance Atrium on the ground floor. If you proceed directly through the security turnstiles to location A on the west wing, you will find the Hyperbaric Pressure Testing Chamber. Here, miniature robotic components are pressure-tested up to sixteen thousand pounds per square inch inside a massive water-filled steel chamber."},{"speaker":"Commander Ross (North American)","text":"Moving north past the central corridor, location B marks the Syntactic Foam Milling Shop. Syntactic foam is our primary buoyancy material, consisting of billions of microscopic hollow glass spheres embedded in epoxy resin. It provides immense flotation without compressing at depth."},{"speaker":"Commander Ross (North American)","text":"Across the hallway to the east at location C is the High-Definition Sonar & Navigation Lab. Here, electrical engineers calibrate multi-beam bathymetric mapping sensors and laser optical scanners."},{"speaker":"Commander Ross (North American)","text":"Finally, at the far northern end of the hangar, marked as location D, is our Emergency Life-Support Testing Rig. This facility validates our cryogenic oxygen scrubbers and emergency seventy-two-hour lithium hydroxide carbon dioxide absorption canisters."},{"speaker":"Commander Ross (North American)","text":"Before we begin our walking inspection, please ensure you leave all personal cell phones and metallic items in your storage lockers, as strong electromagnetic fields in the testing bay can disrupt sensitive instrumentation. Let's head out!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l8-q11","questionNumber":11,"type":"multiple_choice_single","topic":"oceanography","estimatedBand":6.5,"prompt":"Submersibles tested at this facility can reach depths of up to","options":["3,000 meters.","7,500 meters.","11,000 meters."],"correctAnswer":"C","explanation":"Commander Ross states submersibles are capable of descending over eleven thousand meters.","evidence":"Mariana Trench—over eleven thousand meters beneath the ocean surface."},{"id":"l8-q12","questionNumber":12,"type":"multiple_choice_single","topic":"materials","estimatedBand":7,"prompt":"Crew spheres are forged from grade-five titanium rather than steel because","options":["steel becomes brittle under repeated cyclic pressure.","titanium is significantly cheaper than carbon steel.","titanium dissolves less quickly in seawater."],"correctAnswer":"A","explanation":"Commander Ross explains steel becomes brittle under cyclic stress.","evidence":"not from steel, which becomes brittle under cyclic stress, but from seamless, solid grade-five titanium"},{"id":"l8-q13","questionNumber":13,"type":"multiple_choice_single","topic":"engineering","estimatedBand":7,"prompt":"The thickness of the solid titanium crew sphere wall is","options":["2.5 inches.","6.5 inches.","4.0 inches."],"correctAnswer":"B","explanation":"Commander Ross notes: 'precisely six point five inches thick.'","evidence":"solid grade-five titanium, precisely six point five inches thick."},{"id":"l8-q14","questionNumber":14,"type":"multiple_choice_single","topic":"physics","estimatedBand":6.5,"prompt":"Syntactic foam provides buoyancy because it contains microscopic","options":["helium gas pockets.","porous volcanic pebbles.","hollow glass spheres."],"correctAnswer":"C","explanation":"Commander Ross states it consists of billions of microscopic hollow glass spheres in epoxy resin.","evidence":"consisting of billions of microscopic hollow glass spheres embedded in epoxy resin."},{"id":"l8-q15","questionNumber":15,"type":"multiple_choice_single","topic":"safety","estimatedBand":7,"prompt":"Emergency life-support canisters are designed to support crew for at least","options":["72 hours.","24 hours.","48 hours."],"correctAnswer":"A","explanation":"Commander Ross highlights emergency seventy-two-hour absorption canisters.","evidence":"emergency seventy-two-hour lithium hydroxide carbon dioxide absorption canisters."},{"id":"l8-q16","questionNumber":16,"type":"multiple_choice_single","topic":"rules","estimatedBand":6,"prompt":"Why must visitors leave mobile phones in lockers?","options":["To prevent commercial photography theft.","To avoid interference with strong electromagnetic testing equipment.","To comply with secret military security clearances."],"correctAnswer":"B","explanation":"Commander Ross warns strong electromagnetic fields in the testing bay can disrupt instruments.","evidence":"strong electromagnetic fields in the testing bay can disrupt sensitive instrumentation."}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l8-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Hyperbaric Pressure Testing Chamber: Location ____","correctAnswer":"A","explanation":"Commander Ross indicates location A on the west wing as the Hyperbaric Pressure Testing Chamber.","evidence":"location A on the west wing, you will find the Hyperbaric Pressure Testing Chamber."},{"id":"l8-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Syntactic Foam Milling Shop: Location ____","correctAnswer":"B","explanation":"Commander Ross indicates location B past the central corridor as the Syntactic Foam Milling Shop.","evidence":"Moving north past the central corridor, location B marks the Syntactic Foam Milling Shop."},{"id":"l8-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":7,"prompt":"High-Definition Sonar & Navigation Lab: Location ____","correctAnswer":"C","explanation":"Commander Ross indicates location C across the hallway to the east.","evidence":"Across the hallway to the east at location C is the High-Definition Sonar & Navigation Lab."},{"id":"l8-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Emergency Life-Support Testing Rig: Location ____","correctAnswer":"D","explanation":"Commander Ross indicates location D at the far northern end of the hangar.","evidence":"at the far northern end of the hangar, marked as location D, is our Emergency Life-Support Testing Rig."}]}]},{"sectionNumber":3,"title":"University Tutorial: Evaluating Carbon Border Adjustment Mechanisms","contextDescription":"Economics Professor Henderson (British English) discussing an international environmental policy essay with students Tariq (Indian English) and Sophie (Australian English).","audioScript":[{"speaker":"Professor Henderson (British)","text":"Good afternoon Sophie, Tariq. Let us dissect your joint presentation on the European Union's Carbon Border Adjustment Mechanism—or CBAM. Your macroeconomic data on steel and cement imports is well synthesized, but I want to ensure you address both sides of the trade debate."},{"speaker":"Sophie (Australian)","text":"Thanks, Professor. The primary justification for CBAM is preventing 'carbon leakage'. Under the EU Emissions Trading System, European heavy industries pay a substantial carbon price per ton of emissions. Without a border carbon tariff, domestic manufacturers would simply relocate heavy manufacturing offshore to countries with lax environmental laws, shifting emissions rather than abating them."},{"speaker":"Tariq (Indian English)","text":"Right, but our presentation also explores the severe ethical and economic criticisms voiced by developing economies in the Global South. Nations like India, South Africa, and Brazil argue that CBAM violates the United Nations principle of Common But Differentiated Responsibilities. Developing countries have historically contributed far less cumulative atmospheric carbon, yet this tariff penalizes their emerging export manufacturing sectors."},{"speaker":"Professor Henderson (British)","text":"That is a pivotal tension. What are the key industrial sectors covered during the initial phase of CBAM?"},{"speaker":"Sophie (Australian)","text":"The regulation targets six carbon-intensive, trade-exposed commodity sectors: iron and steel, aluminum, cement, chemical fertilizers, electricity generation, and hydrogen."},{"speaker":"Tariq (Indian English)","text":"And an interesting administrative detail is that foreign exporters do not pay cash taxes directly at the port. Instead, importers must surrender digital CBAM certificates, which mirror the weekly average auction price of EU carbon allowances under the ETS."},{"speaker":"Professor Henderson (British)","text":"Excellent observation. For next week's policy briefing, how will you divide the remaining drafting tasks?"},{"speaker":"Sophie (Australian)","text":"I will write the economic modeling section simulating the tariff's impact on Australian aluminum exporters."},{"speaker":"Tariq (Indian English)","text":"And I will analyze the World Trade Organization legal challenges and potential retaliation measures from Asian trade blocs."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l8-q21","questionNumber":21,"type":"multiple_choice_single","topic":"economics","estimatedBand":7.5,"prompt":"The primary stated goal of the Carbon Border Adjustment Mechanism is to","options":["raise tax revenue for space exploration.","eliminate all international trade across Europe.","prevent carbon leakage caused by industries relocating abroad."],"correctAnswer":"C","explanation":"Sophie explains the goal is preventing carbon leakage where companies move production to countries with lax laws.","evidence":"The primary justification for CBAM is preventing 'carbon leakage'."},{"id":"l8-q22","questionNumber":22,"type":"multiple_choice_single","topic":"policy","estimatedBand":7.5,"prompt":"Developing countries criticize CBAM because they believe it violates","options":["the principle of Common But Differentiated Responsibilities.","European Union internal bylaws.","maritime copyright conventions."],"correctAnswer":"A","explanation":"Tariq states nations argue CBAM violates the UN principle of Common But Differentiated Responsibilities.","evidence":"argue that CBAM violates the United Nations principle of Common But Differentiated Responsibilities."},{"id":"l8-q23","questionNumber":23,"type":"multiple_choice_single","topic":"policy","estimatedBand":7,"prompt":"How many industrial sectors are included in the initial phase of CBAM?","options":["Four.","Six.","Eight."],"correctAnswer":"B","explanation":"Sophie states the regulation targets six carbon-intensive commodity sectors.","evidence":"The regulation targets six carbon-intensive, trade-exposed commodity sectors"},{"id":"l8-q24","questionNumber":24,"type":"multiple_choice_single","topic":"industry","estimatedBand":7,"prompt":"Which of the following is NOT one of the six sectors covered by CBAM?","options":["Chemical fertilizers.","Cement.","Commercial textile manufacturing."],"correctAnswer":"C","explanation":"Sophie lists iron and steel, aluminum, cement, fertilizers, electricity, and hydrogen—textiles are not included.","evidence":"iron and steel, aluminum, cement, chemical fertilizers, electricity generation, and hydrogen."},{"id":"l8-q25","questionNumber":25,"type":"multiple_choice_single","topic":"finance","estimatedBand":8,"prompt":"Instead of paying cash customs tariffs, importers must purchase and surrender","options":["digital CBAM certificates.","sovereign gold bonds.","carbon offset airline tickets."],"correctAnswer":"A","explanation":"Tariq explains importers surrender digital CBAM certificates.","evidence":"importers must surrender digital CBAM certificates, which mirror the weekly average auction price"},{"id":"l8-q26","questionNumber":26,"type":"multiple_choice_single","topic":"law","estimatedBand":7.5,"prompt":"Which international organization might hear legal challenges against CBAM?","options":["World Health Organization.","World Trade Organization.","International Monetary Fund."],"correctAnswer":"B","explanation":"Tariq mentions analyzing World Trade Organization legal challenges.","evidence":"analyze the World Trade Organization legal challenges and potential retaliation measures"}]},{"groupInstruction":"Which student is responsible for each research area? Write the correct letter, A or B, in boxes 27–30.\\nA: Sophie\\nB: Tariq","questionType":"matching","questions":[{"id":"l8-q27","questionNumber":27,"type":"matching","topic":"assignment","estimatedBand":7,"prompt":"Explaining the concept and industry risks of carbon leakage.","correctAnswer":"A","explanation":"Sophie presents the carbon leakage rationale.","evidence":"Sophie: The primary justification for CBAM is preventing 'carbon leakage'."},{"id":"l8-q28","questionNumber":28,"type":"matching","topic":"assignment","estimatedBand":7,"prompt":"Synthesizing developing nation perspectives from India, South Africa, and Brazil.","correctAnswer":"B","explanation":"Tariq explores criticisms from developing economies in the Global South.","evidence":"Tariq: Nations like India, South Africa, and Brazil argue that CBAM violates"},{"id":"l8-q29","questionNumber":29,"type":"matching","topic":"assignment","estimatedBand":7.5,"prompt":"Modeling the tariff effects on Australian aluminum exporters.","correctAnswer":"A","explanation":"Sophie confirms she will write the economic modeling section for Australian aluminum.","evidence":"Sophie: I will write the economic modeling section simulating the tariff's impact on Australian aluminum exporters."},{"id":"l8-q30","questionNumber":30,"type":"matching","topic":"assignment","estimatedBand":7.5,"prompt":"Analyzing potential WTO litigation and retaliatory trade policies.","correctAnswer":"B","explanation":"Tariq confirms he will analyze WTO legal challenges.","evidence":"Tariq: And I will analyze the World Trade Organization legal challenges and potential retaliation measures"}]}]},{"sectionNumber":4,"title":"Academic Lecture: Glaciology and Subglacial Lake Vostok Extremophiles","contextDescription":"Dr. Christine Weber (North American English speaker) delivering a university lecture on Antarctic ice-sheet glaciology and subglacial microbial ecosystems.","audioScript":[{"speaker":"Dr. Weber (North American)","text":"Good afternoon, class. Today we explore one of the most extreme environments on our planet: subglacial Lake Vostok in East Antarctica. Situated directly beneath Russia's Vostok Station, this massive freshwater lake lies sealed beneath nearly four kilometers of solid continental ice sheet. Spanning two hundred and fifty kilometers in length and fifty kilometers in width, Lake Vostok has a volume comparable to Lake Ontario, yet it has remained completely isolated from Earth's atmosphere for an estimated fifteen million years."},{"speaker":"Dr. Weber (North American)","text":"You might reasonably ask how liquid water can exist in a location where the mean annual surface air temperature is minus fifty-five degrees Celsius. The answer lies in two thermodynamic mechanisms. First, the colossal weight of the four-kilometer-thick overburden ice creates immense hydrostatic pressure—exceeding three hundred and fifty atmospheres—which lowers the physical freezing point of water to minus two point four degrees Celsius. Second, and more importantly, the base of the ice sheet is warmed by geothermal heat flux radiating upwards from the Earth's continental mantle, steadily melting the basal ice layer."},{"speaker":"Dr. Weber (North American)","text":"In 2012, after decades of meticulous deep ice-core drilling, Russian glaciologists successfully penetrated into the lake using a thermal-drill system. To prevent contaminating this pristine water body with kerosene drilling fluids, researchers maintained a hydraulic pressure deficit, allowing pressurized lake water to surge upward into the borehole and freeze into an ice plug, which was subsequently extracted for analysis."},{"speaker":"Dr. Weber (North American)","text":"Metagenomic sequencing of this accretion ice revealed a startling, thriving microbial community. Because Lake Vostok is completely devoid of sunlight, photosynthesis is impossible. Instead, resident bacteria and archaea are chemolithoautotrophs. They synthesize organic molecules by oxidizing dissolved iron, sulfur, and methane derived from ancient tectonic fault lines in the lake bed. Lake Vostok serves as an invaluable planetary analog for astrobiologists studying Jupiter's moon Europa and Saturn's moon Enceladus, suggesting that life can thrive in dark, ice-covered oceans throughout the solar system."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l8-q31","questionNumber":31,"type":"sentence_completion","topic":"geography","estimatedBand":7,"prompt":"Lake Vostok is located beneath the continental ice sheet in East ____.","correctAnswer":"Antarctica","explanation":"Dr. Weber notes Lake Vostok in East Antarctica.","evidence":"subglacial Lake Vostok in East Antarctica."},{"id":"l8-q32","questionNumber":32,"type":"sentence_completion","topic":"glaciology","estimatedBand":7,"prompt":"The lake lies beneath approximately ____ kilometers of ice.","correctAnswer":["4","four"],"explanation":"Dr. Weber explains the lake lies beneath nearly four kilometers of solid ice.","evidence":"sealed beneath nearly four kilometers of solid continental ice sheet."},{"id":"l8-q33","questionNumber":33,"type":"sentence_completion","topic":"geology","estimatedBand":7.5,"prompt":"Lake Vostok has been sealed off from the atmosphere for an estimated ____ million years.","correctAnswer":["15","fifteen"],"explanation":"Dr. Weber notes isolated for an estimated fifteen million years.","evidence":"isolated from Earth's atmosphere for an estimated fifteen million years."},{"id":"l8-q34","questionNumber":34,"type":"sentence_completion","topic":"physics","estimatedBand":7.5,"prompt":"High hydrostatic pressure lowers the water freezing point to minus ____ degrees Celsius.","correctAnswer":["2.4","two point four"],"explanation":"Dr. Weber states the freezing point is lowered to minus two point four degrees Celsius.","evidence":"lowers the physical freezing point of water to minus two point four degrees Celsius."},{"id":"l8-q35","questionNumber":35,"type":"sentence_completion","topic":"geophysics","estimatedBand":7.5,"prompt":"Basal ice is kept liquid by ____ heat flux rising from the Earth's mantle.","correctAnswer":"geothermal","explanation":"Dr. Weber highlights geothermal heat flux radiating upwards.","evidence":"warmed by geothermal heat flux radiating upwards from the Earth's continental mantle"},{"id":"l8-q36","questionNumber":36,"type":"sentence_completion","topic":"drilling","estimatedBand":7,"prompt":"In the year ____, Russian glaciologists successfully reached the lake surface.","correctAnswer":"2012","explanation":"Dr. Weber states: 'In 2012, after decades of meticulous deep ice-core drilling'.","evidence":"In 2012, after decades of meticulous deep ice-core drilling, Russian glaciologists successfully penetrated"},{"id":"l8-q37","questionNumber":37,"type":"sentence_completion","topic":"engineering","estimatedBand":8,"prompt":"Scientists created an ice ____ in the borehole to prevent chemical fluid contamination.","correctAnswer":"plug","explanation":"Dr. Weber explains water surged up to freeze into an ice plug.","evidence":"freeze into an ice plug, which was subsequently extracted for analysis."},{"id":"l8-q38","questionNumber":38,"type":"sentence_completion","topic":"biology","estimatedBand":8,"prompt":"Organisms in the dark lake produce energy through chemosynthesis as ____.","correctAnswer":"chemolithoautotrophs","explanation":"Dr. Weber identifies them as chemolithoautotrophs.","evidence":"resident bacteria and archaea are chemolithoautotrophs."},{"id":"l8-q39","questionNumber":39,"type":"sentence_completion","topic":"geology","estimatedBand":7.5,"prompt":"Microorganisms oxidize sulfur, iron, and ____ emitted from tectonic fault lines.","correctAnswer":"methane","explanation":"Dr. Weber notes bacteria oxidize dissolved iron, sulfur, and methane.","evidence":"oxidizing dissolved iron, sulfur, and methane derived from ancient tectonic fault lines"},{"id":"l8-q40","questionNumber":40,"type":"sentence_completion","topic":"astronomy","estimatedBand":7.5,"prompt":"Astrobiologists use Vostok as an analog for Jupiter's ice moon ____.","correctAnswer":"Europa","explanation":"Dr. Weber mentions Jupiter's moon Europa and Saturn's moon Enceladus.","evidence":"planetary analog for astrobiologists studying Jupiter's moon Europa and Saturn's moon Enceladus"}]}]}]`),be={id:P,title:R,difficulty:z,timeLimitMinutes:L,sections:O},G="list-test-09",H="Listening Practice Test 9",F="medium",V=40,j=JSON.parse(`[{"sectionNumber":1,"title":"Community Repair Cafe Volunteer Workshop Registration","contextDescription":"Ananya (Indian English speaker) enquiring with Coordinator Arthur (British English speaker) about registering as a volunteer repair technician at the St. Jude Community Repair Cafe.","audioScript":[{"speaker":"Arthur (British)","text":"Good afternoon! St. Jude Community Repair Cafe. Arthur speaking."},{"speaker":"Ananya (Indian English)","text":"Hello Arthur! My name is Ananya Sen. I saw a poster about your monthly repair sessions where neighbors bring in broken household electronics and appliances rather than throwing them into landfills."},{"speaker":"Arthur (British)","text":"Spot on, Ananya! Our motto is 'Fix it, don't ditch it!' We are always on the hunt for volunteer troubleshooters. Let me take down your registration details."},{"speaker":"Ananya (Indian English)","text":"Certainly. My first name is Ananya, spelled A-N-A-N-Y-A, and surname Sen, S-E-N."},{"speaker":"Arthur (British)","text":"Thank you, Ananya. And your home address?"},{"speaker":"Ananya (Indian English)","text":"I reside at twenty-nine Waverley Road, Bristol, postcode B-S-six, six-H-L."},{"speaker":"Arthur (British)","text":"B-S-six, six-H-L. And your preferred contact telephone number?"},{"speaker":"Ananya (Indian English)","text":"It is zero seven seven zero zero, nine zero zero three five nine."},{"speaker":"Arthur (British)","text":"Grand. Now, what repair skill station would you prefer to anchor? We have small electrical appliances, bicycle mechanics, textile sewing, and wooden furniture."},{"speaker":"Ananya (Indian English)","text":"I work professionally as a consumer hardware engineer, so I would feel most useful at the small electrical station—fixing kettles, toasters, lamps, and audio speakers."},{"speaker":"Arthur (British)","text":"Brilliant, we desperately need appliance repairers! For safety reasons, our cafe provides an approved portable appliance tester—a PAT testing multimeter—which every repaired electric item must pass before it leaves the venue."},{"speaker":"Ananya (Indian English)","text":"Of course, electrical safety is paramount. When is the next community session held?"},{"speaker":"Arthur (British)","text":"Our sessions run on the second Saturday of each month. The next one is on Saturday, November the ninth. We start set up at nine in the morning and welcome the public between ten and two."},{"speaker":"Ananya (Indian English)","text":"November the ninth, nine AM. And where is the hall located?"},{"speaker":"Arthur (British)","text":"At St. Jude Parish Hall, right behind the Green Park Primary School. We have bicycle racks and free volunteer parking in the church forecourt."},{"speaker":"Ananya (Indian English)","text":"That is so wonderful. I look forward to November the ninth!"}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l9-q1","questionNumber":1,"type":"sentence_completion","topic":"community","estimatedBand":5.5,"prompt":"Volunteer's surname: ____","correctAnswer":"Sen","explanation":"Ananya spells her surname: S-E-N.","evidence":"surname Sen, S-E-N."},{"id":"l9-q2","questionNumber":2,"type":"sentence_completion","topic":"community","estimatedBand":5.5,"prompt":"Address: 29 ____ Road, Bristol.","correctAnswer":"Waverley","explanation":"Ananya states: twenty-nine Waverley Road.","evidence":"twenty-nine Waverley Road, Bristol"},{"id":"l9-q3","questionNumber":3,"type":"sentence_completion","topic":"community","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["BS6 6HL","BS66HL"],"explanation":"Ananya gives postcode: B-S-six, six-H-L.","evidence":"postcode B-S-six, six-H-L."},{"id":"l9-q4","questionNumber":4,"type":"sentence_completion","topic":"community","estimatedBand":5.5,"prompt":"Contact mobile number: 07700 ____","correctAnswer":"900359","explanation":"Ananya gives: zero seven seven zero zero, nine zero zero three five nine.","evidence":"zero seven seven zero zero, nine zero zero three five nine."},{"id":"l9-q5","questionNumber":5,"type":"sentence_completion","topic":"technology","estimatedBand":6,"prompt":"Preferred station: small ____ appliances.","correctAnswer":"electrical","explanation":"Ananya selects the small electrical station.","evidence":"most useful at the small electrical station"},{"id":"l9-q6","questionNumber":6,"type":"sentence_completion","topic":"safety","estimatedBand":6.5,"prompt":"Repaired items must undergo inspection with a portable appliance ____.","correctAnswer":"tester","explanation":"Arthur mentions an approved portable appliance tester—a PAT testing multimeter.","evidence":"approved portable appliance tester—a PAT testing multimeter"},{"id":"l9-q7","questionNumber":7,"type":"sentence_completion","topic":"schedule","estimatedBand":6,"prompt":"Sessions occur on the ____ Saturday of each month.","correctAnswer":"second","explanation":"Arthur states sessions run on the second Saturday of each month.","evidence":"sessions run on the second Saturday of each month."},{"id":"l9-q8","questionNumber":8,"type":"sentence_completion","topic":"dates","estimatedBand":6,"prompt":"Next event date: Saturday, November ____","correctAnswer":["9th","9","ninth"],"explanation":"Arthur specifies: Saturday, November the ninth.","evidence":"next one is on Saturday, November the ninth."},{"id":"l9-q9","questionNumber":9,"type":"sentence_completion","topic":"time","estimatedBand":5.5,"prompt":"Volunteer setup starts at ____ AM.","correctAnswer":["9","nine","9:00"],"explanation":"Arthur states: We start set up at nine in the morning.","evidence":"We start set up at nine in the morning"},{"id":"l9-q10","questionNumber":10,"type":"sentence_completion","topic":"location","estimatedBand":6,"prompt":"Hall is situated directly behind the Green Park Primary ____.","correctAnswer":"School","explanation":"Arthur notes it is behind the Green Park Primary School.","evidence":"right behind the Green Park Primary School."}]}]},{"sectionNumber":2,"title":"Radio Broadcast: The Great Southern Dark Sky Sanctuary","contextDescription":"Astronomer Liam (Australian English speaker) describing the newly accredited dark sky reserve on a science radio broadcast.","audioScript":[{"speaker":"Liam (Australian)","text":"Good evening, stargazers! I am delighted to report that the Great Southern Outback Reserve in South Australia has officially received Gold Tier Dark Sky Sanctuary accreditation from the International Dark-Sky Association. Covering over five thousand square kilometers of protected wilderness, it now stands as one of the darkest astronomical observation territories on the planet."},{"speaker":"Liam (Australian)","text":"In modern urban centers, excessive artificial light pollution—from roadway floodlights, commercial neon billboards, and residential floodlamps—has bleached the nocturnal sky. Over eighty percent of the global human population now lives under light-polluted skies, unable to glimpse the glowing arc of the Milky Way. Light pollution also catastrophically disrupts wildlife, throwing off navigational cues for nocturnal marsupials and disorienting migratory birds."},{"speaker":"Liam (Australian)","text":"To achieve our sanctuary status, our local rural councils enacted stringent lighting ordinances across all surrounding townships. Public streetlights were replaced with downward-shielded, narrow-spectrum amber LED luminaires that emit zero upward light spill. Furthermore, color temperatures are strictly capped at two thousand two hundred Kelvin, eliminating the high-frequency blue photons that scatter most violently across the atmosphere."},{"speaker":"Liam (Australian)","text":"For visiting astro-tourists, we have constructed four specialized public viewing zones across the reserve. The most popular is Stargazer Plateau at location A, featuring eight concrete telescope mounting piers and 360-degree horizon visibility. To the west at location B is the Astro-Photography Pods, equipped with vibration-isolated timber platforms and external solar battery recharge outlets."},{"speaker":"Liam (Australian)","text":"Location C on the southern ridge marks the Solar Astronomy Observatory, which opens during daylight hours with hydrogen-alpha solar telescopes for viewing sunspots and solar flares. Finally, at location D beside the visitor lodge is our Indigenous Starlore Amphitheatre, where Adnyamathanha cultural guides share ancestral constellations and celestial dreamtime stories around an unlit fire pit."},{"speaker":"Liam (Australian)","text":"When visiting, remember our cardinal rule: only red-filtered flashlights are permitted beyond the car parks to preserve dark adaptation for your night vision. Come experience the cosmos as our ancestors saw it!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l9-q11","questionNumber":11,"type":"multiple_choice_single","topic":"astronomy","estimatedBand":6,"prompt":"The Great Southern Outback Reserve covers an area of over","options":["2,000 square kilometers.","10,000 square kilometers.","5,000 square kilometers."],"correctAnswer":"C","explanation":"Liam states the reserve covers over five thousand square kilometers.","evidence":"Covering over five thousand square kilometers of protected wilderness"},{"id":"l9-q12","questionNumber":12,"type":"multiple_choice_single","topic":"environment","estimatedBand":6.5,"prompt":"What proportion of the global population lives under light-polluted night skies?","options":["Over 80%.","More than 50%.","Nearly 95%."],"correctAnswer":"A","explanation":"Liam explains over eighty percent of the global population lives under light-polluted skies.","evidence":"Over eighty percent of the global human population now lives under light-polluted skies"},{"id":"l9-q13","questionNumber":13,"type":"multiple_choice_single","topic":"technology","estimatedBand":7,"prompt":"Streetlights in surrounding towns were replaced with luminaires emitting","options":["bright white halogen light.","downward-shielded amber LED light.","multi-colored fluorescent light."],"correctAnswer":"B","explanation":"Liam mentions downward-shielded, narrow-spectrum amber LED luminaires.","evidence":"replaced with downward-shielded, narrow-spectrum amber LED luminaires that emit zero upward light spill."},{"id":"l9-q14","questionNumber":14,"type":"multiple_choice_single","topic":"physics","estimatedBand":7.5,"prompt":"Color temperatures for town lighting are restricted to a maximum of","options":["1,500 Kelvin.","4,000 Kelvin.","2,200 Kelvin."],"correctAnswer":"C","explanation":"Liam notes color temperatures are strictly capped at two thousand two hundred Kelvin.","evidence":"strictly capped at two thousand two hundred Kelvin, eliminating the high-frequency blue photons"},{"id":"l9-q15","questionNumber":15,"type":"multiple_choice_single","topic":"facilities","estimatedBand":6.5,"prompt":"The Solar Astronomy Observatory operates during","options":["daylight hours.","midnight only.","lunar eclipses."],"correctAnswer":"A","explanation":"Liam states the solar observatory opens during daylight hours.","evidence":"which opens during daylight hours with hydrogen-alpha solar telescopes"},{"id":"l9-q16","questionNumber":16,"type":"multiple_choice_single","topic":"rules","estimatedBand":6,"prompt":"What kind of personal torch is permitted in the viewing areas?","options":["Blue LED torches.","Red-filtered flashlights.","High-powered searchlights."],"correctAnswer":"B","explanation":"Liam explains only red-filtered flashlights are permitted.","evidence":"only red-filtered flashlights are permitted beyond the car parks to preserve dark adaptation"}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l9-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Stargazer Plateau: Location ____","correctAnswer":"A","explanation":"Liam indicates Stargazer Plateau at location A.","evidence":"most popular is Stargazer Plateau at location A, featuring eight concrete telescope mounting piers"},{"id":"l9-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Astro-Photography Pods: Location ____","correctAnswer":"B","explanation":"Liam indicates Astro-Photography Pods to the west at location B.","evidence":"To the west at location B is the Astro-Photography Pods, equipped with vibration-isolated timber platforms"},{"id":"l9-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":7,"prompt":"Solar Astronomy Observatory: Location ____","correctAnswer":"C","explanation":"Liam indicates location C on the southern ridge as the Solar Astronomy Observatory.","evidence":"Location C on the southern ridge marks the Solar Astronomy Observatory"},{"id":"l9-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Indigenous Starlore Amphitheatre: Location ____","correctAnswer":"D","explanation":"Liam indicates location D beside the visitor lodge.","evidence":"Finally, at location D beside the visitor lodge is our Indigenous Starlore Amphitheatre"}]}]},{"sectionNumber":3,"title":"Undergraduate Project Review: Urban Rain Gardens and Stormwater Bio-retention","contextDescription":"Civil engineering lecturer Dr. Miller (North American English) reviewing a green infrastructure field experiment with students Dev (Indian English) and Rachel (British English).","audioScript":[{"speaker":"Dr. Miller (North American)","text":"Come in Dev, Rachel. Let's look over your preliminary data on the retrofitted urban rain garden test plot on East Campus. Urban runoff management is a critical civil engineering priority, and your field experiment is generating interesting results."},{"speaker":"Dev (Indian English)","text":"Thanks, Dr. Miller. Our objective was to evaluate how effectively an engineered bio-retention swale filters heavy metals and petroleum hydrocarbons from highway parking lot runoff during intense storm events."},{"speaker":"Rachel (British)","text":"We installed an engineered soil filter bed comprised of sixty percent medium silica sand, twenty percent horticultural compost, and twenty percent clay-loam. Beneath that is a thirty-centimeter drainage layer of washed crushed gravel surrounding a perforated PVC underdrain pipe."},{"speaker":"Dr. Miller (North American)","text":"And what did your water quality assays reveal about pollutant removal efficiency?"},{"speaker":"Dev (Indian English)","text":"The bio-retention swale demonstrated remarkable performance. Total suspended solids were reduced by eighty-eight percent. More impressively, dissolved zinc and copper—primarily from vehicle brake pad and tire wear—were captured with an efficiency of over eighty-two percent, bound tightly to the organic compost matrix."},{"speaker":"Rachel (British)","text":"However, we did encounter an unexpected challenge with hydraulic infiltration rates after three consecutive heavy downpours. Fine silt washed down from the neighboring embankment, forming a thin, impermeable crust on top of the mulch layer, which reduced stormwater infiltration velocity by nearly half."},{"speaker":"Dr. Miller (North American)","text":"That is a classic real-world maintenance vulnerability. How do you propose solving that in your final design?"},{"speaker":"Dev (Indian English)","text":"We recommend installing a small concrete forebay or gravel settling trench at the inlet. That will capture the heavy silt sediment before runoff enters the vegetative filter zone, making periodic sediment removal quick and inexpensive."},{"speaker":"Dr. Miller (North American)","text":"Excellent engineering solution. Make sure you incorporate a full lifecycle maintenance cost estimate in your final technical report."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l9-q21","questionNumber":21,"type":"multiple_choice_single","topic":"engineering","estimatedBand":7,"prompt":"The students' research aimed to evaluate how rain gardens filter runoff from","options":["residential rooftop gutters.","agricultural fertilizer fields.","a highway parking lot."],"correctAnswer":"C","explanation":"Dev states the goal was to evaluate runoff from 'highway parking lot runoff'.","evidence":"filters heavy metals and petroleum hydrocarbons from highway parking lot runoff"},{"id":"l9-q22","questionNumber":22,"type":"multiple_choice_single","topic":"materials","estimatedBand":7,"prompt":"What percentage of the engineered soil mix consists of medium silica sand?","options":["60%.","20%.","50%."],"correctAnswer":"A","explanation":"Rachel notes the mix is comprised of sixty percent medium silica sand.","evidence":"comprised of sixty percent medium silica sand, twenty percent horticultural compost"},{"id":"l9-q23","questionNumber":23,"type":"multiple_choice_single","topic":"engineering","estimatedBand":7.5,"prompt":"The swale achieved an 88% reduction in","options":["dissolved nitrogen.","total suspended solids.","water temperature."],"correctAnswer":"B","explanation":"Dev states: 'Total suspended solids were reduced by eighty-eight percent.'","evidence":"Total suspended solids were reduced by eighty-eight percent."},{"id":"l9-q24","questionNumber":24,"type":"multiple_choice_single","topic":"chemistry","estimatedBand":7,"prompt":"Dissolved zinc and copper in the stormwater originated primarily from","options":["underground galvanized pipes.","industrial factory chimneys.","vehicle brake pads and tire wear."],"correctAnswer":"C","explanation":"Dev notes zinc and copper came from vehicle brake pad and tire wear.","evidence":"dissolved zinc and copper—primarily from vehicle brake pad and tire wear—were captured"},{"id":"l9-q25","questionNumber":25,"type":"multiple_choice_single","topic":"hydrology","estimatedBand":7.5,"prompt":"Infiltration rates dropped significantly because fine silt created","options":["an impermeable crust on the mulch.","blockages in the perforated PVC pipe.","a toxic chemical reaction."],"correctAnswer":"A","explanation":"Rachel explains silt formed a thin, impermeable crust on top of the mulch layer.","evidence":"forming a thin, impermeable crust on top of the mulch layer, which reduced stormwater infiltration velocity"},{"id":"l9-q26","questionNumber":26,"type":"multiple_choice_single","topic":"engineering","estimatedBand":7.5,"prompt":"Dev suggests resolving the silt problem by installing a","options":["motorized vacuum suction pump.","concrete forebay or gravel settling trench.","high-pressure water sprinkler."],"correctAnswer":"B","explanation":"Dev recommends installing a small concrete forebay or gravel settling trench at the inlet.","evidence":"installing a small concrete forebay or gravel settling trench at the inlet."}]},{"groupInstruction":"Which student or lecturer made each recommendation or observation? Write the correct letter, A, B, or C, in boxes 27–30.\\nA: Dr. Miller\\nB: Dev\\nC: Rachel","questionType":"matching","questions":[{"id":"l9-q27","questionNumber":27,"type":"matching","topic":"discussion","estimatedBand":6.5,"prompt":"Explaining the proportions of sand, compost, and clay-loam in the filter bed.","correctAnswer":"C","explanation":"Rachel describes the engineered soil filter bed recipe.","evidence":"Rachel: We installed an engineered soil filter bed comprised of sixty percent medium silica sand"},{"id":"l9-q28","questionNumber":28,"type":"matching","topic":"discussion","estimatedBand":7,"prompt":"Reporting the 82% capture efficiency for dissolved metals.","correctAnswer":"B","explanation":"Dev presents the 82% capture efficiency for zinc and copper.","evidence":"Dev: dissolved zinc and copper... were captured with an efficiency of over eighty-two percent"},{"id":"l9-q29","questionNumber":29,"type":"matching","topic":"discussion","estimatedBand":7,"prompt":"Describing how fine embankment silt halved infiltration rates.","correctAnswer":"C","explanation":"Rachel details the reduction in stormwater infiltration velocity.","evidence":"Rachel: Fine silt washed down... reduced stormwater infiltration velocity by nearly half."},{"id":"l9-q30","questionNumber":30,"type":"matching","topic":"discussion","estimatedBand":7.5,"prompt":"Advising the inclusion of a lifecycle maintenance cost calculation.","correctAnswer":"A","explanation":"Dr. Miller advises incorporating a full lifecycle maintenance cost estimate.","evidence":"Dr. Miller: Make sure you incorporate a full lifecycle maintenance cost estimate in your final technical report."}]}]},{"sectionNumber":4,"title":"Academic Lecture: The Evolution of Writing Systems from Cuneiform to the Phoenician Alphabet","contextDescription":"Professor Hugh Langford (British English speaker) delivering an academic archaeology lecture on the historical transition from logographic scripts to phonetic alphabets.","audioScript":[{"speaker":"Professor Langford (British)","text":"Good afternoon, students. Today we trace one of humanity's greatest cognitive and technological achievements: the invention and evolutionary trajectory of writing systems. Prior to writing, human collective memory was restricted to oral transmission, constrained by the mortal lifespan and cognitive limits of individual bards and elders."},{"speaker":"Professor Langford (British)","text":"The earliest indisputable writing emerged around three thousand two hundred BCE in southern Mesopotamia among the Sumerians. Known as cuneiform—from the Latin cuneus, meaning 'wedge'—this script was inscribed by impressing the beveled edge of a sharpened river reed stylus into damp clay tablets. Initially, cuneiform was not a vehicle for poetry or philosophy; it was a pragmatic bureaucratic accounting technology devised to tally temple grain surpluses, livestock counts, and beer rations."},{"speaker":"Professor Langford (British)","text":"Early cuneiform and contemporaneous Egyptian hieroglyphics were complex logographic and syllabic systems requiring scribes to memorize upwards of seven hundred distinct graphemic signs. Because literacy demanded a decade of intense scribal apprenticeship, writing remained an elite instrument of administrative control monopolized by high priests and royal bureaucrats."},{"speaker":"Professor Langford (British)","text":"The democratic democratization of literacy occurred around one thousand eight hundred BCE in the Sinai Peninsula. Semitic turquoise mine laborers, interacting with Egyptian hieroglyphs, devised Proto-Sinaitic: the world's first true phonetic alphabet. Instead of assigning a unique symbol to every word or idea, they applied the acrophonic principle: selecting roughly twenty-two simple pictograms, where each symbol represented only the initial consonant sound of the depicted object. For example, a drawing of an ox head—termed 'alp'—came to represent the consonant sound 'ah'."},{"speaker":"Professor Langford (British)","text":"This brilliant twenty-two-letter consonantal abjad was refined by the maritime Phoenicians, who traded throughout the Mediterranean basin. By stripping away redundant logograms, the Phoenician alphabet allowed an ordinary merchant to achieve functional literacy in mere weeks rather than decades. Adopted and modified by the ancient Greeks—who added dedicated vowels—and subsequently the Romans, this concise twenty-two-symbol phonetic breakthrough became the direct ancestral template for every modern European alphabet."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l9-q31","questionNumber":31,"type":"sentence_completion","topic":"archaeology","estimatedBand":7,"prompt":"Cuneiform writing first developed around ____ BCE in southern Mesopotamia.","correctAnswer":["3200","3,200","three thousand two hundred"],"explanation":"Professor Langford states writing emerged around three thousand two hundred BCE.","evidence":"emerged around three thousand two hundred BCE in southern Mesopotamia"},{"id":"l9-q32","questionNumber":32,"type":"sentence_completion","topic":"linguistics","estimatedBand":7,"prompt":"The word cuneiform originates from a Latin word meaning ____.","correctAnswer":"wedge","explanation":"Professor Langford explains cuneiform is from Latin cuneus, meaning wedge.","evidence":"from the Latin cuneus, meaning 'wedge'"},{"id":"l9-q33","questionNumber":33,"type":"sentence_completion","topic":"archaeology","estimatedBand":6.5,"prompt":"Sumerian scribes pressed the edge of a river ____ stylus into damp clay.","correctAnswer":"reed","explanation":"Professor Langford mentions impressing the beveled edge of a sharpened river reed stylus.","evidence":"impressing the beveled edge of a sharpened river reed stylus into damp clay tablets."},{"id":"l9-q34","questionNumber":34,"type":"sentence_completion","topic":"history","estimatedBand":6.5,"prompt":"Early writing was primarily invented as a tool for bureaucratic ____.","correctAnswer":"accounting","explanation":"Professor Langford describes it as a pragmatic bureaucratic accounting technology.","evidence":"pragmatic bureaucratic accounting technology devised to tally temple grain surpluses"},{"id":"l9-q35","questionNumber":35,"type":"sentence_completion","topic":"linguistics","estimatedBand":7.5,"prompt":"Ancient scribes had to memorize more than ____ distinct symbols.","correctAnswer":["700","seven hundred"],"explanation":"Professor Langford notes memorizing upwards of seven hundred distinct graphemic signs.","evidence":"memorize upwards of seven hundred distinct graphemic signs."},{"id":"l9-q36","questionNumber":36,"type":"sentence_completion","topic":"history","estimatedBand":7.5,"prompt":"Proto-Sinaitic writing was invented by Semitic laborers working in ____ mines.","correctAnswer":"turquoise","explanation":"Professor Langford mentions Semitic turquoise mine laborers.","evidence":"Semitic turquoise mine laborers, interacting with Egyptian hieroglyphs, devised Proto-Sinaitic"},{"id":"l9-q37","questionNumber":37,"type":"sentence_completion","topic":"linguistics","estimatedBand":8,"prompt":"The phonetic system used the ____ principle where a symbol represented an initial sound.","correctAnswer":"acrophonic","explanation":"Professor Langford explains they applied the acrophonic principle.","evidence":"they applied the acrophonic principle: selecting roughly twenty-two simple pictograms"},{"id":"l9-q38","questionNumber":38,"type":"sentence_completion","topic":"linguistics","estimatedBand":7.5,"prompt":"The original phonetic alphabet consisted of approximately ____ letters.","correctAnswer":["22","twenty-two"],"explanation":"Professor Langford mentions roughly twenty-two simple pictograms.","evidence":"selecting roughly twenty-two simple pictograms"},{"id":"l9-q39","questionNumber":39,"type":"sentence_completion","topic":"history","estimatedBand":7,"prompt":"The Phoenician alphabet was spread across the Mediterranean by ____ traders.","correctAnswer":"maritime","explanation":"Professor Langford notes refined by maritime Phoenicians.","evidence":"refined by the maritime Phoenicians, who traded throughout the Mediterranean basin."},{"id":"l9-q40","questionNumber":40,"type":"sentence_completion","topic":"linguistics","estimatedBand":7,"prompt":"The ancient Greeks adapted the script by introducing dedicated ____.","correctAnswer":"vowels","explanation":"Professor Langford states Greeks modified the script by adding dedicated vowels.","evidence":"Adopted and modified by the ancient Greeks—who added dedicated vowels"}]}]}]`),ve={id:G,title:H,difficulty:F,timeLimitMinutes:V,sections:j},U="list-test-10",K="Listening Practice Test 10",$="easy",J=40,Y=JSON.parse(`[{"sectionNumber":1,"title":"Residential Solar Panel Installation Consultation","contextDescription":"Neha (Indian English speaker) enquiring with Solar Energy Advisor Brian (Australian English speaker) about installing photovoltaic panels on her suburban home.","audioScript":[{"speaker":"Brian (Australian)","text":"G'day! Sunburst Renewable Energy Solutions. Brian speaking."},{"speaker":"Neha (Indian English)","text":"Hello Brian! My name is Neha Verma. I am calling to schedule a site feasibility inspection for installing a rooftop solar and battery storage system on my house."},{"speaker":"Brian (Australian)","text":"No worries at all, Neha! I can certainly assist with that. Let me grab your contact details and home specifications."},{"speaker":"Neha (Indian English)","text":"Sure. My first name is Neha, N-E-H-A, and surname Verma, V-E-R-M-A."},{"speaker":"Brian (Australian)","text":"Thanks, Neha. And what is your property street address?"},{"speaker":"Neha (Indian English)","text":"It is fifty-eight Banksia Avenue, Brisbane, postcode four zero six seven."},{"speaker":"Brian (Australian)","text":"Banksia Avenue, four zero six seven. And your mobile phone number?"},{"speaker":"Neha (Indian English)","text":"It is zero four eight eight, one two three four five six."},{"speaker":"Brian (Australian)","text":"Got it. Now, what type of roof cladding does your house have—terracotta tiles, corrugated Colorbond metal, or slate?"},{"speaker":"Neha (Indian English)","text":"It is corrugated Colorbond steel, pitched at approximately twenty-five degrees."},{"speaker":"Brian (Australian)","text":"Corrugated metal is the absolute easiest to mount panels on. Based on your household power usage, our standard six point six kilowatt system with twelve high-efficiency monocrystalline panels will generate about twenty-four kilowatt-hours of clean electricity daily."},{"speaker":"Neha (Indian English)","text":"And what is the estimated cost after the federal government rebate?"},{"speaker":"Brian (Australian)","text":"With the Small-scale Renewable Energy Scheme rebate deducted upfront, the net price for the complete package is four thousand eight hundred dollars, which includes an Austrian-made inverter."},{"speaker":"Neha (Indian English)","text":"That is within our budget. What warranty is provided on the hardware?"},{"speaker":"Brian (Australian)","text":"You get a twenty-five-year performance warranty on the solar panels, and a ten-year replacement warranty on the central inverter unit."},{"speaker":"Neha (Indian English)","text":"That gives great peace of mind. When could an engineer inspect our roof structure?"},{"speaker":"Brian (Australian)","text":"Our structural assessor can visit this Friday, November the twenty-second, at ten thirty in the morning."},{"speaker":"Neha (Indian English)","text":"Friday the twenty-second at ten thirty AM suits me perfectly. Thank you, Brian!"}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l10-q1","questionNumber":1,"type":"sentence_completion","topic":"customer enquiry","estimatedBand":5.5,"prompt":"Customer surname: ____","correctAnswer":"Verma","explanation":"Neha spells her surname: V-E-R-M-A.","evidence":"surname Verma, V-E-R-M-A."},{"id":"l10-q2","questionNumber":2,"type":"sentence_completion","topic":"address","estimatedBand":5.5,"prompt":"Street address: 58 ____ Avenue, Brisbane.","correctAnswer":"Banksia","explanation":"Neha states: fifty-eight Banksia Avenue.","evidence":"fifty-eight Banksia Avenue, Brisbane"},{"id":"l10-q3","questionNumber":3,"type":"sentence_completion","topic":"postcode","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["4067","four zero six seven"],"explanation":"Neha gives postcode: four zero six seven.","evidence":"postcode four zero six seven."},{"id":"l10-q4","questionNumber":4,"type":"sentence_completion","topic":"telephone","estimatedBand":5.5,"prompt":"Contact mobile: 0488 ____","correctAnswer":"123456","explanation":"Neha gives: zero four eight eight, one two three four five six.","evidence":"zero four eight eight, one two three four five six."},{"id":"l10-q5","questionNumber":5,"type":"sentence_completion","topic":"construction","estimatedBand":6,"prompt":"Roof material: corrugated ____ steel.","correctAnswer":"Colorbond","explanation":"Neha states: corrugated Colorbond steel.","evidence":"corrugated Colorbond steel, pitched at approximately"},{"id":"l10-q6","questionNumber":6,"type":"sentence_completion","topic":"energy","estimatedBand":6.5,"prompt":"Recommended system capacity: ____ kilowatts.","correctAnswer":["6.6","six point six"],"explanation":"Brian recommends a standard six point six kilowatt system.","evidence":"our standard six point six kilowatt system with twelve high-efficiency"},{"id":"l10-q7","questionNumber":7,"type":"sentence_completion","topic":"finance","estimatedBand":6,"prompt":"Total net price after rebate: $____","correctAnswer":["4800","4,800","four thousand eight hundred"],"explanation":"Brian quotes four thousand eight hundred dollars.","evidence":"net price for the complete package is four thousand eight hundred dollars"},{"id":"l10-q8","questionNumber":8,"type":"sentence_completion","topic":"warranty","estimatedBand":6.5,"prompt":"Inverter replacement warranty duration: ____ years.","correctAnswer":["10","ten"],"explanation":"Brian confirms a ten-year replacement warranty on the inverter.","evidence":"ten-year replacement warranty on the central inverter unit."},{"id":"l10-q9","questionNumber":9,"type":"sentence_completion","topic":"dates","estimatedBand":6,"prompt":"Inspection appointment date: Friday, November ____","correctAnswer":["22nd","22","twenty-second"],"explanation":"Brian confirms Friday, November the twenty-second.","evidence":"Friday, November the twenty-second, at ten thirty in the morning."},{"id":"l10-q10","questionNumber":10,"type":"sentence_completion","topic":"time","estimatedBand":5.5,"prompt":"Appointment time: ____ AM.","correctAnswer":["10:30","10.30","ten thirty"],"explanation":"Brian specifies ten thirty in the morning.","evidence":"at ten thirty in the morning."}]}]},{"sectionNumber":2,"title":"Visitor Tour of the Regional Maritime Lighthouse Museum","contextDescription":"Senior Curator Edward (British English speaker) providing a historical orientation talk to a tour group at the South Foreland Victorian Lighthouse Museum.","audioScript":[{"speaker":"Edward (British)","text":"Good morning ladies and gentlemen, and welcome to South Foreland Victorian Lighthouse! I am Edward, the senior heritage curator. Perched atop these white chalk cliffs overlooking the Strait of Dover, this lighthouse has safeguarded maritime navigation along one of the world's busiest shipping lanes since 1843."},{"speaker":"Edward (British)","text":"South Foreland holds a celebrated place in global technological history. In 1858, it became the very first lighthouse on Earth to be illuminated by electric arc light, engineered by Michael Faraday. Later, in 1898, Guglielmo Marconi installed a wireless radio transmitter in our lantern room, broadcasting the world's first ship-to-shore wireless distress telegraph across the English Channel."},{"speaker":"Edward (British)","text":"Let me direct your attention to the site map in your visitor brochures. We are currently standing in the Keeper's Parlour on the ground floor. If you exit the back door and follow the gravel path westward to location A, you will find the original 1870 Steam Foghorn Engine Shed. Inside, the massive coal-fired twin steam boilers that powered our acoustic sirens have been fully restored."},{"speaker":"Edward (British)","text":"Location B to the north marks the Fresnel Lens Optical Vault. Here, you can examine a giant six-foot rotating biconvex glass lens crafted in Paris, which refracted light into a beam visible for twenty-six nautical miles."},{"speaker":"Edward (British)","text":"Continuing eastward along the cliff path brings you to location C, the Victorian Kitchen & Pantry Garden. Volunteers have planted period-accurate heirloom root vegetables and medicinal herbs that keepers' families cultivated during winter isolations."},{"speaker":"Edward (British)","text":"Finally, location D at the base of the tower is the Marconi Wireless Telegraphy Station. Our radio amateur volunteers conduct live Morse code demonstrations every hour on the half-hour."},{"speaker":"Edward (British)","text":"A quick safety advisory: the iron spiral staircase to the lantern gallery consists of seventy-six narrow steps. Please hold the handrails firmly, and leave heavy backpacks in the cloakroom lockers. Enjoy your visit!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l10-q11","questionNumber":11,"type":"multiple_choice_single","topic":"history","estimatedBand":6,"prompt":"The South Foreland Lighthouse has guided maritime navigation since","options":["1858.","1898.","1843."],"correctAnswer":"C","explanation":"Edward notes the lighthouse has guided shipping lanes since 1843.","evidence":"safeguarded maritime navigation along one of the world's busiest shipping lanes since 1843."},{"id":"l10-q12","questionNumber":12,"type":"multiple_choice_single","topic":"technology","estimatedBand":6.5,"prompt":"In 1858, South Foreland became the first lighthouse to use","options":["electric arc light.","whale oil lamps.","solar-powered bulbs."],"correctAnswer":"A","explanation":"Edward states it became the very first lighthouse to be illuminated by electric arc light.","evidence":"very first lighthouse on Earth to be illuminated by electric arc light, engineered by Michael Faraday."},{"id":"l10-q13","questionNumber":13,"type":"multiple_choice_single","topic":"history","estimatedBand":6.5,"prompt":"What historic milestone was achieved at the lighthouse by Marconi in 1898?","options":["The first submarine radar detection.","The first ship-to-shore wireless distress telegraph.","The first television broadcast."],"correctAnswer":"B","explanation":"Edward highlights the world's first ship-to-shore wireless distress telegraph.","evidence":"broadcasting the world's first ship-to-shore wireless distress telegraph across the English Channel."},{"id":"l10-q14","questionNumber":14,"type":"multiple_choice_single","topic":"optics","estimatedBand":7,"prompt":"The historic French-crafted Fresnel lens could project a light beam up to","options":["12 nautical miles.","40 nautical miles.","26 nautical miles."],"correctAnswer":"C","explanation":"Edward notes light was visible for twenty-six nautical miles.","evidence":"refracted light into a beam visible for twenty-six nautical miles."},{"id":"l10-q15","questionNumber":15,"type":"multiple_choice_single","topic":"demonstration","estimatedBand":6,"prompt":"Live Morse code demonstrations take place","options":["every hour on the half-hour.","once daily at noon.","on Sunday afternoons only."],"correctAnswer":"A","explanation":"Edward states demonstrations run every hour on the half-hour.","evidence":"conduct live Morse code demonstrations every hour on the half-hour."},{"id":"l10-q16","questionNumber":16,"type":"multiple_choice_single","topic":"safety","estimatedBand":5.5,"prompt":"How many steps make up the iron spiral staircase?","options":["50.","76.","120."],"correctAnswer":"B","explanation":"Edward notes the staircase consists of seventy-six narrow steps.","evidence":"spiral staircase to the lantern gallery consists of seventy-six narrow steps."}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l10-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Steam Foghorn Engine Shed: Location ____","correctAnswer":"A","explanation":"Edward indicates location A westward along the gravel path as the Steam Foghorn Engine Shed.","evidence":"follow the gravel path westward to location A, you will find the original 1870 Steam Foghorn Engine Shed."},{"id":"l10-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Fresnel Lens Optical Vault: Location ____","correctAnswer":"B","explanation":"Edward indicates location B to the north as the Fresnel Lens Optical Vault.","evidence":"Location B to the north marks the Fresnel Lens Optical Vault."},{"id":"l10-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Victorian Kitchen & Pantry Garden: Location ____","correctAnswer":"C","explanation":"Edward indicates location C eastward along the cliff path as the Victorian Kitchen & Pantry Garden.","evidence":"Continuing eastward along the cliff path brings you to location C, the Victorian Kitchen & Pantry Garden."},{"id":"l10-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Marconi Wireless Telegraphy Station: Location ____","correctAnswer":"D","explanation":"Edward indicates location D at the base of the tower as the Marconi Wireless Telegraphy Station.","evidence":"Finally, location D at the base of the tower is the Marconi Wireless Telegraphy Station."}]}]},{"sectionNumber":3,"title":"Academic Tutorial: Comparative Analysis of Modular Prefabricated Construction","contextDescription":"Architecture Professor Wallace (British English) discussing industrial building technology with students Kyle (North American English) and Divya (Indian English).","audioScript":[{"speaker":"Professor Wallace (British)","text":"Good morning Kyle, Divya. Let us examine your dissertation draft comparing offsite volumetric modular construction with conventional in-situ concrete methods. Your life-cycle carbon calculations are solid, but I want to make sure your logistical analysis is rigorous."},{"speaker":"Kyle (North American)","text":"Thanks, Professor Wallace. In our data, the single greatest benefit of modular prefabrication is schedule compression. Because site excavation and underground foundation piling occur concurrently with three-dimensional module manufacturing inside a factory, overall project timelines are slashed by thirty to fifty percent."},{"speaker":"Divya (Indian English)","text":"And from an environmental perspective, factory assembly minimizes construction material waste by up to eighty percent compared to traditional construction sites. Factory off-cuts of structural timber, plasterboard, and insulation are collected in centralized recycling hoppers rather than dumped in open skips exposed to rain."},{"speaker":"Professor Wallace (British)","text":"Very true. But what about structural and transport constraints? That is where several high-profile modular contractors have stumbled."},{"speaker":"Kyle (North American)","text":"Right. We highlighted that road transport regulations impose strict geometric boundaries. Highway overpasses limit maximum module widths to four point two meters and heights to three point six meters. If an architectural plan requires large, pillarless open spaces—like auditoriums or hotel ballrooms—modular design becomes structurally inefficient."},{"speaker":"Divya (Indian English)","text":"Furthermore, modular construction requires full architectural design freeze before factory assembly commences. Conventional construction allows developers to alter interior partitions or electrical layouts late in the build, but with prefabrication, late engineering change orders are prohibitively expensive."},{"speaker":"Professor Wallace (British)","text":"Precisely. Now, how are you allocating your final report chapters for next week?"},{"speaker":"Kyle (North American)","text":"I will author the logistics and crane installation chapter, modeling the heavy mobile crane capacity needed for high-rise stacking."},{"speaker":"Divya (Indian English)","text":"And I will finalize the embodied carbon comparison, evaluating cross-laminated timber modules against structural steel frames."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l10-q21","questionNumber":21,"type":"multiple_choice_single","topic":"construction","estimatedBand":7,"prompt":"Modular construction reduces project schedules by 30 to 50 percent because","options":["construction workers work twenty-four hours a day.","building regulations are completely waived for modular homes.","foundation work and factory module fabrication occur simultaneously."],"correctAnswer":"C","explanation":"Kyle explains site excavation occurs concurrently with module manufacturing inside a factory.","evidence":"Because site excavation and underground foundation piling occur concurrently with three-dimensional module manufacturing inside a factory"},{"id":"l10-q22","questionNumber":22,"type":"multiple_choice_single","topic":"environment","estimatedBand":6.5,"prompt":"Factory manufacturing reduces construction site material waste by up to","options":["80%.","30%.","50%."],"correctAnswer":"A","explanation":"Divya states factory assembly minimizes material waste by up to eighty percent.","evidence":"factory assembly minimizes construction material waste by up to eighty percent"},{"id":"l10-q23","questionNumber":23,"type":"multiple_choice_single","topic":"transport","estimatedBand":7,"prompt":"Highway overpass regulations restrict maximum module width to","options":["3.6 meters.","4.2 meters.","5.5 meters."],"correctAnswer":"B","explanation":"Kyle notes highway overpasses limit maximum module widths to four point two meters.","evidence":"limit maximum module widths to four point two meters and heights to three point six meters."},{"id":"l10-q24","questionNumber":24,"type":"multiple_choice_single","topic":"architecture","estimatedBand":7,"prompt":"Modular construction is poorly suited for architectural spaces requiring","options":["standard repetitive hotel rooms.","bathroom pods.","large open spaces without supporting pillars."],"correctAnswer":"C","explanation":"Kyle explains that large, pillarless open spaces like auditoriums make modular design inefficient.","evidence":"architectural plan requires large, pillarless open spaces—like auditoriums or hotel ballrooms—modular design becomes structurally inefficient."},{"id":"l10-q25","questionNumber":25,"type":"multiple_choice_single","topic":"management","estimatedBand":7.5,"prompt":"Why are late design modifications especially costly in modular building?","options":["Complete architectural designs must be locked in before factory assembly begins.","Building materials cannot be cut by hand.","Local governments fine contractors for changing plans."],"correctAnswer":"A","explanation":"Divya states modular construction requires full architectural design freeze before assembly commences.","evidence":"modular construction requires full architectural design freeze before factory assembly commences."},{"id":"l10-q26","questionNumber":26,"type":"multiple_choice_single","topic":"engineering","estimatedBand":7,"prompt":"High-rise modular assembly requires specialized engineering calculations for","options":["underground water pressure.","heavy mobile crane stacking capacity.","window cleaning ropes."],"correctAnswer":"B","explanation":"Kyle mentions modeling heavy mobile crane capacity needed for high-rise stacking.","evidence":"modeling the heavy mobile crane capacity needed for high-rise stacking."}]},{"groupInstruction":"Which student is responsible for each section of the final report? Write the correct letter, A or B, in boxes 27–30.\\nA: Kyle\\nB: Divya","questionType":"matching","questions":[{"id":"l10-q27","questionNumber":27,"type":"matching","topic":"assignment","estimatedBand":6.5,"prompt":"Explaining simultaneous foundation piling and factory fabrication schedules.","correctAnswer":"A","explanation":"Kyle explains schedule compression and concurrent manufacturing.","evidence":"Kyle: In our data, the single greatest benefit of modular prefabrication is schedule compression."},{"id":"l10-q28","questionNumber":28,"type":"matching","topic":"assignment","estimatedBand":7,"prompt":"Analyzing timber and plasterboard waste reduction in centralized factory hoppers.","correctAnswer":"B","explanation":"Divya details factory material waste reduction.","evidence":"Divya: Factory off-cuts of structural timber, plasterboard, and insulation are collected"},{"id":"l10-q29","questionNumber":29,"type":"matching","topic":"assignment","estimatedBand":7.5,"prompt":"Modeling mobile crane lifting loads for high-rise volumetric stacking.","correctAnswer":"A","explanation":"Kyle confirms he will author the logistics and crane installation chapter.","evidence":"Kyle: I will author the logistics and crane installation chapter"},{"id":"l10-q30","questionNumber":30,"type":"matching","topic":"assignment","estimatedBand":7.5,"prompt":"Comparing embodied carbon metrics between cross-laminated timber and steel frames.","correctAnswer":"B","explanation":"Divya confirms she will finalize the embodied carbon comparison.","evidence":"Divya: And I will finalize the embodied carbon comparison, evaluating cross-laminated timber modules"}]}]},{"sectionNumber":4,"title":"Academic Lecture: The Evolution and Cognitive Ecology of Cephalopod Intelligence","contextDescription":"Dr. Miranda Price (Australian English speaker) delivering a university biology lecture on invertebrate neurobiology and octopus cognitive evolution.","audioScript":[{"speaker":"Dr. Price (Australian)","text":"Good afternoon, students. In classical evolutionary biology, complex intelligence was long regarded as an exclusive evolutionary prerogative of vertebrates—specifically birds and mammals with large, centralized brains. However, the class Cephalopoda—predominantly octopuses, cuttlefish, and squid—represents a profound evolutionary anomaly: an invertebrate lineage that developed remarkable cognitive sophistication entirely independently from vertebrates."},{"speaker":"Dr. Price (Australian)","text":"To understand cephalopod neuroanatomy, we must examine its radically decentralized architecture. An adult common octopus (Octopus vulgaris) possesses roughly five hundred million neurons—comparable to the neural count of a domestic dog. Crucially, however, less than one-third of these neurons reside within the central brain encircling the esophagus. The remaining two-thirds are distributed throughout the animal's eight flexible arms. Each arm possesses an independent subcortical neural ganglion that processes tactile, chemical, and proprioceptive sensory inputs locally, allowing individual arms to explore crevices, taste substrates, and manipulate objects semi-autonomously without continuous top-down commands from the brain."},{"speaker":"Dr. Price (Australian)","text":"Why did cephalopods evolve such formidable intellect? Paleobiological fossil records indicate that during the Mesozoic Era, ancestral cephalopods lost their heavy external protective shells. While shedding their calcified armor bestowed unprecedented agility and camouflage prowess, it left them soft-bodied and exquisitely vulnerable to swift, jawed teleost fish predators. Natural selection favored individuals capable of dynamic tactical problem-solving, spatial memory mapping, and predatory deception."},{"speaker":"Dr. Price (Australian)","text":"In laboratory cognitive paradigms, octopuses demonstrate advanced executive abilities, including tool use, maze navigation, associative learning, and flexible play behavior. For example, wild veined octopuses in Indonesia routinely harvest discarded coconut shell halves, carrying them across open sandy seafloors to assemble armored defensive shelters against sharks—an indisputable manifestation of foresight and multi-step tool utilization. The cephalopod mind proves that nature can construct sophisticated intelligence along a radically distinct neuroarchitectural blueprint."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l10-q31","questionNumber":31,"type":"sentence_completion","topic":"biology","estimatedBand":7,"prompt":"An adult common octopus has approximately ____ million neurons.","correctAnswer":["500","five hundred"],"explanation":"Dr. Price states roughly five hundred million neurons.","evidence":"possesses roughly five hundred million neurons—comparable to the neural count of a domestic dog."},{"id":"l10-q32","questionNumber":32,"type":"sentence_completion","topic":"anatomy","estimatedBand":7.5,"prompt":"The central brain is situated encircling the animal's ____.","correctAnswer":"esophagus","explanation":"Dr. Price states the central brain encircles the esophagus.","evidence":"central brain encircling the esophagus."},{"id":"l10-q33","questionNumber":33,"type":"sentence_completion","topic":"neurobiology","estimatedBand":7,"prompt":"Over two-thirds of an octopus's neurons are distributed across its eight ____.","correctAnswer":"arms","explanation":"Dr. Price notes two-thirds are distributed throughout the eight arms.","evidence":"The remaining two-thirds are distributed throughout the animal's eight flexible arms."},{"id":"l10-q34","questionNumber":34,"type":"sentence_completion","topic":"neurobiology","estimatedBand":8,"prompt":"Each arm contains a subcortical neural ____ to process information locally.","correctAnswer":"ganglion","explanation":"Dr. Price mentions each arm possesses an independent subcortical neural ganglion.","evidence":"Each arm possesses an independent subcortical neural ganglion"},{"id":"l10-q35","questionNumber":35,"type":"sentence_completion","topic":"paleontology","estimatedBand":7.5,"prompt":"Ancestral cephalopods lost their heavy external ____ during the Mesozoic Era.","correctAnswer":"shells","explanation":"Dr. Price explains ancestral cephalopods lost their heavy external protective shells.","evidence":"ancestral cephalopods lost their heavy external protective shells."},{"id":"l10-q36","questionNumber":36,"type":"sentence_completion","topic":"evolution","estimatedBand":7,"prompt":"Losing their armor made cephalopods vulnerable to jawed teleost ____.","correctAnswer":"fish","explanation":"Dr. Price refers to vulnerability to jawed teleost fish predators.","evidence":"exquisitely vulnerable to swift, jawed teleost fish predators."},{"id":"l10-q37","questionNumber":37,"type":"sentence_completion","topic":"zoology","estimatedBand":7,"prompt":"Wild veined octopuses in Indonesia harvest discarded ____ shells.","correctAnswer":"coconut","explanation":"Dr. Price mentions harvesting discarded coconut shell halves.","evidence":"wild veined octopuses in Indonesia routinely harvest discarded coconut shell halves"},{"id":"l10-q38","questionNumber":38,"type":"sentence_completion","topic":"behavior","estimatedBand":7.5,"prompt":"Octopuses assemble coconut shells to build defensive shelters against ____.","correctAnswer":"sharks","explanation":"Dr. Price notes assembling shelters against sharks.","evidence":"assemble armored defensive shelters against sharks"},{"id":"l10-q39","questionNumber":39,"type":"sentence_completion","topic":"cognitive science","estimatedBand":7.5,"prompt":"Carrying shells across the seafloor represents evidence of planning and ____.","correctAnswer":"foresight","explanation":"Dr. Price states an indisputable manifestation of foresight and multi-step tool utilization.","evidence":"an indisputable manifestation of foresight and multi-step tool utilization."},{"id":"l10-q40","questionNumber":40,"type":"sentence_completion","topic":"neurobiology","estimatedBand":8,"prompt":"Cephalopods prove intelligence can arise along a distinct evolutionary ____.","correctAnswer":"blueprint","explanation":"Dr. Price concludes nature can construct intelligence along a radically distinct neuroarchitectural blueprint.","evidence":"construct sophisticated intelligence along a radically distinct neuroarchitectural blueprint."}]}]}]`),xe={id:U,title:K,difficulty:$,timeLimitMinutes:J,sections:Y},Q="list-test-11",Z="Listening Practice Test 11",X="hard",ee=40,te=JSON.parse(`[{"sectionNumber":1,"title":"Alpine Hiking Club Guided Expedition Booking","contextDescription":"Rajesh (Indian English speaker) enquiring with Lead Mountaineering Guide Thomas (Scottish / British English speaker) about registering for a guided winter traverse in the Cairngorm Mountains.","audioScript":[{"speaker":"Thomas (Scottish/British)","text":"Good morning! Cairngorm Alpine Mountaineering Club. Thomas speaking."},{"speaker":"Rajesh (Indian English)","text":"Good morning, Thomas! My name is Rajesh Patel. I am looking to book a place on your five-day winter alpine ridge traverse next month."},{"speaker":"Thomas (Scottish/British)","text":"Grand, Rajesh! The Cairngorms in winter are spectacular, but they demand serious preparation. Let me take down your contact and experience details."},{"speaker":"Rajesh (Indian English)","text":"Certainly. My first name is Rajesh, R-A-J-E-S-H, and my surname is Patel, P-A-T-E-L."},{"speaker":"Thomas (Scottish/British)","text":"Thank you, Rajesh. And your contact mobile number?"},{"speaker":"Rajesh (Indian English)","text":"It is zero seven nine eight seven, six five four three two zero."},{"speaker":"Thomas (Scottish/British)","text":"Got it. And what is your residential address?"},{"speaker":"Rajesh (Indian English)","text":"I live at thirty-one Glenmore Close, Aviemore, postcode P-H-twenty-two, one-Q-R."},{"speaker":"Thomas (Scottish/British)","text":"P-H-twenty-two, one-Q-R. Now regarding technical mountaineering experience, have you previously completed winter ascents using crampons and a mountaineering ice axe?"},{"speaker":"Rajesh (Indian English)","text":"Yes, I completed a Scottish Winter Skills Level Two course in Glencoe last January, covering self-arrest and snow shelter construction."},{"speaker":"Thomas (Scottish/British)","text":"Excellent! That meets our prerequisite. The full expedition fee is five hundred and twenty pounds, which includes shared lodge accommodation and mountain guide instruction."},{"speaker":"Rajesh (Indian English)","text":"What specialized safety hardware must participants carry?"},{"speaker":"Thomas (Scottish/British)","text":"Every climber must carry a certified digital avalanche transceiver, a collapsible carbon snow probe, and a metal shovel blade. We provide the transceivers, but you must bring your own B2-rated mountaineering boots compatible with semi-automatic crampons."},{"speaker":"Rajesh (Indian English)","text":"Understood. When does the expedition assemble?"},{"speaker":"Thomas (Scottish/British)","text":"Our mandatory gear check and safety briefing begins at eight in the evening on Sunday, January the twelfth, at the Pine Lodge Mountain Base."},{"speaker":"Rajesh (Indian English)","text":"Sunday, January the twelfth at eight PM. Thank you so much, Thomas. See you in Aviemore!"}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l11-q1","questionNumber":1,"type":"sentence_completion","topic":"mountaineering","estimatedBand":5.5,"prompt":"Applicant surname: ____","correctAnswer":"Patel","explanation":"Rajesh spells his surname: P-A-T-E-L.","evidence":"surname is Patel, P-A-T-E-L."},{"id":"l11-q2","questionNumber":2,"type":"sentence_completion","topic":"contact","estimatedBand":5.5,"prompt":"Contact mobile number: 07987 ____","correctAnswer":"654320","explanation":"Rajesh states: zero seven nine eight seven, six five four three two zero.","evidence":"zero seven nine eight seven, six five four three two zero."},{"id":"l11-q3","questionNumber":3,"type":"sentence_completion","topic":"address","estimatedBand":6,"prompt":"Address: 31 ____ Close, Aviemore.","correctAnswer":"Glenmore","explanation":"Rajesh states thirty-one Glenmore Close.","evidence":"thirty-one Glenmore Close, Aviemore"},{"id":"l11-q4","questionNumber":4,"type":"sentence_completion","topic":"postcode","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["PH22 1QR","PH221QR","PH22","P H twenty two one Q R"],"explanation":"Rajesh gives postcode P-H-twenty-two, one-Q-R.","evidence":"postcode P-H-twenty-two, one-Q-R."},{"id":"l11-q5","questionNumber":5,"type":"sentence_completion","topic":"qualifications","estimatedBand":6.5,"prompt":"Prerequisite: completed Scottish Winter Skills Level ____.","correctAnswer":["Two","2"],"explanation":"Rajesh completed a Scottish Winter Skills Level Two course.","evidence":"Scottish Winter Skills Level Two course in Glencoe"},{"id":"l11-q6","questionNumber":6,"type":"sentence_completion","topic":"finance","estimatedBand":6,"prompt":"Total expedition fee: £____","correctAnswer":["520","five hundred and twenty"],"explanation":"Thomas states the fee is five hundred and twenty pounds.","evidence":"expedition fee is five hundred and twenty pounds"},{"id":"l11-q7","questionNumber":7,"type":"sentence_completion","topic":"safety equipment","estimatedBand":7,"prompt":"Supplied safety item: digital ____ transceiver.","correctAnswer":"avalanche","explanation":"Thomas states climbers must carry a certified digital avalanche transceiver.","evidence":"carry a certified digital avalanche transceiver"},{"id":"l11-q8","questionNumber":8,"type":"sentence_completion","topic":"gear","estimatedBand":7,"prompt":"Participants must bring their own ____-rated boots.","correctAnswer":"B2","explanation":"Thomas notes: 'must bring your own B2-rated mountaineering boots'.","evidence":"bring your own B2-rated mountaineering boots compatible with semi-automatic crampons."},{"id":"l11-q9","questionNumber":9,"type":"sentence_completion","topic":"dates","estimatedBand":6,"prompt":"Meeting date: Sunday, January ____","correctAnswer":["12th","12","twelfth"],"explanation":"Thomas confirms Sunday, January the twelfth.","evidence":"Sunday, January the twelfth, at the Pine Lodge Mountain Base."},{"id":"l11-q10","questionNumber":10,"type":"sentence_completion","topic":"time","estimatedBand":5.5,"prompt":"Gear check starts at ____ PM.","correctAnswer":["8","eight","8:00"],"explanation":"Thomas specifies eight in the evening.","evidence":"begins at eight in the evening on Sunday"}]}]},{"sectionNumber":2,"title":"Community Orientation: The Circular Economy E-Waste Recycling Hub","contextDescription":"Facility Operations Manager Hannah (North American English speaker) orienting community volunteers and residents to the Eastside Circular Electronic Recycling and Recovery Depot.","audioScript":[{"speaker":"Hannah (North American)","text":"Good morning everyone, and welcome to the Eastside Circular Electronics Resource Recovery Hub! My name is Hannah. Across North America and Europe, electronic waste—or e-waste—is the fastest-growing municipal waste stream, expanding three times faster than standard household refuse. Consumer electronics contain toxic heavy metals like lead, cadmium, and mercury, but they also harbor extraordinary concentrations of precious and critical raw materials: gold, silver, copper, palladium, and lithium."},{"speaker":"Hannah (North American)","text":"In fact, one metric ton of discarded smartphone circuit boards contains forty times more gold than a metric ton of freshly mined gold ore! Our mission here is to divert obsolete technology from incinerators, refurbishing usable devices for low-income school children and disassembling the rest into pure, high-grade commodity streams for domestic smelting."},{"speaker":"Hannah (North American)","text":"Let me orient you to our facility floor plan. Right now, we are assembled at the Main Drop-Off Bay on the southern entrance. Directly ahead of you to the northwest, location A marks the Battery & Hazardous Chemistry Cell. Here, technicians safely discharge and isolate damaged lithium-ion batteries inside fire-suppressant vermiculite barrels to prevent thermal runaway fires."},{"speaker":"Hannah (North American)","text":"Moving northeast from the entrance, location B is the Secure Data Destruction Suite. In this locked chamber, decommissioned hard drives and solid-state drives undergo automated physical degaussing followed by hydraulic shredding into two-millimeter particulate chips to guarantee zero data recovery."},{"speaker":"Hannah (North American)","text":"Location C in the center of the facility is the Diagnostic and Refurbishment Cleanroom. Our trained volunteers test computer motherboards, upgrade RAM, and install lightweight open-source Linux operating systems on donated laptops."},{"speaker":"Hannah (North American)","text":"Finally, at the far northern wall, location D marks the Automated Circuit Board Disassembly Line. Robotic desoldering arms harvest rare-earth capacitors, microprocessors, and copper heat pipes."},{"speaker":"Hannah (North American)","text":"A crucial safety protocol for all volunteers today: anti-static wrist straps and steel-toed boots must be worn in the cleanroom, and protective Kevlar gloves are mandatory whenever handling cracked glass screens. Let's begin our tour!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l11-q11","questionNumber":11,"type":"multiple_choice_single","topic":"e-waste","estimatedBand":6.5,"prompt":"Electronic waste is expanding how much faster than ordinary domestic trash?","options":["Twice as fast.","Ten times faster.","Three times faster."],"correctAnswer":"C","explanation":"Hannah states e-waste is expanding three times faster than standard household refuse.","evidence":"expanding three times faster than standard household refuse."},{"id":"l11-q12","questionNumber":12,"type":"multiple_choice_single","topic":"mining","estimatedBand":7,"prompt":"One ton of smartphone circuit boards contains how much more gold than mined ore?","options":["40 times more.","10 times more.","100 times more."],"correctAnswer":"A","explanation":"Hannah highlights that circuit boards contain forty times more gold than mined ore.","evidence":"contains forty times more gold than a metric ton of freshly mined gold ore!"},{"id":"l11-q13","questionNumber":13,"type":"multiple_choice_single","topic":"safety","estimatedBand":7,"prompt":"Lithium batteries are stored inside barrels filled with","options":["salt water.","vermiculite.","shredded paper."],"correctAnswer":"B","explanation":"Hannah notes lithium batteries are stored inside fire-suppressant vermiculite barrels.","evidence":"isolate damaged lithium-ion batteries inside fire-suppressant vermiculite barrels"},{"id":"l11-q14","questionNumber":14,"type":"multiple_choice_single","topic":"security","estimatedBand":7,"prompt":"To guarantee data security, shredded hard drives are chopped into pieces of","options":["10 millimeters.","25 millimeters.","2 millimeters."],"correctAnswer":"C","explanation":"Hannah explains hydraulic shredding cuts drives into two-millimeter particulate chips.","evidence":"hydraulic shredding into two-millimeter particulate chips to guarantee zero data recovery."},{"id":"l11-q15","questionNumber":15,"type":"multiple_choice_single","topic":"technology","estimatedBand":6.5,"prompt":"Refurbished laptops are equipped with which operating system?","options":["Open-source Linux.","Proprietary commercial software.","Cloud-only web browsers."],"correctAnswer":"A","explanation":"Hannah notes volunteers install lightweight open-source Linux operating systems.","evidence":"install lightweight open-source Linux operating systems on donated laptops."},{"id":"l11-q16","questionNumber":16,"type":"multiple_choice_single","topic":"safety","estimatedBand":6.5,"prompt":"Volunteers handling cracked screens must wear gloves made of","options":["cotton.","Kevlar.","latex."],"correctAnswer":"B","explanation":"Hannah states protective Kevlar gloves are mandatory.","evidence":"protective Kevlar gloves are mandatory whenever handling cracked glass screens."}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l11-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Battery & Hazardous Chemistry Cell: Location ____","correctAnswer":"A","explanation":"Hannah points northwest to location A as the Battery & Hazardous Chemistry Cell.","evidence":"Directly ahead of you to the northwest, location A marks the Battery & Hazardous Chemistry Cell."},{"id":"l11-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Secure Data Destruction Suite: Location ____","correctAnswer":"B","explanation":"Hannah points northeast to location B as the Secure Data Destruction Suite.","evidence":"Moving northeast from the entrance, location B is the Secure Data Destruction Suite."},{"id":"l11-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":7,"prompt":"Diagnostic and Refurbishment Cleanroom: Location ____","correctAnswer":"C","explanation":"Hannah indicates location C in the center as the Cleanroom.","evidence":"Location C in the center of the facility is the Diagnostic and Refurbishment Cleanroom."},{"id":"l11-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Automated Circuit Board Disassembly Line: Location ____","correctAnswer":"D","explanation":"Hannah indicates location D at the far northern wall.","evidence":"Finally, at the far northern wall, location D marks the Automated Circuit Board Disassembly Line."}]}]},{"sectionNumber":3,"title":"Postgraduate Seminar: Evaluating Machine Translation Quality and Hallucinations","contextDescription":"Computational linguistics professor Dr. Brooks (British English) reviewing neural machine translation research with students Anya (Indian English) and Marcus (Australian English).","audioScript":[{"speaker":"Dr. Brooks (British)","text":"Good afternoon Marcus, Anya. Let us review your experimental paper evaluating neural machine translation—or NMT—across low-resource Indo-Aryan and Indigenous Australian languages. Your BLEU score benchmarks are thorough, but I want to scrutinize your analysis of translation hallucinations."},{"speaker":"Marcus (Australian)","text":"Thanks, Dr. Brooks. In our experiments, we compared traditional statistical machine translation against transformer-based neural models. While transformers achieve remarkably fluent, human-like grammar, they exhibit an alarming vulnerability to catastrophic hallucinations: generating completely fabricated clauses or phantom names when processing rare source vocabulary."},{"speaker":"Anya (Indian English)","text":"Yes, especially in medical and legal domains. For example, when translating patient clinical notes from Hindi to English, an off-the-shelf neural model translated a rare regional symptom for stomach distress into the English phrase 'advanced pulmonary tuberculosis'—a hallucinated diagnosis that could have fatal real-world clinical consequences."},{"speaker":"Dr. Brooks (British)","text":"That is an extraordinary finding. Why do transformer models produce hallucinations rather than simply omitting unfamiliar words?"},{"speaker":"Marcus (Australian)","text":"It stems from how the self-attention mechanism operates. Large language models are trained on auto-regressive next-token prediction, prioritizing fluent linguistic coherence over strict semantic fidelity. When an unknown token appears in low-probability vector space, the decoder hallucinates plausible-sounding words to maximize statistical language likelihood."},{"speaker":"Anya (Indian English)","text":"To solve this, our proposed architecture integrates a copy-attention mechanism and external multilingual knowledge graphs. If the model's confidence entropy exceeds a threshold of zero point seven, the system flags the phrase for human-in-the-loop verification."},{"speaker":"Dr. Brooks (British)","text":"Excellent engineering. For next Thursday's department colloquium, how will you divide the speaking slots?"},{"speaker":"Marcus (Australian)","text":"I will deliver the mathematical overview of self-attention mechanisms and explain why hallucinations occur in high-entropy states."},{"speaker":"Anya (Indian English)","text":"And I will demonstrate our live benchmarking tool, showcasing real-time error detection on Hindi and Warlpiri medical texts."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l11-q21","questionNumber":21,"type":"multiple_choice_single","topic":"computational linguistics","estimatedBand":7.5,"prompt":"In computational linguistics, a machine translation 'hallucination' refers to","options":["software failing to boot up.","translating text too slowly.","generating fabricated phrases not present in the source text."],"correctAnswer":"C","explanation":"Marcus explains hallucinations as generating completely fabricated clauses or phantom names.","evidence":"generating completely fabricated clauses or phantom names when processing rare source vocabulary."},{"id":"l11-q22","questionNumber":22,"type":"multiple_choice_single","topic":"medicine","estimatedBand":7.5,"prompt":"In Anya's Hindi medical example, a mild stomach symptom was mistranslated as","options":["pulmonary tuberculosis.","acute heart attack.","fractured collarbone."],"correctAnswer":"A","explanation":"Anya notes it translated stomach distress into 'advanced pulmonary tuberculosis'.","evidence":"translated a rare regional symptom for stomach distress into the English phrase 'advanced pulmonary tuberculosis'"},{"id":"l11-q23","questionNumber":23,"type":"multiple_choice_single","topic":"artificial intelligence","estimatedBand":8,"prompt":"Transformer decoders generate hallucinations primarily because they prioritize","options":["processing speed over electrical efficiency.","grammatical fluency and statistical likelihood over factual accuracy.","short words over multi-syllable terms."],"correctAnswer":"B","explanation":"Marcus explains models prioritize fluent linguistic coherence over strict semantic fidelity.","evidence":"prioritizing fluent linguistic coherence over strict semantic fidelity."},{"id":"l11-q24","questionNumber":24,"type":"multiple_choice_single","topic":"computer science","estimatedBand":8,"prompt":"The students' proposed system flags phrases for human review when confidence entropy exceeds","options":["0.3.","0.5.","0.7."],"correctAnswer":"C","explanation":"Anya states: 'confidence entropy exceeds a threshold of zero point seven'.","evidence":"confidence entropy exceeds a threshold of zero point seven, the system flags the phrase"},{"id":"l11-q25","questionNumber":25,"type":"multiple_choice_single","topic":"linguistics","estimatedBand":7,"prompt":"Besides Hindi, which other language was included in their benchmark tests?","options":["Warlpiri.","Swahili.","Icelandic."],"correctAnswer":"A","explanation":"Anya mentions showcasing real-time error detection on Hindi and Warlpiri.","evidence":"showcasing real-time error detection on Hindi and Warlpiri medical texts."},{"id":"l11-q26","questionNumber":26,"type":"multiple_choice_single","topic":"education","estimatedBand":6.5,"prompt":"When will the students present their findings to the department colloquium?","options":["Next Tuesday.","Next Thursday.","Next Friday."],"correctAnswer":"B","explanation":"Dr. Brooks mentions next Thursday's department colloquium.","evidence":"For next Thursday's department colloquium, how will you divide the speaking slots?"}]},{"groupInstruction":"Which student is responsible for each part of the upcoming presentation? Write the correct letter, A or B, in boxes 27–30.\\nA: Marcus\\nB: Anya","questionType":"matching","questions":[{"id":"l11-q27","questionNumber":27,"type":"matching","topic":"presentation","estimatedBand":7.5,"prompt":"Delivering the mathematical explanation of self-attention mechanisms.","correctAnswer":"A","explanation":"Marcus confirms he will deliver the mathematical overview of self-attention.","evidence":"Marcus: I will deliver the mathematical overview of self-attention mechanisms"},{"id":"l11-q28","questionNumber":28,"type":"matching","topic":"presentation","estimatedBand":7.5,"prompt":"Demonstrating the live benchmarking software tool.","correctAnswer":"B","explanation":"Anya confirms she will demonstrate the live benchmarking tool.","evidence":"Anya: And I will demonstrate our live benchmarking tool"},{"id":"l11-q29","questionNumber":29,"type":"matching","topic":"presentation","estimatedBand":8,"prompt":"Explaining how high-entropy vector spaces trigger token hallucinations.","correctAnswer":"A","explanation":"Marcus explains hallucinations in high-entropy states.","evidence":"Marcus: explain why hallucinations occur in high-entropy states."},{"id":"l11-q30","questionNumber":30,"type":"matching","topic":"presentation","estimatedBand":7,"prompt":"Presenting medical translation case studies in Hindi and Indigenous languages.","correctAnswer":"B","explanation":"Anya showcases real-time error detection on Hindi and Warlpiri medical texts.","evidence":"Anya: showcasing real-time error detection on Hindi and Warlpiri medical texts."}]}]},{"sectionNumber":4,"title":"Academic Lecture: The Atmospheric Physics of Cirrus Cloud Radiative Forcing","contextDescription":"Professor Evelyn Taylor (North American English speaker) delivering an academic meteorology lecture on upper-troposphere ice crystal dynamics and planetary radiative equilibrium.","audioScript":[{"speaker":"Professor Taylor (North American)","text":"Good afternoon, class. Today we examine one of the greatest uncertainties in contemporary planetary climate modeling: the dual radiative forcing of cirrus clouds. Floating in the frigid upper troposphere between eight and sixteen kilometers above sea level, cirrus clouds are composed entirely of non-spherical ice crystals. Unlike low-altitude marine stratocumulus clouds—which exert a powerful net cooling effect by reflecting incoming shortwave solar radiation back into space—cirrus clouds exert a complex, competing radiative influence on Earth's energy budget."},{"speaker":"Professor Taylor (North American)","text":"Cirrus clouds are semi-transparent to incoming solar radiation, possessing low optical depth that allows most shortwave sunlight to penetrate through to the Earth's surface. However, they are exceptionally effective at absorbing outgoing longwave infrared radiation emitted by the warm planet. Because cirrus cloud tops are extremely cold—often minus fifty to minus sixty degrees Celsius—they re-emit longwave radiation into space at a much lower intensity than the warm surface beneath. Consequently, cirrus clouds act as a thermal greenhouse blanket, trapping heat in the troposphere."},{"speaker":"Professor Taylor (North American)","text":"The critical parameter governing whether a cirrus cloud warms or cools the planet is ice crystal habit and effective particle size. When cirrus clouds form through homogeneous nucleation—where microscopic water droplets freeze spontaneously without foreign nuclei—they produce vast quantities of tiny hexagonal ice crystals under twenty micrometers in diameter, which strongly enhances infrared absorption and net planetary warming."},{"speaker":"Professor Taylor (North American)","text":"This microphysical mechanism intersects directly with commercial aviation. High-altitude aircraft jet engines emit hot exhaust containing water vapor, soot, and aerosol sulfates. In ice-supersaturated air, these soot particles trigger contrail-induced cirrus clouds. Atmospheric physicists calculate that the net radiative warming caused by aviation-induced cirrus clouds actually exceeds the cumulative climate warming produced by all the carbon dioxide emitted by commercial aircraft engines since the beginning of aviation history."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l11-q31","questionNumber":31,"type":"sentence_completion","topic":"meteorology","estimatedBand":7,"prompt":"Cirrus clouds form in the upper troposphere between 8 and ____ kilometers above Earth.","correctAnswer":["16","sixteen"],"explanation":"Professor Taylor states between eight and sixteen kilometers above sea level.","evidence":"upper troposphere between eight and sixteen kilometers above sea level"},{"id":"l11-q32","questionNumber":32,"type":"sentence_completion","topic":"physics","estimatedBand":7,"prompt":"Cirrus clouds are composed entirely of microscopic ____ crystals.","correctAnswer":"ice","explanation":"Professor Taylor states cirrus clouds are composed entirely of non-spherical ice crystals.","evidence":"cirrus clouds are composed entirely of non-spherical ice crystals."},{"id":"l11-q33","questionNumber":33,"type":"sentence_completion","topic":"meteorology","estimatedBand":7.5,"prompt":"Unlike cirrus, low-altitude stratocumulus clouds exert a strong net ____ effect.","correctAnswer":"cooling","explanation":"Professor Taylor contrasts them with low-altitude clouds which exert a powerful net cooling effect.","evidence":"which exert a powerful net cooling effect by reflecting incoming shortwave solar radiation"},{"id":"l11-q34","questionNumber":34,"type":"sentence_completion","topic":"radiation","estimatedBand":7.5,"prompt":"Cirrus clouds have low optical depth, allowing ____ sunlight to pass through.","correctAnswer":"shortwave","explanation":"Professor Taylor notes they allow most shortwave sunlight to penetrate.","evidence":"allows most shortwave sunlight to penetrate through to the Earth's surface."},{"id":"l11-q35","questionNumber":35,"type":"sentence_completion","topic":"radiation","estimatedBand":7.5,"prompt":"They trap heat by absorbing outgoing longwave ____ radiation from the surface.","correctAnswer":"infrared","explanation":"Professor Taylor notes they absorb outgoing longwave infrared radiation.","evidence":"exceptionally effective at absorbing outgoing longwave infrared radiation emitted by the warm planet."},{"id":"l11-q36","questionNumber":36,"type":"sentence_completion","topic":"temperature","estimatedBand":7,"prompt":"Cloud tops reach temperatures as low as minus ____ degrees Celsius.","correctAnswer":["60","sixty"],"explanation":"Professor Taylor mentions minus fifty to minus sixty degrees Celsius.","evidence":"often minus fifty to minus sixty degrees Celsius—they re-emit longwave radiation"},{"id":"l11-q37","questionNumber":37,"type":"sentence_completion","topic":"physics","estimatedBand":8,"prompt":"Spontaneous freezing without foreign particles is called ____ nucleation.","correctAnswer":"homogeneous","explanation":"Professor Taylor defines homogeneous nucleation.","evidence":"cirrus clouds form through homogeneous nucleation—where microscopic water droplets freeze spontaneously"},{"id":"l11-q38","questionNumber":38,"type":"sentence_completion","topic":"optics","estimatedBand":7.5,"prompt":"High warming occurs when ice crystals are smaller than ____ micrometers.","correctAnswer":["20","twenty"],"explanation":"Professor Taylor states tiny crystals under twenty micrometers enhance warming.","evidence":"tiny hexagonal ice crystals under twenty micrometers in diameter"},{"id":"l11-q39","questionNumber":39,"type":"sentence_completion","topic":"aviation","estimatedBand":7.5,"prompt":"Aircraft engines emit water vapor, aerosol sulfates, and ____ particles.","correctAnswer":"soot","explanation":"Professor Taylor lists water vapor, soot, and aerosol sulfates.","evidence":"hot exhaust containing water vapor, soot, and aerosol sulfates."},{"id":"l11-q40","questionNumber":40,"type":"sentence_completion","topic":"climate","estimatedBand":8,"prompt":"Aviation-induced cirrus clouds produce more warming than all aircraft engine ____ emissions.","correctAnswer":"carbon dioxide","explanation":"Professor Taylor states warming exceeds cumulative carbon dioxide emitted by commercial aircraft.","evidence":"exceeds the cumulative climate warming produced by all the carbon dioxide emitted by commercial aircraft engines"}]}]}]`),_e={id:Q,title:Z,difficulty:X,timeLimitMinutes:ee,sections:te},ie="list-test-12",ne="Listening Practice Test 12",re="medium",oe=40,ae=JSON.parse(`[{"sectionNumber":1,"title":"Community Sports Pavilion Tennis Court Membership","contextDescription":"Priya (Indian English speaker) enquiring with Sports Pavilion Manager Liam (Australian English speaker) about joining the local tennis and squash club.","audioScript":[{"speaker":"Liam (Australian)","text":"Good morning! Westside Community Sports Pavilion. Liam speaking."},{"speaker":"Priya (Indian English)","text":"Hello Liam! My name is Priya Sharma. I recently moved to the area and would love to register for an annual tennis club membership."},{"speaker":"Liam (Australian)","text":"No worries, Priya! We have both outdoor floodlit synthetic grass courts and indoor squash courts. Let me take down your contact details."},{"speaker":"Priya (Indian English)","text":"Certainly. My first name is Priya, P-R-I-Y-A, and surname Sharma, S-H-A-R-M-A."},{"speaker":"Liam (Australian)","text":"Thank you, Priya. And your home address?"},{"speaker":"Priya (Indian English)","text":"I reside at sixty-three Acacia Crescent, Perth, postcode six zero零eight—that is six zero zero eight."},{"speaker":"Liam (Australian)","text":"Six zero zero eight. And a contact mobile number?"},{"speaker":"Priya (Indian English)","text":"It is zero four nine nine, eight seven six five four three."},{"speaker":"Liam (Australian)","text":"Got it. Now regarding our membership packages, our Individual Full Adult pass is fifty-five dollars per month, or five hundred and fifty dollars if paid annually upfront, which gives you two months free."},{"speaker":"Priya (Indian English)","text":"I will take the annual upfront payment for five hundred and fifty dollars. Does that fee include nighttime floodlight tokens?"},{"speaker":"Liam (Australian)","text":"Yes, annual members receive fifty complimentary digital lighting tokens loaded onto their electronic access card. Additional tokens can be topped up via our mobile app for two dollars per hour."},{"speaker":"Priya (Indian English)","text":"That is very convenient. What footwear regulations apply to the synthetic grass courts?"},{"speaker":"Liam (Australian)","text":"All players must wear non-marking rubber court shoes with flat herringbone tread; running shoes with aggressive black cleat soles are strictly banned to prevent tearing the artificial turf fibers."},{"speaker":"Priya (Indian English)","text":"Understood. When does the beginner-intermediate social doubles round-robin meet?"},{"speaker":"Liam (Australian)","text":"Every Thursday evening at seven PM. You can simply turn up and our club coach organizes matched pairs."},{"speaker":"Priya (Indian English)","text":"Thursday at seven PM. Thank you so much, Liam! I will pop in tomorrow to pay and collect my access card."}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l12-q1","questionNumber":1,"type":"sentence_completion","topic":"customer enquiry","estimatedBand":5.5,"prompt":"Applicant surname: ____","correctAnswer":"Sharma","explanation":"Priya spells her surname: S-H-A-R-M-A.","evidence":"surname Sharma, S-H-A-R-M-A."},{"id":"l12-q2","questionNumber":2,"type":"sentence_completion","topic":"address","estimatedBand":5.5,"prompt":"Address: 63 ____ Crescent, Perth.","correctAnswer":"Acacia","explanation":"Priya states: sixty-three Acacia Crescent.","evidence":"sixty-three Acacia Crescent, Perth"},{"id":"l12-q3","questionNumber":3,"type":"sentence_completion","topic":"postcode","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["6008","six zero zero eight"],"explanation":"Priya confirms: six zero zero eight.","evidence":"postcode six zero zero eight."},{"id":"l12-q4","questionNumber":4,"type":"sentence_completion","topic":"telephone","estimatedBand":5.5,"prompt":"Mobile telephone: 0499 ____","correctAnswer":"876543","explanation":"Priya states: zero four nine nine, eight seven six five four three.","evidence":"zero four nine nine, eight seven six five four three."},{"id":"l12-q5","questionNumber":5,"type":"sentence_completion","topic":"finance","estimatedBand":6,"prompt":"Upfront annual membership price: $____","correctAnswer":["550","five hundred and fifty"],"explanation":"Liam states five hundred and fifty dollars if paid annually.","evidence":"five hundred and fifty dollars if paid annually upfront"},{"id":"l12-q6","questionNumber":6,"type":"sentence_completion","topic":"facilities","estimatedBand":6,"prompt":"Members receive ____ free digital lighting tokens per year.","correctAnswer":["50","fifty"],"explanation":"Liam confirms fifty complimentary digital lighting tokens.","evidence":"receive fifty complimentary digital lighting tokens"},{"id":"l12-q7","questionNumber":7,"type":"sentence_completion","topic":"sports gear","estimatedBand":6.5,"prompt":"Court shoes must feature a flat ____ tread pattern.","correctAnswer":"herringbone","explanation":"Liam specifies flat herringbone tread.","evidence":"rubber court shoes with flat herringbone tread"},{"id":"l12-q8","questionNumber":8,"type":"sentence_completion","topic":"sports rules","estimatedBand":6.5,"prompt":"Footwear with black ____ soles is prohibited.","correctAnswer":"cleat","explanation":"Liam states shoes with aggressive black cleat soles are banned.","evidence":"aggressive black cleat soles are strictly banned to prevent tearing"},{"id":"l12-q9","questionNumber":9,"type":"sentence_completion","topic":"schedule","estimatedBand":6,"prompt":"Social doubles night takes place every ____ evening.","correctAnswer":"Thursday","explanation":"Liam notes every Thursday evening at seven PM.","evidence":"Every Thursday evening at seven PM."},{"id":"l12-q10","questionNumber":10,"type":"sentence_completion","topic":"time","estimatedBand":5.5,"prompt":"Round-robin session starting time: ____ PM.","correctAnswer":["7","seven","7:00"],"explanation":"Liam states starting time is seven PM.","evidence":"at seven PM. You can simply turn up"}]}]},{"sectionNumber":2,"title":"Guided Audio Tour of the Historic Port Docks and Maritime Museum","contextDescription":"Captain Roberts (British RP speaker) narrating a walking audio tour of the historic Royal Albert Maritime Docks and dry dock basin.","audioScript":[{"speaker":"Captain Roberts (British)","text":"Welcome to the Royal Albert Maritime Heritage Quays. I am Captain David Roberts. Constructed in 1846 during the height of the Industrial Revolution, these enclosed brick and granite wet docks once handled over forty percent of the British Empire's international maritime trade, receiving spice clippers from the East Indies and timber schooners from the Baltic."},{"speaker":"Captain Roberts (British)","text":"Today, our restored twenty-hectare historic basin serves as a living open-air maritime museum. As you follow the dockside cobblestone perimeter, refer to the numbered stations on your visitor map. We begin at the Dockmaster's Watchtower on the southern quay. Directly ahead to the northwest at location A is the 1854 Hydraulic Pumping Station. Here, two massive coal-fired steam engines pumped high-pressure hydraulic fluid through miles of cast-iron pipes to operate forty-eight dockside cargo cranes and open thirty-ton lock gates in less than two minutes."},{"speaker":"Captain Roberts (British)","text":"Proceeding northward along the inner quay, location B marks the Graving Dry Dock. In this hollowed granite basin, water was pumped out to expose ship keels for hull caulking and copper plating. Inside rests the fully rigged three-masted tea clipper SS Falcon, launched in 1872."},{"speaker":"Captain Roberts (British)","text":"Continuing past the dry dock to location C on the eastern basin wall is the Victorian Spiceries & Bonded Warehouse. The heavy iron fire shutters and unmortared air vents were designed to keep precious cargoes of cinnamon, nutmeg, and vanilla cool and rodent-free."},{"speaker":"Captain Roberts (British)","text":"Finally, at the far northeastern tip of the pier, marked as location D, is our Traditional Rigging & Sailmaking Loft. Master craftsmen demonstrate the ancient art of hand-splicing wire rope and stitching heavy flax canvas sails using traditional bone fids and palm thimbles."},{"speaker":"Captain Roberts (British)","text":"Please mind the deep water edge along the quayside, as historic granite coping stones lack safety guardrails to maintain historic authenticity. Enjoy your maritime voyage back into Victorian history!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l12-q11","questionNumber":11,"type":"multiple_choice_single","topic":"history","estimatedBand":6,"prompt":"The Royal Albert wet docks were originally constructed in","options":["1750.","1912.","1846."],"correctAnswer":"C","explanation":"Captain Roberts notes docks were constructed in 1846.","evidence":"Constructed in 1846 during the height of the Industrial Revolution"},{"id":"l12-q12","questionNumber":12,"type":"multiple_choice_single","topic":"trade","estimatedBand":6.5,"prompt":"At their peak, the docks handled what percentage of British maritime trade?","options":["Over 40%.","Approximately 25%.","Nearly 75%."],"correctAnswer":"A","explanation":"Captain Roberts states docks handled over forty percent of trade.","evidence":"once handled over forty percent of the British Empire's international maritime trade"},{"id":"l12-q13","questionNumber":13,"type":"multiple_choice_single","topic":"engineering","estimatedBand":7,"prompt":"Hydraulic pressure was used to operate","options":["streetlamps and clock towers.","cargo cranes and thirty-ton lock gates.","steam locomotives."],"correctAnswer":"B","explanation":"Captain Roberts states hydraulic fluid operated forty-eight cranes and lock gates.","evidence":"operate forty-eight dockside cargo cranes and open thirty-ton lock gates in less than two minutes."},{"id":"l12-q14","questionNumber":14,"type":"multiple_choice_single","topic":"ships","estimatedBand":6.5,"prompt":"The historic ship preserved in the dry dock is the","options":["HMS Victory.","Cutty Sark.","SS Falcon."],"correctAnswer":"C","explanation":"Captain Roberts identifies the SS Falcon, launched in 1872.","evidence":"Inside rests the fully rigged three-masted tea clipper SS Falcon, launched in 1872."},{"id":"l12-q15","questionNumber":15,"type":"multiple_choice_single","topic":"architecture","estimatedBand":7,"prompt":"The Victorian warehouse preserved spices by using unmortared air vents and","options":["heavy iron fire shutters.","ice blocks shipped from Norway.","subterranean water channels."],"correctAnswer":"A","explanation":"Captain Roberts mentions heavy iron fire shutters and unmortared air vents.","evidence":"heavy iron fire shutters and unmortared air vents were designed to keep precious cargoes"},{"id":"l12-q16","questionNumber":16,"type":"multiple_choice_single","topic":"safety","estimatedBand":6,"prompt":"Why are there no safety guardrails along the quayside?","options":["To save municipal construction costs.","To preserve authentic historic appearance.","To allow ships to dock anywhere."],"correctAnswer":"B","explanation":"Captain Roberts explains stones lack guardrails to maintain historic authenticity.","evidence":"historic granite coping stones lack safety guardrails to maintain historic authenticity."}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l12-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"1854 Hydraulic Pumping Station: Location ____","correctAnswer":"A","explanation":"Captain Roberts indicates location A to the northwest as the Pumping Station.","evidence":"Directly ahead to the northwest at location A is the 1854 Hydraulic Pumping Station."},{"id":"l12-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Graving Dry Dock: Location ____","correctAnswer":"B","explanation":"Captain Roberts indicates location B along the inner quay as the Graving Dry Dock.","evidence":"Proceeding northward along the inner quay, location B marks the Graving Dry Dock."},{"id":"l12-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":7,"prompt":"Victorian Spiceries & Bonded Warehouse: Location ____","correctAnswer":"C","explanation":"Captain Roberts indicates location C on the eastern basin wall as the Warehouse.","evidence":"past the dry dock to location C on the eastern basin wall is the Victorian Spiceries & Bonded Warehouse."},{"id":"l12-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Traditional Rigging & Sailmaking Loft: Location ____","correctAnswer":"D","explanation":"Captain Roberts indicates location D at the northeastern tip of the pier.","evidence":"northeastern tip of the pier, marked as location D, is our Traditional Rigging & Sailmaking Loft."}]}]},{"sectionNumber":3,"title":"Postgraduate Project Tutorial on Ocean Thermal Energy Conversion (OTEC)","contextDescription":"Renewable energy professor Dr. Samuel Wright (North American English) discussing thermodynamics with graduate researchers Deepak (Indian English) and Chloe (Australian English).","audioScript":[{"speaker":"Dr. Wright (North American)","text":"Good afternoon Deepak, Chloe. Let us examine your engineering design proposal on Ocean Thermal Energy Conversion—or OTEC. Tropical oceans represent Earth's largest natural solar collector, and your thermodynamic modeling on deep-sea water exchange is very promising."},{"speaker":"Chloe (Australian)","text":"Thanks, Dr. Wright. Our project models a closed-cycle OTEC pilot plant situated in Hawaii. The system exploits the natural thermal gradient between warm tropical surface seawater at twenty-five degrees Celsius and cold deep water at four degrees Celsius, pumped from a depth of one thousand meters."},{"speaker":"Deepak (Indian English)","text":"Because the temperature delta is only twenty-one degrees Celsius, water cannot boil directly. Instead, we circulate ammonia as the working fluid, which has a boiling point of minus thirty-three degrees Celsius at standard atmospheric pressure. Warm surface water vaporizes the liquid ammonia into high-pressure vapor, spinning an electrical turbine generator."},{"speaker":"Dr. Wright (North American)","text":"The thermodynamics are sound, but Carnot cycle efficiency is notoriously low—usually only three to four percent. What makes OTEC economically viable despite that low thermal efficiency?"},{"speaker":"Chloe (Australian)","text":"The key economic differentiator is baseload reliability. Unlike intermittent wind and solar photovoltaics, OTEC operates twenty-four hours a day, three hundred and sixty-five days a year, with a capacity factor exceeding ninety percent."},{"speaker":"Deepak (Indian English)","text":"Furthermore, OTEC produces high-value coproducts. The deep ocean water pumped to the surface is pathogen-free and saturated with dissolved nitrates and phosphates. After exiting the condenser, the cold nutrient-rich effluent can be channeled into onshore aquaculture ponds for spirulina algae farming and deep-sea salmon breeding."},{"speaker":"Dr. Wright (North American)","text":"Outstanding integration of circular engineering principles. For Tuesday's seminar, how will you divide your presentation?"},{"speaker":"Chloe (Australian)","text":"I will deliver the thermodynamic turbine cycle calculations and parasitic pumping load modeling."},{"speaker":"Deepak (Indian English)","text":"And I will present the deep-water intake pipe structural design and the commercial aquaculture economics."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l12-q21","questionNumber":21,"type":"multiple_choice_single","topic":"energy","estimatedBand":7,"prompt":"The students' proposed OTEC pilot plant is located in","options":["Iceland.","Scotland.","Hawaii."],"correctAnswer":"C","explanation":"Chloe states the project models a pilot plant situated in Hawaii.","evidence":"models a closed-cycle OTEC pilot plant situated in Hawaii."},{"id":"l12-q22","questionNumber":22,"type":"multiple_choice_single","topic":"thermodynamics","estimatedBand":7,"prompt":"Cold seawater is pumped from what depth beneath the ocean surface?","options":["1,000 meters.","200 meters.","500 meters."],"correctAnswer":"A","explanation":"Chloe states cold water is pumped from a depth of one thousand meters.","evidence":"pumped from a depth of one thousand meters."},{"id":"l12-q23","questionNumber":23,"type":"multiple_choice_single","topic":"chemistry","estimatedBand":7.5,"prompt":"What substance is utilized as the working fluid inside the closed turbine loop?","options":["Pure ethanol.","Liquid ammonia.","Synthetic freon gas."],"correctAnswer":"B","explanation":"Deepak explains they circulate ammonia as the working fluid.","evidence":"we circulate ammonia as the working fluid, which has a boiling point of minus thirty-three"},{"id":"l12-q24","questionNumber":24,"type":"multiple_choice_single","topic":"physics","estimatedBand":7.5,"prompt":"The Carnot thermal conversion efficiency of OTEC systems is typically","options":["15 to 20%.","45 to 50%.","3 to 4%."],"correctAnswer":"C","explanation":"Dr. Wright mentions Carnot efficiency is notoriously low—usually only three to four percent.","evidence":"Carnot cycle efficiency is notoriously low—usually only three to four percent."},{"id":"l12-q25","questionNumber":25,"type":"multiple_choice_single","topic":"energy","estimatedBand":7,"prompt":"The main operational advantage of OTEC over wind and solar power is its","options":["continuous 24/7 baseload reliability.","zero construction cost.","lack of any moving parts."],"correctAnswer":"A","explanation":"Chloe states OTEC operates twenty-four hours a day, 365 days a year with over 90% capacity factor.","evidence":"key economic differentiator is baseload reliability. Unlike intermittent wind and solar photovoltaics, OTEC operates twenty-four hours a day"},{"id":"l12-q26","questionNumber":26,"type":"multiple_choice_single","topic":"aquaculture","estimatedBand":7.5,"prompt":"Deep ocean effluent is valuable for aquaculture because it is cold and rich in","options":["toxic heavy metals.","nitrates and phosphates.","plastic microfibers."],"correctAnswer":"B","explanation":"Deepak notes deep water is pathogen-free and saturated with dissolved nitrates and phosphates.","evidence":"saturated with dissolved nitrates and phosphates. After exiting the condenser, the cold nutrient-rich effluent can be channeled"}]},{"groupInstruction":"Which student is responsible for each presentation component? Write the correct letter, A or B, in boxes 27–30.\\nA: Chloe\\nB: Deepak","questionType":"matching","questions":[{"id":"l12-q27","questionNumber":27,"type":"matching","topic":"presentation","estimatedBand":7,"prompt":"Explaining the 21-degree temperature gradient between surface and deep water.","correctAnswer":"A","explanation":"Chloe presents the temperature delta and depths.","evidence":"Chloe: The system exploits the natural thermal gradient between warm tropical surface seawater at twenty-five degrees Celsius and cold deep water"},{"id":"l12-q28","questionNumber":28,"type":"matching","topic":"presentation","estimatedBand":7.5,"prompt":"Describing the phase transition of liquid ammonia into high-pressure vapor.","correctAnswer":"B","explanation":"Deepak explains circulating ammonia and boiling point dynamics.","evidence":"Deepak: Warm surface water vaporizes the liquid ammonia into high-pressure vapor, spinning an electrical turbine generator."},{"id":"l12-q29","questionNumber":29,"type":"matching","topic":"presentation","estimatedBand":7.5,"prompt":"Calculating parasitic pumping loads and turbine electrical output.","correctAnswer":"A","explanation":"Chloe confirms she will deliver thermodynamic turbine cycle calculations and pumping load modeling.","evidence":"Chloe: I will deliver the thermodynamic turbine cycle calculations and parasitic pumping load modeling."},{"id":"l12-q30","questionNumber":30,"type":"matching","topic":"presentation","estimatedBand":7.5,"prompt":"Presenting the structural engineering of deep-water intake pipes and aquaculture economics.","correctAnswer":"B","explanation":"Deepak confirms he will present intake pipe design and commercial aquaculture.","evidence":"Deepak: And I will present the deep-water intake pipe structural design and the commercial aquaculture economics."}]}]},{"sectionNumber":4,"title":"Academic Lecture: The Archaeology of Neolithic Monumental Architecture at Göbekli Tepe","contextDescription":"Dr. Julian Finch (British English speaker) delivering a university archaeology lecture on monumental megaliths, hunter-gatherer complexity, and social transformation in southeastern Anatolia.","audioScript":[{"speaker":"Dr. Finch (British)","text":"Good afternoon, students. For nearly a century, mainstream archaeological dogma maintained that monumental stone architecture was an exclusive accomplishment of sedentary agrarian civilizations. Under the traditional Vere Gordon Childe paradigm, the sequence was clear: first, humans invented agriculture; farming yielded permanent food surpluses; surpluses enabled labor specialization and permanent villages; and only then could societies mobilize the collective labor needed to quarry, sculpt, and erect massive stone monuments. However, the discovery of Göbekli Tepe in southeastern Turkey has turned that foundational paradigm entirely upside down."},{"speaker":"Dr. Finch (British)","text":"First excavated in 1995 by German archaeologist Dr. Klaus Schmidt, Göbekli Tepe sits atop a limestone ridge near the modern city of Şanlıurfa. Carbon-14 radiocarbon dating of organic matrix collagen establishes that the monumental megalithic enclosures date to approximately nine thousand five hundred BCE—roughly eleven thousand five hundred years ago. This predates Stonehenge by more than six millennia and precedes the construction of the Great Pyramid of Giza by seven thousand years. Crucially, comprehensive botanical and zooarchaeological analysis proves that the builders of Göbekli Tepe were not sedentary farmers; they were nomadic hunter-gatherers living thousands of years before the domestication of wheat, sheep, or cattle."},{"speaker":"Dr. Finch (British)","text":"The architecture itself is breathtaking. The site consists of over twenty circular enclosures, each containing concentric rings of massive T-shaped limestone pillars measuring up to five point five meters in height and weighing between ten and twenty tonnes. These monolithic pillars were quarried from neighboring bedrock using only flint chisels and wooden wedges. Remarkably, the pillars are carved in high relief with intricate bas-relief animal iconography: snarling lions, leaping foxes, wild boars, scorpions, vultures, and headless human figures."},{"speaker":"Dr. Finch (British)","text":"Dr. Schmidt hypothesized that the T-shaped pillars represent stylized anthropomorphic beings: the horizontal crossbeam represents a human head seen in profile, while long human arms and hands carved in relief on the vertical shaft wrap around a belt cinched with an animal loincloth. Göbekli Tepe was not a residential village; archaeologists have discovered no domestic hearths, storage silos, or residential houses. Rather, it served as a regional monumental sanctuary—a prehistoric pilgrimage cathedral. This revelation suggests that religious ritual and monumental myth-making did not follow agriculture; rather, the social imperative to gather hundreds of workers to erect temples forced hunter-gatherers to domesticate wild einkorn wheat in order to feed the construction labor force."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l12-q31","questionNumber":31,"type":"sentence_completion","topic":"archaeology","estimatedBand":7,"prompt":"Göbekli Tepe was first excavated in the year ____ by Dr. Klaus Schmidt.","correctAnswer":"1995","explanation":"Dr. Finch states first excavated in 1995 by Dr. Klaus Schmidt.","evidence":"First excavated in 1995 by German archaeologist Dr. Klaus Schmidt"},{"id":"l12-q32","questionNumber":32,"type":"sentence_completion","topic":"geography","estimatedBand":7,"prompt":"The archaeological site is situated in southeastern ____.","correctAnswer":"Turkey","explanation":"Dr. Finch notes Göbekli Tepe in southeastern Turkey.","evidence":"discovery of Göbekli Tepe in southeastern Turkey has turned that foundational paradigm entirely upside down."},{"id":"l12-q33","questionNumber":33,"type":"sentence_completion","topic":"chronology","estimatedBand":7.5,"prompt":"Radiocarbon dating places the enclosures at around ____ BCE.","correctAnswer":["9500","9,500","nine thousand five hundred"],"explanation":"Dr. Finch notes dates to approximately nine thousand five hundred BCE.","evidence":"date to approximately nine thousand five hundred BCE"},{"id":"l12-q34","questionNumber":34,"type":"sentence_completion","topic":"history","estimatedBand":7.5,"prompt":"The site predates the construction of Stonehenge by over ____ millennia.","correctAnswer":["6","six"],"explanation":"Dr. Finch states predates Stonehenge by more than six millennia.","evidence":"predates Stonehenge by more than six millennia"},{"id":"l12-q35","questionNumber":35,"type":"sentence_completion","topic":"anthropology","estimatedBand":7,"prompt":"The builders of the monumental site were nomadic hunter-____.","correctAnswer":"gatherers","explanation":"Dr. Finch states builders were nomadic hunter-gatherers.","evidence":"builders of Göbekli Tepe were not sedentary farmers; they were nomadic hunter-gatherers"},{"id":"l12-q36","questionNumber":36,"type":"sentence_completion","topic":"architecture","estimatedBand":7.5,"prompt":"The circular enclosures contain large ____-shaped stone pillars.","correctAnswer":"T","explanation":"Dr. Finch notes concentric rings of massive T-shaped limestone pillars.","evidence":"concentric rings of massive T-shaped limestone pillars measuring up to five point five meters"},{"id":"l12-q37","questionNumber":37,"type":"sentence_completion","topic":"dimensions","estimatedBand":7,"prompt":"The largest pillars weigh up to ____ tonnes.","correctAnswer":["20","twenty"],"explanation":"Dr. Finch states weighing between ten and twenty tonnes.","evidence":"measuring up to five point five meters in height and weighing between ten and twenty tonnes."},{"id":"l12-q38","questionNumber":38,"type":"sentence_completion","topic":"tools","estimatedBand":7.5,"prompt":"Pillars were quarried out of bedrock using wooden wedges and ____ chisels.","correctAnswer":"flint","explanation":"Dr. Finch notes using only flint chisels and wooden wedges.","evidence":"quarried from neighboring bedrock using only flint chisels and wooden wedges."},{"id":"l12-q39","questionNumber":39,"type":"sentence_completion","topic":"art","estimatedBand":7.5,"prompt":"Schmidt believed the horizontal stone bar symbolized a human ____.","correctAnswer":"head","explanation":"Dr. Finch states the horizontal crossbeam represents a human head seen in profile.","evidence":"the horizontal crossbeam represents a human head seen in profile"},{"id":"l12-q40","questionNumber":40,"type":"sentence_completion","topic":"agriculture","estimatedBand":8,"prompt":"Feeding temple builders may have sparked the domestication of wild ____ wheat.","correctAnswer":"einkorn","explanation":"Dr. Finch notes forced hunter-gatherers to domesticate wild einkorn wheat.","evidence":"forced hunter-gatherers to domesticate wild einkorn wheat in order to feed the construction labor force."}]}]}]`),ke={id:ie,title:ne,difficulty:re,timeLimitMinutes:oe,sections:ae},se="list-test-13",le="Listening Practice Test 13",ce="hard",de=40,pe=JSON.parse(`[{"sectionNumber":1,"title":"Heritage Orchard Apple Tree Adoption Scheme","contextDescription":"Rohan (Indian English speaker) enquiring with Orchard Coordinator Sarah (British English speaker) about adopting an endangered heritage cider apple tree at the Kent Community Orchard Trust.","audioScript":[{"speaker":"Sarah (British)","text":"Good morning! Kent Heritage Orchard Trust. Sarah speaking."},{"speaker":"Rohan (Indian English)","text":"Good morning, Sarah! My name is Rohan Kapoor. I read an article about your community orchard conservation scheme where local residents can adopt and sponsor a rare heritage fruit tree."},{"speaker":"Sarah (British)","text":"Delighted you called, Rohan! Yes, we safeguard over two hundred endangered Victorian and Georgian apple, pear, and plum varieties. Let me take down your sponsorship registration details."},{"speaker":"Rohan (Indian English)","text":"Wonderful. My first name is Rohan, spelled R-O-H-A-N, and surname Kapoor, K-A-P-O-O-R."},{"speaker":"Sarah (British)","text":"Thank you, Rohan. And what is your postal address?"},{"speaker":"Rohan (Indian English)","text":"It is fifteen Millfield Crescent, Canterbury, postcode C-T-two, eight-J-P."},{"speaker":"Sarah (British)","text":"C-T-two, eight-J-P. And your contact mobile number?"},{"speaker":"Rohan (Indian English)","text":"Yes, it is zero seven seven zero zero, nine zero zero six four one."},{"speaker":"Sarah (British)","text":"Perfect. Now regarding adoption tiers, our standard Tree Guardian sponsorship costs sixty pounds annually. That includes a customized engraved wooden tree plaque, an adoption certificate, and invitations to our seasonal blossom and harvest festivals."},{"speaker":"Rohan (Indian English)","text":"Sixty pounds sounds lovely. Do sponsors also receive a portion of the harvest?"},{"speaker":"Sarah (British)","text":"Yes! Every autumn in October, you are invited to our Harvest Day to personally pick up to twenty kilograms of fresh organic fruit from your adopted tree, plus you receive two bottles of artisanal pressed apple juice."},{"speaker":"Rohan (Indian English)","text":"That is fantastic! What tree variety would you recommend for me?"},{"speaker":"Sarah (British)","text":"I highly recommend the Ashmead's Kernel. It is an extraordinary 1700 Gloucestershire russet variety with intense aromatic pear-drop and hazelnut flavors, and it keeps crisp in cold storage for up to four months."},{"speaker":"Rohan (Indian English)","text":"The Ashmead's Kernel sounds marvelous. When is your next volunteer winter pruning workshop?"},{"speaker":"Sarah (British)","text":"Our master pruner leads a winter restoration session on Saturday, February the eighth, starting at nine thirty AM in the Cider Barn."},{"speaker":"Rohan (Indian English)","text":"Saturday, February the eighth. Thank you so much, Sarah! I will complete the online payment today."}],"questionGroups":[{"groupInstruction":"Complete the form below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 1–10.","questionType":"sentence_completion","questions":[{"id":"l13-q1","questionNumber":1,"type":"sentence_completion","topic":"customer enquiry","estimatedBand":5.5,"prompt":"Sponsor surname: ____","correctAnswer":"Kapoor","explanation":"Rohan spells his surname: K-A-P-O-O-R.","evidence":"surname Kapoor, K-A-P-O-O-R."},{"id":"l13-q2","questionNumber":2,"type":"sentence_completion","topic":"address","estimatedBand":5.5,"prompt":"Address: 15 ____ Crescent, Canterbury.","correctAnswer":"Millfield","explanation":"Rohan states: fifteen Millfield Crescent.","evidence":"fifteen Millfield Crescent, Canterbury"},{"id":"l13-q3","questionNumber":3,"type":"sentence_completion","topic":"postcode","estimatedBand":6,"prompt":"Postcode: ____","correctAnswer":["CT2 8JP","CT28JP"],"explanation":"Rohan gives postcode: C-T-two, eight-J-P.","evidence":"postcode C-T-two, eight-J-P."},{"id":"l13-q4","questionNumber":4,"type":"sentence_completion","topic":"telephone","estimatedBand":5.5,"prompt":"Mobile telephone: 07700 ____","correctAnswer":"900641","explanation":"Rohan gives number: zero seven seven zero zero, nine zero zero six four one.","evidence":"zero seven seven zero zero, nine zero zero six four one."},{"id":"l13-q5","questionNumber":5,"type":"sentence_completion","topic":"finance","estimatedBand":6,"prompt":"Annual Tree Guardian sponsorship: £____","correctAnswer":["60","sixty"],"explanation":"Sarah states sponsorship costs sixty pounds annually.","evidence":"sponsorship costs sixty pounds annually."},{"id":"l13-q6","questionNumber":6,"type":"sentence_completion","topic":"harvest","estimatedBand":6,"prompt":"Sponsors can pick up to ____ kilograms of fruit each autumn.","correctAnswer":["20","twenty"],"explanation":"Sarah confirms picking up to twenty kilograms of fresh fruit.","evidence":"pick up to twenty kilograms of fresh organic fruit"},{"id":"l13-q7","questionNumber":7,"type":"sentence_completion","topic":"botany","estimatedBand":7,"prompt":"Recommended apple variety: Ashmead's ____.","correctAnswer":"Kernel","explanation":"Sarah recommends the Ashmead's Kernel.","evidence":"recommend the Ashmead's Kernel. It is an extraordinary 1700 Gloucestershire russet variety"},{"id":"l13-q8","questionNumber":8,"type":"sentence_completion","topic":"storage","estimatedBand":6.5,"prompt":"This apple can be preserved in cold storage for up to ____ months.","correctAnswer":["4","four"],"explanation":"Sarah states it keeps crisp in cold storage for up to four months.","evidence":"keeps crisp in cold storage for up to four months."},{"id":"l13-q9","questionNumber":9,"type":"sentence_completion","topic":"dates","estimatedBand":6,"prompt":"Winter pruning workshop date: Saturday, February the ____.","correctAnswer":["8th","8","eighth"],"explanation":"Sarah states Saturday, February the eighth.","evidence":"Saturday, February the eighth, starting at nine thirty AM"},{"id":"l13-q10","questionNumber":10,"type":"sentence_completion","topic":"venue","estimatedBand":6.5,"prompt":"Workshop venue: the ____ Barn.","correctAnswer":"Cider","explanation":"Sarah specifies starting at nine thirty AM in the Cider Barn.","evidence":"starting at nine thirty AM in the Cider Barn."}]}]},{"sectionNumber":2,"title":"Orientation for Volunteers at the Coastal Seabird Rehabilitation Sanctuary","contextDescription":"Senior Wildlife Ranger Megan (Australian English speaker) briefing newly inducted volunteer wildlife rescuers at the Penguin and Seabird Marine Hospital.","audioScript":[{"speaker":"Megan (Australian)","text":"G'day team, and welcome to Phillip Island Coastal Seabird Rescue Sanctuary! My name is Megan. Our wildlife hospital treats over one thousand sick, oiled, or injured marine birds every single year—including little penguins, short-tailed shearwaters, and Australasian gannets."},{"speaker":"Megan (Australian)","text":"The greatest acute threat our hospital faces is petroleum contamination from offshore shipping collisions and marine bilge dumping. When a seabird's feathers become coated in toxic heavy fuel oil, the microscopic interlocking barbules of their plumage are destroyed. The feathers lose their natural waterproofing and buoyancy, meaning birds succumb to hypothermia in cold ocean currents within hours or ingest lethal hydrocarbons while desperately trying to preen themselves clean."},{"speaker":"Megan (Australian)","text":"Let's review our sanctuary rehabilitation facility layout. Refer to the site plan on your clipboards. We are currently gathered at the Reception & Triage Gate. If you follow the covered breezeway to location A on the southern wing, you will find our Intensive Washroom & Decontamination Bay. Here, stabilized birds undergo gentle four-stage washing using thirty-eight-degree warm water and specialized mild degreasing detergents."},{"speaker":"Megan (Australian)","text":"Directly north of the washroom at location B is the Infrared Warmth & Drying Cleanroom. Freshly washed birds rest under ceramic infrared heat lamps for six hours to thoroughly dry their down plumage without causing thermal stress."},{"speaker":"Megan (Australian)","text":"Location C on the eastern perimeter marks our Saltwater Conditioning Pools. These deep, filtered seawater exercise flumes allow recovering penguins to swim continuously, preening their feathers to re-establish their natural waterproofing oil layer before release."},{"speaker":"Megan (Australian)","text":"Finally, at location D beside the coastal dunes is our Pre-Release Acclimatization Aviary. Here, birds are evaluated for dive endurance and live fish foraging agility."},{"speaker":"Megan (Australian)","text":"Safety note for all volunteers: seabirds possess razor-sharp beaks. Thick neoprene forearm gauntlets and protective eye goggles must be worn whenever handling gannets or cormorants. Let's get started!"}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 11–16.","questionType":"multiple_choice_single","questions":[{"id":"l13-q11","questionNumber":11,"type":"multiple_choice_single","topic":"wildlife","estimatedBand":6,"prompt":"The seabird hospital treats approximately how many marine birds each year?","options":["250.","500.","Over 1,000."],"correctAnswer":"C","explanation":"Megan states the hospital treats over one thousand sick or injured marine birds every year.","evidence":"treats over one thousand sick, oiled, or injured marine birds every single year"},{"id":"l13-q12","questionNumber":12,"type":"multiple_choice_single","topic":"biology","estimatedBand":7,"prompt":"Fuel oil is deadly to seabirds primarily because it destroys their plumage's","options":["waterproofing and buoyancy.","color pigments.","flight muscle bone structure."],"correctAnswer":"A","explanation":"Megan explains feathers lose their natural waterproofing and buoyancy, causing hypothermia.","evidence":"The feathers lose their natural waterproofing and buoyancy, meaning birds succumb to hypothermia"},{"id":"l13-q13","questionNumber":13,"type":"multiple_choice_single","topic":"veterinary","estimatedBand":7,"prompt":"Oiled birds are washed in warm water maintained at what temperature?","options":["25°C.","38°C.","45°C."],"correctAnswer":"B","explanation":"Megan specifies washing using thirty-eight-degree warm water.","evidence":"washing using thirty-eight-degree warm water and specialized mild degreasing detergents."},{"id":"l13-q14","questionNumber":14,"type":"multiple_choice_single","topic":"treatment","estimatedBand":6.5,"prompt":"How long do washed birds remain in the infrared drying cleanroom?","options":["2 hours.","24 hours.","6 hours."],"correctAnswer":"C","explanation":"Megan states birds rest under heat lamps for six hours.","evidence":"rest under ceramic infrared heat lamps for six hours to thoroughly dry their down plumage"},{"id":"l13-q15","questionNumber":15,"type":"multiple_choice_single","topic":"rehabilitation","estimatedBand":7,"prompt":"Penguins swim in saltwater conditioning pools to","options":["re-establish their natural waterproofing oil layer through preening.","socialize with tourist visitors.","lay eggs."],"correctAnswer":"A","explanation":"Megan explains swimming allows penguins to preen and re-establish their natural oil layer.","evidence":"preening their feathers to re-establish their natural waterproofing oil layer before release."},{"id":"l13-q16","questionNumber":16,"type":"multiple_choice_single","topic":"safety","estimatedBand":6,"prompt":"What protective equipment must volunteers wear when handling gannets?","options":["Leather aprons and steel boots.","Neoprene forearm gauntlets and eye goggles.","Full-face diving masks."],"correctAnswer":"B","explanation":"Megan states neoprene forearm gauntlets and protective eye goggles must be worn.","evidence":"Thick neoprene forearm gauntlets and protective eye goggles must be worn whenever handling gannets"}]},{"groupInstruction":"Label the map below. Write the correct letter, A–D, next to Questions 17–20.","questionType":"diagram_label_completion","questions":[{"id":"l13-q17","questionNumber":17,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Intensive Washroom & Decontamination Bay: Location ____","correctAnswer":"A","explanation":"Megan indicates location A on the southern wing as the Intensive Washroom.","evidence":"location A on the southern wing, you will find our Intensive Washroom & Decontamination Bay."},{"id":"l13-q18","questionNumber":18,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Infrared Warmth & Drying Cleanroom: Location ____","correctAnswer":"B","explanation":"Megan indicates location B directly north of the washroom.","evidence":"Directly north of the washroom at location B is the Infrared Warmth & Drying Cleanroom."},{"id":"l13-q19","questionNumber":19,"type":"diagram_label_completion","topic":"map","estimatedBand":7,"prompt":"Saltwater Conditioning Pools: Location ____","correctAnswer":"C","explanation":"Megan indicates location C on the eastern perimeter as the Saltwater Conditioning Pools.","evidence":"Location C on the eastern perimeter marks our Saltwater Conditioning Pools."},{"id":"l13-q20","questionNumber":20,"type":"diagram_label_completion","topic":"map","estimatedBand":6.5,"prompt":"Pre-Release Acclimatization Aviary: Location ____","correctAnswer":"D","explanation":"Megan indicates location D beside the coastal dunes.","evidence":"Finally, at location D beside the coastal dunes is our Pre-Release Acclimatization Aviary."}]}]},{"sectionNumber":3,"title":"Research Methodology Review: Quantifying Soil Carbon Sequestration Using Satellite Remote Sensing","contextDescription":"Remote sensing professor Dr. Linda Chen (North American English) reviewing satellite data calibration with graduate researchers Alistair (British English) and Kavita (Indian English).","audioScript":[{"speaker":"Dr. Chen (North American)","text":"Good afternoon Alistair, Kavita. Let us review your proposed dissertation methodology on using multi-spectral satellite imagery to quantify soil organic carbon stock across agricultural grasslands."},{"speaker":"Alistair (British)","text":"Thanks, Dr. Chen. Our goal is to replace labor-intensive, destructive manual soil coring with predictive machine learning models driven by European Space Agency Sentinel-2 satellite data and Landsat-9 imagery."},{"speaker":"Kavita (Indian English)","text":"To train our algorithm, we collected three hundred ground-truth soil core samples across forty farms in the Yorkshire Dales. We divided each one-meter core into three depth strata: zero to ten centimeters, ten to thirty centimeters, and thirty to one hundred centimeters. Total organic carbon was measured via dry combustion elemental analysis."},{"speaker":"Dr. Chen (North American)","text":"The ground-truth sampling is robust. But how will you overcome the fundamental limitation of optical satellite remote sensing—namely, that multi-spectral sensors can only measure surface reflectance from bare topsoil, completely blind to carbon beneath vegetative canopies or deeper in the soil column?"},{"speaker":"Alistair (British)","text":"That is where our hybrid feature-fusion model comes in. We combine shortwave infrared surface reflectance with synthetic aperture radar—SAR—from the Sentinel-1 satellite. C-band radar backscatter penetrates vegetation canopies and correlates with soil moisture and surface roughness."},{"speaker":"Kavita (Indian English)","text":"Additionally, we incorporate time-series Normalized Difference Vegetation Index—NDVI—curves over five growing seasons. Peak biomass productivity operates as a mathematical proxy for root exudate carbon inputs into the subterranean profile."},{"speaker":"Dr. Chen (North American)","text":"Very clever. And how will you validate your model's predictive precision?"},{"speaker":"Alistair (British)","text":"We will utilize spatial k-fold cross-validation, reserving twenty percent of our geographic clusters strictly for blind test evaluation. We target an R-squared coefficient of determination above zero point eight."},{"speaker":"Dr. Chen (North American)","text":"Impressive. Ensure your final presentation highlights the international carbon credit verification implications."}],"questionGroups":[{"groupInstruction":"Choose the correct letter, A, B, or C. Write your answers in boxes 21–26.","questionType":"multiple_choice_single","questions":[{"id":"l13-q21","questionNumber":21,"type":"multiple_choice_single","topic":"remote sensing","estimatedBand":7.5,"prompt":"The primary purpose of the students' research is to","options":["measure volcanic ash plumes in the atmosphere.","count the number of cows grazing on farms.","estimate soil carbon using satellite data to reduce physical core sampling."],"correctAnswer":"C","explanation":"Alistair states the goal is to replace manual soil coring with predictive satellite models.","evidence":"replace labor-intensive, destructive manual soil coring with predictive machine learning models driven by European Space Agency Sentinel-2"},{"id":"l13-q22","questionNumber":22,"type":"multiple_choice_single","topic":"soil science","estimatedBand":7,"prompt":"How many ground-truth soil core samples were collected across Yorkshire farms?","options":["300.","100.","600."],"correctAnswer":"A","explanation":"Kavita states they collected three hundred ground-truth soil core samples.","evidence":"we collected three hundred ground-truth soil core samples across forty farms"},{"id":"l13-q23","questionNumber":23,"type":"multiple_choice_single","topic":"remote sensing","estimatedBand":8,"prompt":"What major limitation of optical satellite sensors was identified by Dr. Chen?","options":["They cannot operate in freezing temperatures.","They only capture surface reflectance and cannot see beneath vegetation.","Their batteries run out during night orbits."],"correctAnswer":"B","explanation":"Dr. Chen explains sensors only measure surface reflectance from bare topsoil, blind beneath canopies.","evidence":"multi-spectral sensors can only measure surface reflectance from bare topsoil, completely blind to carbon beneath vegetative canopies"},{"id":"l13-q24","questionNumber":24,"type":"multiple_choice_single","topic":"radar","estimatedBand":7.5,"prompt":"Synthetic Aperture Radar (SAR) is added to the model because radar waves can","options":["measure wind speed over oceans.","detect underground gold mines.","penetrate vegetation canopies and evaluate soil moisture."],"correctAnswer":"C","explanation":"Alistair notes C-band radar penetrates vegetation canopies and correlates with soil moisture.","evidence":"C-band radar backscatter penetrates vegetation canopies and correlates with soil moisture and surface roughness."},{"id":"l13-q25","questionNumber":25,"type":"multiple_choice_single","topic":"machine learning","estimatedBand":8,"prompt":"What percentage of geographic clusters is withheld for blind model validation?","options":["20%.","10%.","50%."],"correctAnswer":"A","explanation":"Alistair states reserving twenty percent of geographic clusters strictly for blind test evaluation.","evidence":"reserving twenty percent of our geographic clusters strictly for blind test evaluation."},{"id":"l13-q26","questionNumber":26,"type":"multiple_choice_single","topic":"statistics","estimatedBand":7.5,"prompt":"The researchers target a coefficient of determination (R-squared) above","options":["0.5.","0.8.","0.95."],"correctAnswer":"B","explanation":"Alistair states: 'target an R-squared coefficient of determination above zero point eight.'","evidence":"target an R-squared coefficient of determination above zero point eight."}]},{"groupInstruction":"Which student proposed or explained each methodology component? Write the correct letter, A or B, in boxes 27–30.\\nA: Alistair\\nB: Kavita","questionType":"matching","questions":[{"id":"l13-q27","questionNumber":27,"type":"matching","topic":"methodology","estimatedBand":7,"prompt":"Proposing Sentinel-2 and Landsat-9 satellite imagery as the primary optical data source.","correctAnswer":"A","explanation":"Alistair presents using Sentinel-2 and Landsat-9 imagery.","evidence":"Alistair: driven by European Space Agency Sentinel-2 satellite data and Landsat-9 imagery."},{"id":"l13-q28","questionNumber":28,"type":"matching","topic":"methodology","estimatedBand":7.5,"prompt":"Describing the three-layer soil coring depths and dry combustion carbon analysis.","correctAnswer":"B","explanation":"Kavita explains the three depth strata and dry combustion analysis.","evidence":"Kavita: divided each one-meter core into three depth strata... measured via dry combustion elemental analysis."},{"id":"l13-q29","questionNumber":29,"type":"matching","topic":"methodology","estimatedBand":8,"prompt":"Integrating Sentinel-1 radar backscatter to overcome canopy obstruction.","correctAnswer":"A","explanation":"Alistair explains combining optical data with Sentinel-1 SAR.","evidence":"Alistair: We combine shortwave infrared surface reflectance with synthetic aperture radar—SAR—from the Sentinel-1 satellite."},{"id":"l13-q30","questionNumber":30,"type":"matching","topic":"methodology","estimatedBand":7.5,"prompt":"Explaining multi-year NDVI curves as a proxy for root exudate carbon.","correctAnswer":"B","explanation":"Kavita explains using 5-year NDVI curves to estimate root exudate carbon.","evidence":"Kavita: incorporate time-series Normalized Difference Vegetation Index—NDVI—curves... proxy for root exudate carbon inputs"}]}]},{"sectionNumber":4,"title":"Academic Lecture: The Evolution of Human Sleep Architecture and Circadian Photobiology","contextDescription":"Professor Alan Drummond (Scottish / British English speaker) delivering a university evolutionary physiology lecture on sleep architecture, REM cycles, and blue-light circadian disruption.","audioScript":[{"speaker":"Professor Drummond (Scottish/British)","text":"Good afternoon, class. Today we examine human sleep architecture through the dual lenses of evolutionary anthropology and circadian photobiology. Among terrestrial mammals, human sleep represents a profound evolutionary enigma. Non-human primates, such as chimpanzees, baboons, and orangutans, sleep between ten and fifteen hours every day. In stark contrast, anatomically modern humans sleep for a consolidated average of only seven hours per night. Yet, despite sleeping significantly fewer hours, humans exhibit vastly superior cognitive flexibility, working memory capacity, and executive problem-solving skills."},{"speaker":"Professor Drummond (Scottish/British)","text":"The solution to this paradox lies not in sleep quantity, but in sleep intensity and architectural composition. Human sleep is remarkably enriched in rapid eye movement—or REM—sleep. In typical adult humans, REM sleep comprises nearly twenty-five percent of total sleep duration, compared to a meager five to nine percent in our closest great ape relatives. Evolutionary anthropologists hypothesize that when human ancestors descended from arboreal canopies to sleep on the ground around terrestrial campfires, the threat of nocturnal mammalian predators created intense evolutionary selection for highly condensed, ultra-efficient sleep cycles."},{"speaker":"Professor Drummond (Scottish/British)","text":"At the molecular level, circadian rhythms are orchestrated by the suprachiasmatic nucleus—the SCN—a pair of pinhead-sized structures containing twenty thousand neurons situated in the anterior hypothalamus. The primary environmental zeitgeber—or time-giver—synchronizing the SCN is daylight. In the early 2000s, neurobiologists discovered intrinsically photosensitive retinal ganglion cells—ipRGCs—in the human eye. These specialized photoreceptors do not contribute to conscious image vision; instead, they contain the photopigment melanopsin, which is maximally sensitive to high-frequency blue light at wavelengths between four hundred and sixty and four hundred and eighty nanometers."},{"speaker":"Professor Drummond (Scottish/British)","text":"When morning sunlight hits ipRGCs, electrical signals travel along the retinohypothalamic tract to the SCN, which suppresses melatonin synthesis in the pineal gland, promoting alertness and metabolic vigor. In modern societies, however, pervasive nocturnal exposure to blue-enriched light emitted by smartphones, laptop screens, and solid-state LED bulbs severely disrupts this photobiological clock. Evening blue light tricks the SCN into perceiving daylight, delaying nocturnal melatonin surge by upwards of two hours, fragmenting slow-wave delta sleep, and exacerbating systemic chronic metabolic disorders."}],"questionGroups":[{"groupInstruction":"Complete the notes below. Write NO MORE THAN TWO WORDS AND/OR A NUMBER for each answer. Write your answers in boxes 31–40.","questionType":"sentence_completion","questions":[{"id":"l13-q31","questionNumber":31,"type":"sentence_completion","topic":"biology","estimatedBand":6.5,"prompt":"Non-human primates sleep between 10 and ____ hours daily.","correctAnswer":["15","fifteen"],"explanation":"Professor Drummond states primates sleep between ten and fifteen hours every day.","evidence":"sleep between ten and fifteen hours every day."},{"id":"l13-q32","questionNumber":32,"type":"sentence_completion","topic":"physiology","estimatedBand":6.5,"prompt":"Modern humans sleep for a consolidated average of ____ hours each night.","correctAnswer":["7","seven"],"explanation":"Professor Drummond notes humans sleep an average of only seven hours per night.","evidence":"consolidated average of only seven hours per night."},{"id":"l13-q33","questionNumber":33,"type":"sentence_completion","topic":"sleep","estimatedBand":7,"prompt":"In adult humans, REM sleep makes up approximately ____ percent of total sleep.","correctAnswer":["25","twenty-five"],"explanation":"Professor Drummond states REM sleep comprises nearly twenty-five percent.","evidence":"REM sleep comprises nearly twenty-five percent of total sleep duration"},{"id":"l13-q34","questionNumber":34,"type":"sentence_completion","topic":"evolution","estimatedBand":7.5,"prompt":"Condensed sleep evolved when human ancestors began sleeping around terrestrial ____.","correctAnswer":"campfires","explanation":"Professor Drummond mentions sleeping on the ground around terrestrial campfires.","evidence":"descended from arboreal canopies to sleep on the ground around terrestrial campfires"},{"id":"l13-q35","questionNumber":35,"type":"sentence_completion","topic":"neuroanatomy","estimatedBand":7.5,"prompt":"The master circadian clock is located in the ____ nucleus of the hypothalamus.","correctAnswer":"suprachiasmatic","explanation":"Professor Drummond refers to the suprachiasmatic nucleus (SCN).","evidence":"orchestrated by the suprachiasmatic nucleus—the SCN"},{"id":"l13-q36","questionNumber":36,"type":"sentence_completion","topic":"photobiology","estimatedBand":8,"prompt":"Specialized eye ganglion cells contain the blue-sensitive photopigment ____.","correctAnswer":"melanopsin","explanation":"Professor Drummond states cells contain the photopigment melanopsin.","evidence":"they contain the photopigment melanopsin, which is maximally sensitive to high-frequency blue light"},{"id":"l13-q37","questionNumber":37,"type":"sentence_completion","topic":"physics","estimatedBand":7.5,"prompt":"Melanopsin is most responsive to light wavelengths between 460 and ____ nanometers.","correctAnswer":["480","four hundred and eighty"],"explanation":"Professor Drummond cites wavelengths between 460 and 480 nanometers.","evidence":"between four hundred and sixty and four hundred and eighty nanometers."},{"id":"l13-q38","questionNumber":38,"type":"sentence_completion","topic":"endocrinology","estimatedBand":7.5,"prompt":"Morning light signals suppress the production of ____ in the pineal gland.","correctAnswer":"melatonin","explanation":"Professor Drummond notes suppression of melatonin synthesis in the pineal gland.","evidence":"suppresses melatonin synthesis in the pineal gland, promoting alertness"},{"id":"l13-q39","questionNumber":39,"type":"sentence_completion","topic":"health","estimatedBand":7,"prompt":"Evening smartphone light can delay the melatonin surge by more than ____ hours.","correctAnswer":["2","two"],"explanation":"Professor Drummond states delaying nocturnal melatonin surge by upwards of two hours.","evidence":"delaying nocturnal melatonin surge by upwards of two hours"},{"id":"l13-q40","questionNumber":40,"type":"sentence_completion","topic":"sleep","estimatedBand":8,"prompt":"Night light exposure damages deep slow-wave ____ sleep.","correctAnswer":"delta","explanation":"Professor Drummond notes fragmenting slow-wave delta sleep.","evidence":"fragmenting slow-wave delta sleep, and exacerbating systemic chronic metabolic disorders."}]}]}]`),qe={id:se,title:le,difficulty:ce,timeLimitMinutes:de,sections:pe};export{he as a,me as b,ge as c,ye as d,fe as e,we as f,be as g,ve as h,xe as i,_e as j,ke as k,ue as l,qe as m};
